using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

namespace hehshihbeen_compiler
{
    /// <summary> 综合自检的一部分:多文件编译 / 自举基础 / 寄存器扩充 / 元数据 / 变量 / 类型 / 结构 / 整数边界 / 规模统计。(第88批从 `综合自检C.cs` 按组边界原样搬出,断言一个字没改) </summary>
    public static partial class 综合自检C
    {
        #region 多文件编译 / 自举基础 / 寄存器扩充 / 元数据 / 变量 / 类型 / 结构 / 整数边界 / 规模统计
        // ================= 16) 多文档编译 =================
        private static void 多文件编译自检()
        {
            // 跨文件标签:主文件 调用 子文件里的子程序
            try
            {
                var 码 = new 汇编器C().汇编多文件(
                [
                    ("main.hb", "调用 子程序\n停止\n"),
                    ("sub.hb", "子程序:\n加载立即数 R0, 42\n返回\n"),
                ]);
                var vm = new 虚拟机C();
                vm.运行(码);
                记录("多文件 跨文档 调用标签 R0=42", vm.寄存器[0] == 42, $"R0={vm.寄存器[0]}");
            }
            catch (Exception ex) { 记录异常("多文件 跨文档 调用标签", ex); }

            // 多文件 各自含中间层流程 → 内部 _f 标签不冲突
            try
            {
                string a = "整数 左值 = 1;\n整数 果 = 0;\n如果 (左值 == 1) {\n果 = 7;\n} 否则 {\n果 = 9;\n}\n测试输出(果);\n停止";
                string b = "整数 右值 = 0;\n整数 果2 = 0;\n如果 (右值 == 0) {\n果2 = 5;\n} 否则 {\n果2 = 6;\n}\n";
                var 汇编器 = new 汇编器C();
                var 码 = 汇编器.汇编多文件([("a.hb", a), ("b.hb", b)]);
                记录("多文件 中间层同编(不冲突)", 码.Length > 0, $"长度={码.Length}");
            }
            catch (Exception ex) { 记录异常("多文件 中间层同编", ex); }

            // 标签重复(两个文件定义同名用户标签)→ 报错
            期望异常("多文件 同名用户标签应报错",
                () => new 汇编器C().汇编多文件(
                [
                    ("a.hb", "入口:\n停止"),
                    ("b.hb", "入口:\n停止"),
                ]), "重复");

            // ================= 第94批:工程级符号表(跨文件函数 / 结构 / 全局变量) =================
            // 三文件工程:a(=启动文件,排第一)声明结构与全局并定义函数,b 调用它们,c 用 a 的结构定义函数。
            // 钉三件事:①跨文件**任意顺序**调函数(b 调 c 里的 `挪`)②跨文件共享全局与结构 ③序言只发一份。
            //
            // **顺序口径**:函数有"预扫函数头",结构类型与顶层全局变量也有"声明预扫"(Q1b,见本文件后面那一段),
            // 所以三者跨文件都**不限顺序**;同名照旧报错(带两处位置),要隔离就给文件加 `模块`。
            try
            {
                var 编译 = new 汇编器C().汇编多文件带调试(
                [
                    ("a.hb", "结构 点\n{\n整数 x;\n整数 y;\n}\n整数 计数 = 1;\n方法 加(整数 a, 整数 b) 返回 整数\n{\n返回 a + b;\n}\n方法 取计数() 返回 整数\n{\n返回 计数;\n}\n"),
                    ("b.hb", "整数 二倍计数 = 2;\n方法 调外() 返回 整数\n{\n返回 加(取计数(), 二倍计数);\n}\n点 原点;\n原点.x = 5;\n原点.y = 0;\n测试输出(调外());\n测试输出(挪(原点));\n停止\n"),
                    ("c.hb", "方法 挪(点 p) 返回 整数\n{\n返回 p.x + 计数;\n}\n"),
                ]);
                记录("工程级 三文件一起编译且各有一段调试信息", 编译.机器码.Length > 0 && 编译.调试文件表.Count == 3,
                    $"机器码={编译.机器码.Length} 字节,段数={编译.调试文件表.Count}");

                var vm = new 虚拟机C();
                var 输出 = new StringBuilder();
                vm.输出目标 = b => 输出.Append((char)b);
                vm.运行(编译);
                记录("工程级 跨文件函数/全局/结构跑出 3 与 6", 输出.ToString().Trim() == "3\n6", $"输出=<{输出.ToString().Trim()}>");

                int 序言条数 = 编译.调试文件表.Sum(段 => 段.展开文本.Split('\n').Count(行 => 行.Contains("取地址 R15", StringComparison.Ordinal)));
                记录("工程级 序言只发一份(不再每个文件各发一套 FP/软栈)", 序言条数 == 1, $"取地址 R15 出现 {序言条数} 次");
            }
            catch (Exception ex) { 记录异常("工程级 符号表 跨文件可用", ex); }

            // 反面:跨文件重名必须**报错**,不许静默覆盖(D2 决策)
            期望异常("工程级 两个文件定义同名函数 → 报错",
                () => new 汇编器C().汇编多文件带调试(
                [
                    ("a.hb", "方法 同名() 返回 整数\n{\n返回 1;\n}\n停止\n"),
                    ("b.hb", "方法 同名() 返回 整数\n{\n返回 2;\n}\n"),
                ]), "重复定义");
            期望异常("工程级 两个文件各写同名全局 → 报错",
                () => new 汇编器C().汇编多文件带调试(
                [
                    ("a.hb", "整数 同名 = 1;\n停止\n"),
                    ("b.hb", "整数 同名 = 2;\n"),
                ]), "重复声明");

            // ================= 第94批 Q1b:结构与顶层全局变量的"声明预扫"(不再要求声明在前) =================
            // 三文件工程:结构 `点` 与全局 `计数` 都写在**最后一个文件(c.hb)**里,启动文件(a.hb,排第一)
            // **先用后声明** —— 结构用来声明变量并访问字段,全局先读再经函数读。
            // 预扫只提前"登记名字 + 开数据槽":**初始化代码一个字都不许提前**(所以另有一条顺序钉子)。
            try
            {
                var 顺序文件表 = new List<(string 名称, string 内容)>
                {
                    ("a.hb", "点 原点;\n原点.x = 5;\n原点.y = 6;\n测试输出(原点.x + 原点.y);\n" +
                              "测试输出(计数 + 1);\n测试输出(取计数());\n停止\n"),
                    ("b.hb", "方法 取计数() 返回 整数\n{\n返回 计数;\n}\n"),
                    ("c.hb", "结构 点\n{\n整数 x;\n整数 y;\n}\n整数 计数 = 41;\n"),
                };
                var 顺序编译 = new 汇编器C().汇编多文件带调试(顺序文件表);
                string 实顺序 = 跑多文件(顺序编译);
                记录("Q1b 结构定义在最后一个文件、启动文件先用后声明(声明变量+访问字段)",
                    实顺序.StartsWith("11\n", StringComparison.Ordinal), $"输出=<{实顺序.Replace("\n", "|")}>");
                记录("Q1b 顶层全局定义在最后一个文件、启动文件先读(直接读 + 函数里读)",
                    实顺序 == "11\n42\n41", $"输出=<{实顺序.Replace("\n", "|")}>");
                // 预扫这半条新路上,"双跑字节一致"与"优化开/关结果一致"也不许破
                var 顺序再编译 = new 汇编器C().汇编多文件带调试(顺序文件表);
                string 关优化输出 = 跑多文件(new 汇编器C().汇编多文件带调试(顺序文件表, 优化: false));
                bool 双跑一致 = 顺序再编译.机器码.SequenceEqual(顺序编译.机器码);
                记录("Q1b 声明预扫 双跑字节一致、优化开/关输出一致",
                    双跑一致 && 关优化输出 == 实顺序,
                    $"字节一致={双跑一致} 关优=<{关优化输出.Replace("\n", "|")}>");
            }
            catch (Exception ex) { 记录异常("Q1b 结构与全局的跨文件声明预扫", ex); }

            // 钉子:预扫只"登记名字 / 开槽",初始化代码仍然留在原语句那一句上 ——
            // 一旦有人图省事把初始化搬到程序开头,这里立刻红(b 会变成 1)
            跑输出断言("Q1b 预扫没把初始化代码搬走(整数 a = 1; a = 5; 整数 b = a; → b 是 5)",
                "整数 a = 1;\na = 5;\n整数 b = a;\n测试输出(b);\n停止", "5");
            // 重名照旧报错,而且**两处位置**都要报得出(D2 口径不退化)
            期望异常("Q1b 跨文件重名结构照旧报错(带上一处声明位置)",
                () => new 汇编器C().汇编多文件带调试(
                [
                    ("a.hb", "结构 点\n{\n整数 x;\n}\n停止\n"),
                    ("b.hb", "结构 点\n{\n整数 y;\n}\n"),
                ]), "结构名冲突", "已经有一个同名的");
            期望异常("Q1b 跨文件重名全局照旧报错(带上一处声明位置)",
                () => new 汇编器C().汇编多文件带调试(
                [
                    ("a.hb", "整数 同名 = 1;\n停止\n"),
                    ("b.hb", "整数 同名 = 2;\n"),
                ]), "重复声明", "已经有一个同名的");

            // ================= 第94批(第88节):Q2 `程序集` 可见性(边界 = 单个 `.hbp` 工程) =================
            // 三档:`私有`(同一个 `模块` 里,已有)/ `程序集`(同一个 `.hbp` 工程里,新增;英文 `internal`)/ `公共`(不写,默认)。
            // 夹具用临时目录搭两个真工程:库(自己一个 .hbp)与 程序(把库那份 .hb 列进自己的文件表,子工程指向库)——
            // "库工程 + 借它一起编译的程序工程"就是这个功能真正要挡的场景。
            程序集自检();

            // ================= Q3:调用边表(IDE 侧栏"我调用了谁 / 谁调用了我"的原料;先列表、不画图) =================
            // 扫描器只读**现成的**调试信息(展开文本的源行标记 + 函数范围 + 标签表),不改编译产物一个字。
            调用关系自检();

            // ================= Q4a:未使用函数扫描(只读上面那张调用边表;同样不动机器码一个字) =================
            未使用扫描自检();

            // ================= Q4(核心):重命名**编辑清单**(只算清单 —— 不写盘、不碰编辑器;界面接线见 Q4c) =================
            重命名自检();

            // ================= Q4c:未使用报告 → 诊断项(接进 IDE『问题』页那一层的引擎侧映射) =================
            未使用诊断自检();

            /// <summary> 编译 + 跑多文件工程,收标准输出(Q1b 那几条断言要拿它比优化开/关)</summary>
            static string 跑多文件(汇编调试结果C 编译结果)
            {
                var vm = new 虚拟机C();
                var 输出 = new StringBuilder();
                vm.输出目标 = b => 输出.Append((char)b);
                vm.运行(编译结果);
                return 输出.ToString().Replace("\r\n", "\n").Trim('\n');
            }
        }

        /// <summary>
        /// Q3 调用边表:从现成的编译调试信息里扫"谁调用了谁"(见 `引擎\调用关系扫描C.cs`)。
        /// 钉六件事:①顶层调函数 ②函数调函数 ③递归自调用 ④反向索引(谁调用了 阶乘)
        /// ⑤跨文件边(调用点文件是被调方的**调用方**那个文件)⑥宿主能力 / 编译器内建例程两类分得对,
        /// 外加"同一调用点重复出现去重"与"不在任何函数里的调用只记在顶层名下"。
        /// </summary>
        private static void 调用关系自检()
        {
            try
            {
                // 主.hb:阶乘 递归调自己(第 6 行)、两倍阶乘 同一行写两次 阶乘(b)(第 10 行,该去重成一条)、
                //        顶层调 两倍阶乘(第 13 行)、顶层 `输出行("好")` 走打印串内建例程(第 12 行)、
                //        顶层 `当前时间()` 走宿主能力(第 14 行)。
                // 副.hb:合用 → 阶乘 与 合用 → 两倍阶乘 都是**跨文件边**(调用点在副.hb,被调方在主.hb)。
                const string 主 = "方法 阶乘(整数 a) 返回 整数\n{\n如果 (a <= 1) {\n返回 1;\n}\n返回 a * 阶乘(a - 1);\n}\n" +
                                 "方法 两倍阶乘(整数 b) 返回 整数\n{\n返回 阶乘(b) + 阶乘(b);\n}\n" +
                                 "输出行(\"好\");\n测试输出(两倍阶乘(3));\n整数 时刻 = 当前时间();\n测试输出(时刻);\n停止\n";
                const string 副 = "方法 合用(整数 c) 返回 整数\n{\n返回 阶乘(c) + 两倍阶乘(c - 1);\n}\n";
                var 编译 = new 汇编器C().汇编多文件带调试([("主.hb", 主), ("副.hb", 副)]);
                var 表 = 调用关系扫描C.扫描(编译);

                bool 有条(string 调用者, string 被调定义名, int 行) =>
                    表.调用了谁(调用者).Any(e => e.被调定义名 == 被调定义名 && e.调用点行 == 行);

                记录("调用关系 顶层调用户函数(不在任何函数里 → 顶层)", 有条("", "两倍阶乘", 13),
                    $"顶层出边:{显示(表.调用了谁(""))}");
                记录("调用关系 函数调函数(两倍阶乘 调 阶乘)", 有条("两倍阶乘", "阶乘", 10),
                    $"两倍阶乘出边:{显示(表.调用了谁("两倍阶乘"))}");
                记录("调用关系 递归自调用(阶乘 调 阶乘)", 有条("阶乘", "阶乘", 6),
                    $"阶乘出边:{显示(表.调用了谁("阶乘"))}");

                var 调用者集 = 表.谁调用了("阶乘").Select(e => e.调用者).ToHashSet(StringComparer.Ordinal);
                记录("调用关系 反向索引 谁调用了 阶乘(阶乘自己 / 两倍阶乘 / 合用)", 调用者集.SetEquals(new[] { "阶乘", "两倍阶乘", "合用" }),
                    $"谁调用了 阶乘:{显示(表.谁调用了("阶乘"))}");

                var 跨文件 = 表.谁调用了("阶乘").Where(e => e.调用者 == "合用").ToList();
                记录("调用关系 跨文件边:调用点文件是调用方 副.hb、被调定义名是 主.hb 的 阶乘",
                    跨文件.Count == 1 && 跨文件[0].调用点文件 == "副.hb" && 跨文件[0].调用点行 == 3
                    && 跨文件[0].种类 == 调用种类C.用户函数,
                    跨文件.Count > 0 ? 跨文件[0].ToString() : "（没扫到 合用→阶乘 这条边）");

                var 宿主出边 = 表.调用了谁("").Where(e => e.种类 == 调用种类C.宿主能力).ToList();
                记录("调用关系 宿主能力归到宿主类(当前时间)", 宿主出边.Any(e => e.备注 == "当前时间" && e.调用点行 == 14),
                    宿主出边.Count > 0 ? 显示(宿主出边) : "（没扫到宿主调用）");

                var 内建出边 = 表.调用了谁("").Where(e => e.种类 == 调用种类C.内建函数).ToList();
                记录("调用关系 编译器内建例程归到内建类(输出行 的打印串例程)",
                    内建出边.Any(e => e.调用点行 == 12 && e.备注.Contains("打印", StringComparison.Ordinal)),
                    内建出边.Count > 0 ? 显示(内建出边) : "（没扫到内建例程调用）");

                int 调用条数 = 表.调用了谁("两倍阶乘").Count(e => e.被调定义名 == "阶乘");
                记录("调用关系 同一调用点重复出现只留一条(那一行写了两次 阶乘(b))", 调用条数 == 1, $"两倍阶乘→阶乘 有 {调用条数} 条");

                bool 顶层只挂顶层名 = 表.边表.Where(e => e.调用点行 == 13).All(e => e.在顶层)
                    && 表.调用了谁("").Any(e => e.调用点行 == 13);
                记录("调用关系 不在任何函数里的调用只记在顶层名下(不挂到别的函数上)", 顶层只挂顶层名,
                    $"第 13 行的边:{显示(表.边表.Where(e => e.调用点行 == 13))}");

                var 未知 = 表.边表.Where(e => e.种类 == 调用种类C.未知).ToList();
                记录("调用关系 这个工程没有认不出的标签跳转(用户函数/内建/宿主三类分完)",
                    未知.Count == 0, 未知.Count == 0 ? "全部对上了" : 显示(未知));

                // 手造一段展开文本:钉两件靠"真编译"不好造的事 ——
                // ① `库` 行(语句来自被 `包含` 进来的文件)的行号**不能算到主文件头上**(置 0);
                // ② 只给调试段、不给汇编器标签表时,也能从展开文本里认出内建例程。
                var 手造段 = new 文件映射C
                {
                    文件 = "主.hb",
                    展开文本 = "取地址帧 R14 96   // 来自第 2 行 库\nCALL 阶乘\nMOV R0 R15   // 来自第 9 行\nCALL 两倍阶乘\n_f内建1:\nCALL _f内建1   // 来自第 11 行\n",
                    名字表 = new 名字表C { 函数范围 = [("阶乘", 1, 5, "主.hb"), ("两倍阶乘", 7, 15, "主.hb")] },
                };
                var 手造表 = 调用关系扫描C.扫描([手造段]);
                bool 库行置零 = 手造表.边表.Any(e => e.被调定义名 == "阶乘" && e.调用点行 == 0 && e.是库行)
                    && !手造表.边表.Any(e => e.调用点行 == 2);
                记录("调用关系 库行(包含进来的文件)的行号不落到主文件上(记 0 并标出是库行)", 库行置零,
                    $"手造边表:{显示(手造表.边表)}");
                记录("调用关系 不给标签表也能从展开文本认出内建例程(只有调试段也能扫)",
                    手造表.边表.Any(e => e.被调标签 == "_f内建1" && e.种类 == 调用种类C.内建函数),
                    $"手造边表:{显示(手造表.边表)}");

                // H6(第244批):生成代码一律**没有源行** —— 展开文本里那句 `// 编译器生成`
                // (第136批加的)之后、下一个真标记之前的那一段,行号按"不知道"算;
                // 不这么算,生成区里真发一条 `调用` 时就会沿用**上一条真语句**的行号,
                // 面板上冒出一条"某函数在第 N 行调用了 `_fheapalloc…`"的假边。
                var 生成段 = new 文件映射C
                {
                    文件 = "主.hb",
                    展开文本 = "CALL 阶乘   // 来自第 4 行\n" + 源行标记C.生成标记 + "\nCALL _fheapalloc1\n" +
                        "取地址帧 R14 96   // 来自第 9 行\nCALL 两倍阶乘\n",
                    名字表 = new 名字表C { 函数范围 = [("阶乘", 1, 5, "主.hb"), ("两倍阶乘", 7, 15, "主.hb")] },
                };
                var 生成表 = 调用关系扫描C.扫描([生成段]);
                记录("调用关系 生成代码里的调用不沾上一条真语句的行号(生成标记之后一律无源行)",
                    生成表.边表.Any(e => e.被调标签 == "_fheapalloc1" && e.调用点行 == 0 && e.在顶层)
                    && !生成表.边表.Any(e => e.被调标签 == "_fheapalloc1" && e.调用点行 == 4),
                    $"生成段边表:{显示(生成表.边表)}");

                // 上面那条口径的**原料**确实会出现在真编译产物里(不然就是空转):真编一份
                // "函数里要堆 + 顶层动态列表"的小程序,展开文本里 `// 编译器生成` 至少 2 处
                // (程序开头的初始化 + 列表扩容与堆这些内部例程)。
                const string 生成源 = "方法 要块(整数 n) 返回 地址\n{\n地址 p = 申请(n);\n返回 p;\n}\n" +
                    "整数 表[];\n表.添加(1);\n地址 q = 要块(8);\n释放(q);\n测试输出(表.长度());\n停止\n";
                var 生成编译 = new 汇编器C().汇编多文件带调试([("主.hb", 生成源)]);
                int 生成标记数 = 生成编译.调试文件表.Sum(段 =>
                    (段.展开文本 ?? "").Split('\n').Count(行 => 源行标记C.读(行).生成));
                记录("调用关系 真编产物里确有 `编译器生成` 标记(生成区无源行这条口径有原料)", 生成标记数 >= 2,
                    $"展开文本里 `{源行标记C.生成标记}` 出现 {生成标记数} 处");
            }
            catch (Exception ex) { 记录异常("调用关系 调用边表", ex); }

            static string 显示(IEnumerable<调用边C> 边们)
            {
                string 文本 = string.Join(" | ", 边们.Select(e => e.ToString()));
                return 文本.Length > 0 ? 文本 : "（空）";
            }
        }

        /// <summary>
        /// Q4a 未使用函数扫描(见 `引擎\未使用扫描C.cs`)。**只读**上面那张调用边表,不改编译产物一个字。
        /// 钉这些事:①没人调的函数扫得出来(含标了 `私有` 的模块函数)②顶层程序段调过的不算
        /// ③`测试` 块里调过的也不算 ④递归孤岛单独一栏 ⑤写了 `程序集` / 名字带模块前缀的归"对外接口"
        /// ⑥`私有` 一票否决(模块函数也不算对外,照实报"没人调")⑦三栏顺序都确定(文件 → 行号)
        /// ⑧便捷重载(直接吃编译结果)与"名字表 + 边表"两条路给出同一份报告
        /// ⑨"不写前缀 = 公共"的开关两种口径各验一次 ⑩不给源码时判不准的边界照实钉住。
        /// </summary>
        private static void 未使用扫描自检()
        {
            try
            {
                // 主.hb:四个函数,两个有人用(一个被顶层调、一个被 `测试` 块调)、一个没人调、一个递归孤岛。
                // 工具.hb:一个模块文件 —— `程序集`、默认公开、`私有` 各一个,三个都没人调。
                const string 主 = "方法 没人调() 返回 整数\n{\n返回 1;\n}\n" +
                    "方法 递归孤岛(整数 n) 返回 整数\n{\n如果 (n <= 1) {\n返回 0;\n}\n返回 递归孤岛(n - 1);\n}\n" +
                    "方法 被顶层用() 返回 整数\n{\n返回 3;\n}\n" +
                    "方法 被测试块用() 返回 整数\n{\n返回 4;\n}\n" +
                    "测试 样例 {\n断言 被测试块用() == 4;\n}\n测试输出(被顶层用());\n停止\n";
                const string 工具 = "模块 工具\n\n程序集 方法 同工程工具() 返回 整数\n{\n返回 5;\n}\n\n" +
                    "方法 对外求和(整数 a) 返回 整数\n{\n返回 a;\n}\n\n" +
                    "私有 方法 模块内部() 返回 整数\n{\n返回 6;\n}\n";
                var 文件表 = new List<(string 名称, string 内容)> { ("主.hb", 主), ("工具.hb", 工具) };
                var 编译结果 = new 汇编器C().汇编多文件带调试(文件表);
                var 边表 = 调用关系扫描C.扫描(编译结果);
                var 报告 = 未使用扫描C.扫描(编译结果.名字表, 边表, 文件表);

                var 完全没人调 = 报告.完全没人调.Select(x => $"{x.函数}@{x.文件名}:{x.起行}").ToArray();
                记录("未使用扫描 没人调的函数扫得出来(含标了 `私有` 的模块函数)",
                   完全没人调.SequenceEqual(new[] { "没人调@主.hb:1", "工具.模块内部@工具.hb:13" }),
                   string.Join(" | ", 完全没人调));
                记录("未使用扫描 顶层程序段调用过的不算(测试输出(被顶层用()))",
                   报告.找("被顶层用") == null, "被顶层用 不该出现在报告里");
                记录("未使用扫描 `测试` 块里调用过的也不算(测试块会生成真调用)",
                   报告.找("被测试块用") == null, "被测试块用 不该出现在报告里");
                记录("未使用扫描 递归孤岛单独一栏(只有它自己调自己)",
                   报告.递归孤岛.Count == 1 && 报告.递归孤岛[0].函数 == "递归孤岛"
                   && 报告.递归孤岛[0].归类 == 未使用归类C.递归孤岛,
                   string.Join(" | ", 报告.递归孤岛.Select(x => x.ToString())));

                var 对外 = 报告.对外接口.Select(x => $"{x.函数}@{x.起行}").ToArray();
                记录("未使用扫描 写了 `程序集` 与名字带模块前缀的归「对外接口」",
                   对外.SequenceEqual(new[] { "工具.同工程工具@3", "工具.对外求和@8" }),
                   string.Join(" | ", 对外));
                记录("未使用扫描 `私有` 一票否决(模块函数也不算对外,照实报没人调)",
                   报告.找("工具.模块内部")?.归类 == 未使用归类C.完全没人调,
                   $"{报告.找("工具.模块内部")}");

                bool 顺序对 = 三栏有序(报告);
                记录("未使用扫描 三栏顺序确定(文件 → 起行 → 函数名)", 顺序对,
                   $"完全没人调={完全没人调.Length} 递归孤岛={报告.递归孤岛.Count} 对外接口={对外.Length} 共 {报告.条数} 条");

                var 便捷 = 未使用扫描C.扫描(编译结果, 文件表);
                记录("未使用扫描 便捷重载(直接吃编译结果)与「名字表+边表」给出同一份报告",
                   便捷.全部.Select(x => $"{x.函数}@{x.归类}").SequenceEqual(报告.全部.Select(x => $"{x.函数}@{x.归类}")),
                   $"便捷={便捷.条数} 条,分开算={报告.条数} 条");

                // 库作者口径:把"不写可见性前缀 = 公共"也算对外 —— 默认公开的那条改归对外接口,`私有` 那条不动
                var 宽松 = 未使用扫描C.扫描(编译结果.名字表, 边表, 文件表, 无前缀也算对外接口: true);
                记录("未使用扫描 打开「无前缀也算对外接口」后,默认公共的没人调函数改归对外接口",
                   宽松.完全没人调.Count == 1 && 宽松.完全没人调[0].函数 == "工具.模块内部"
                   && 宽松.对外接口.Any(x => x.函数 == "没人调"),
                   $"完全没人调={string.Join("、", 宽松.完全没人调.Select(x => x.函数))};对外接口={string.Join("、", 宽松.对外接口.Select(x => x.函数))}");

                // 不给源码:看不到声明行。带模块前缀的**保守**算对外(宁可少报死代码,也不劝人删库的对外函数);
                // 不带前缀的照实报"没人调"。这条边界照实钉住,免得以后以为"不给源码也判得准"。
                var 无源 = 未使用扫描C.扫描(编译结果.名字表, 边表);
                记录("未使用扫描 不给源码时:不带前缀的照实报没人调,带前缀的保守算对外",
                   无源.找("没人调")?.归类 == 未使用归类C.完全没人调
                   && 无源.找("工具.模块内部")?.归类 == 未使用归类C.对外接口,
                   $"没人调={无源.找("没人调")?.归类};工具.模块内部={无源.找("工具.模块内部")?.归类}");
            }
            catch (Exception ex) { 记录异常("未使用扫描 未使用函数检测", ex); }

            static bool 三栏有序(未使用报告C 报告)
            {
                foreach (var 栏 in new[] { 报告.完全没人调, 报告.递归孤岛, 报告.对外接口 })
                    for (int i = 1; i < 栏.Count; i++)
                    {
                        int 比 = string.CompareOrdinal(栏[i - 1].声明文件, 栏[i].声明文件);
                        if (比 > 0) return false;
                        if (比 == 0 && (栏[i - 1].起行 > 栏[i].起行
                            || (栏[i - 1].起行 == 栏[i].起行
                                && string.CompareOrdinal(栏[i - 1].函数, 栏[i].函数) > 0))) return false;
                    }
                return true;
            }
        }

        /// <summary>
        /// Q4(核心) 重命名**编辑清单**(见 `引擎\重命名C.cs`):只算清单,不写盘、不碰编辑器。
        /// 钉这些事:①注释与字符串里的同名文字**一个都不许改**(最关键的一条)②代码里的整词都改了,
        /// 而 `x求和` / `求和x` / `求和_1` 这类前后缀同名**不算** ③幂等(套两遍 = 套一遍、改过的文本再算为 0 处)
        /// ④可逆(把新名再改回旧名,与原文逐字节一致)⑤带模块前缀名与裸名两种写法都能命中(开关也验)
        /// ⑥新名已经存在时报问题且**不硬改** ⑦字符串里的新名不算撞车 ⑧改完的源码照样能编译过。
        /// </summary>
        private static void 重命名自检()
        {
            try
            {
                // 第 3 行是注释、第 9 行是字符串、第 6~8 与第 10 行是"前后缀同名" —— 这些一律不许动。
                const string 源 = "模块 数学\n\n// 注释里的 求和 与 数学.求和 都不能动\n" +
                    "方法 求和(整数 a) 返回 整数\n{\n    整数 求和x = 1;\n    整数 x求和 = 2;\n    整数 求和_1 = 3;\n" +
                    "    输出行(\"求和 数学.求和 求和x\");\n    返回 a + 求和x + x求和 + 求和_1;\n}\n\n" +
                    "测试输出(求和(1));\n测试输出(数学.求和(2));\n停止\n";
                const string 期望 = "模块 数学\n\n// 注释里的 求和 与 数学.求和 都不能动\n" +
                    "方法 加和(整数 a) 返回 整数\n{\n    整数 求和x = 1;\n    整数 x求和 = 2;\n    整数 求和_1 = 3;\n" +
                    "    输出行(\"求和 数学.求和 求和x\");\n    返回 a + 求和x + x求和 + 求和_1;\n}\n\n" +
                    "测试输出(加和(1));\n测试输出(数学.加和(2));\n停止\n";
                var 文件表 = new List<(string 名称, string 内容)> { ("主.hb", 源) };

                var 清单 = 重命名C.计算("数学.求和", "数学.加和", 文件表);
                记录("重命名 清单可改且只在代码里改整词(声明 + 裸名调用 + 带前缀调用 = 3 处)",
                   清单.可改 && 清单.问题.Count == 0 && 清单.编辑.Select(x => x.行号).SequenceEqual(new[] { 4, 13, 14 }),
                   $"问题={清单.问题.Count} 编辑={string.Join(" | ", 清单.编辑)}");

                string 改后 = 清单.应用(文件表)[0].内容;
                记录("重命名 注释与字符串里的同名文字一个都没改(与期望文本逐字节一致)",
                   string.Equals(改后, 期望, StringComparison.Ordinal), 首个不同处(源, 期望, 改后));
                记录("重命名 前后缀同名不算整词(x求和 / 求和x / 求和_1 一个都没动)",
                   改后.Contains("整数 求和x = 1;", StringComparison.Ordinal)
                   && 改后.Contains("整数 x求和 = 2;", StringComparison.Ordinal)
                   && 改后.Contains("整数 求和_1 = 3;", StringComparison.Ordinal)
                   && 改后.Contains("a + 求和x + x求和 + 求和_1", StringComparison.Ordinal),
                   "前后缀同名那几行原样");
                记录("重命名 带模块前缀名与裸名两种写法都命中(第 13、14 行都改了)",
                   改后.Contains("测试输出(加和(1));", StringComparison.Ordinal)
                   && 改后.Contains("测试输出(数学.加和(2));", StringComparison.Ordinal),
                   "第 13 行是裸名、第 14 行是 `数学.` 前缀");

                var 回表 = new List<(string 名称, string 内容)> { ("主.hb", 改后) };
                var 回清单 = 重命名C.计算("数学.加和", "数学.求和", 回表);
                记录("重命名 可逆:把新名再改回旧名,与原文逐字节一致",
                   回清单.可改 && string.Equals(回清单.应用(回表)[0].内容, 源, StringComparison.Ordinal),
                   回清单.可改 ? $"回改 {回清单.处数} 处" : string.Join(" | ", 回清单.问题));
                记录("重命名 幂等:同一份清单套两遍 = 套一遍",
                   string.Equals(清单.应用(清单.应用(文件表))[0].内容, 改后, StringComparison.Ordinal), "套两遍不多改一处");
                var 二次 = 重命名C.计算("数学.求和", "数学.加和", 回表);
                记录("重命名 幂等:对已经改过的文本再算一次,编辑项为 0(旧名已经不在了)",
                   二次.编辑.Count == 0, $"编辑={二次.处数} 问题={二次.问题.Count}");

                // 反过来:旧名给**裸名** `求和`,带模块前缀的 `数学.求和` 也要命中(而且只换尾巴那一段)
                var 裸清单 = 重命名C.计算("求和", "加和", 文件表);
                记录("重命名 旧名给裸名时,带前缀的写法也命中(只换尾巴,前缀留着)",
                   裸清单.可改 && 裸清单.编辑.Select(x => x.行号).SequenceEqual(new[] { 4, 13, 14 })
                   && string.Equals(裸清单.应用(文件表)[0].内容, 期望, StringComparison.Ordinal),
                   $"编辑={string.Join(" | ", 裸清单.编辑)}");
                var 不碰前缀 = 重命名C.计算("求和", "加和", 文件表, null, 含模块前缀名: false);
                记录("重命名 关掉「含模块前缀名」后 `数学.求和` 不动(只改模块里的裸写)",
                   不碰前缀.可改 && 不碰前缀.编辑.Select(x => x.行号).SequenceEqual(new[] { 4, 13 })
                   && 不碰前缀.应用(文件表)[0].内容.Contains("数学.求和(2)", StringComparison.Ordinal),
                   $"编辑={string.Join(" | ", 不碰前缀.编辑)}");

                var 撞车表 = new List<(string 名称, string 内容)> { ("小.hb", "整数 a = 1;\n整数 b = 2;\na = a + b;\n") };
                var 撞车 = 重命名C.计算("a", "b", 撞车表);
                记录("重命名 新名已经存在时报问题且不硬改(编辑清空、带文件与行号)",
                   !撞车.可改 && 撞车.编辑.Count == 0 && 撞车.问题.Count == 1
                   && 撞车.问题[0].文件 == "小.hb" && 撞车.问题[0].行号 == 2
                   && 撞车.问题[0].说明.Contains("已经", StringComparison.Ordinal)
                   && 撞车.问题[0].说明.Contains("b", StringComparison.Ordinal),
                   string.Join(" | ", 撞车.问题));

                var 串表 = new List<(string 名称, string 内容)> { ("串.hb", "输出行(\"加和\");\n整数 求和 = 1;\n测试输出(求和);\n") };
                var 串清单 = 重命名C.计算("求和", "加和", 串表);
                记录("重命名 字符串里的新名不算撞车(撞车只看代码区)",
                   串清单.可改 && 串清单.处数 == 2
                   && 串清单.应用(串表)[0].内容.Contains("\"加和\"", StringComparison.Ordinal)
                   && 串清单.应用(串表)[0].内容.Contains("整数 加和 = 1;", StringComparison.Ordinal),
                   $"编辑={string.Join(" | ", 串清单.编辑)}");

                try
                {
                    // R4-2:以前这里写死 `true`(等于"没抛异常就算过"),换成真谓词 —— 编出来的机器码非空。
                    byte[] 改后机器码 = 汇编(改后);
                    记录("重命名 改完的源码照样能编译过(清单没把语法改坏)", 改后机器码.Length > 0,
                        $"编译通过,机器码 {改后机器码.Length} 字节");
                }
                catch (Exception ex)
                {
                    记录("重命名 改完的源码照样能编译过(清单没把语法改坏)", false, ex.Message);
                }
            }
            catch (Exception ex) { 记录异常("重命名 编辑清单", ex); }

            static string 首个不同处(string 原, string 期望, string 实际)
            {
                if (string.Equals(实际, 期望, StringComparison.Ordinal))
                    return string.Equals(实际, 原, StringComparison.Ordinal) ? "与原文一致(没有改到)" : "与期望一致";
                int 止 = Math.Min(期望.Length, 实际.Length);
                for (int i = 0; i < 止; i++)
                    if (期望[i] != 实际[i])
                        return $"第 {i + 1} 个字符起不一样:期望 <{剪(期望, i)}> 实际 <{剪(实际, i)}>";
                return $"长度不一样:期望 {期望.Length} 实际 {实际.Length}";
            }

            static string 剪(string 文本, int 起)
            {
                int 长 = Math.Min(24, 文本.Length - 起);
                return 文本.Substring(起, 长).Replace("\n", "\\n");
            }
        }

        /// <summary>
        /// C1(第118批):**查找 / 替换**(P21)。引擎在 `引擎\查找替换C.cs`,界面与命令行共用。
        /// 钉的是口径:① 默认**保护注释与字符串**(与 `重命名C` 同一套判据)② 默认**不区分大小写**
        /// ③ `整词` 开着时前后缀同名不算 ④ 命中的区间**不重叠** ⑤ 替换清单的顺序/应用/幂等/可逆
        /// ⑥ 空词、新旧一样的报错 ⑦ 预览文本里带 文件:行:列。
        /// </summary>
        private static void 查找替换自检()
        {
            try
            {
                // ① 当前文件查找:注释与字符串里的不算(默认保护)
                const string 源 = "整数 词 = 1;\n// 词 的注释\n字符串 说 = \"词\";\n测试输出(词);\n";
                var 命中 = 查找替换C.查找(源, "词");
                记录("查找 默认保护注释与字符串(代码里 2 处;注释/字符串里的不算)",
                    命中.Count == 2 && 命中[0].行号 == 1 && 命中[0].列 == 3 && 命中[1].行号 == 4 && 命中[1].列 == 5,
                    string.Join(" | ", 命中));
                记录("查找 位置换算对(行文本一起带出来,给『下一个』跳转用)",
                    命中.Count == 2 && 命中[1].行文本 == "测试输出(词);", 命中.Count == 2 ? 命中[1].行文本 : "命中数不对");
                var 全命中 = 查找替换C.查找(源, "词", new 查找设置C { 保护注释与字符串 = false });
                记录("查找 关掉保护后连注释/字符串里的也命中(4 处)",
                    全命中.Count == 4, string.Join(" | ", 全命中));

                // ② 不区分大小写(默认)/ 区分大小写
                const string 英文 = "Abc = 1;\nabc = 2;\nABC = 3;\n";
                记录("查找 默认不区分大小写(Abc/abc/ABC 都算,3 处)",
                    查找替换C.查找(英文, "abc").Count == 3, "3 处");
                记录("查找 勾上区分大小写后只剩 1 处(abc)",
                    查找替换C.查找(英文, "abc", new 查找设置C { 区分大小写 = true }).Count == 1, "1 处");

                // ③ 整词
                const string 整词源 = "整数 词 = 1;\n整数 词词 = 2;\n测试输出(词词 + 词);\n";
                记录("查找 整词开着时前后缀同名不算(词命中 2 处,词词 不算)",
                    查找替换C.查找(整词源, "词", new 查找设置C { 整词 = true }).Count == 2, "2 处");

                // ④ 命中区间不重叠
                记录("查找 命中不重叠(\"aaaa\" 找 \"aa\" 是 2 处)",
                    查找替换C.查找("aaaa", "aa").Count == 2, "2 处");

                // ⑤ 全工程替换清单:顺序(文件 → 行号 → 列)/ 应用 / 幂等 / 可逆
                var 文件表 = new List<(string 名称, string 内容)>
                {
                    ("b.hb", "整数 x = 1;\n"),
                    ("a.hb", "// x 的注释\n整数 x = 1;\n测试输出(x);\n"),
                };
                var 清单 = 查找替换C.替换清单("x", "y", 文件表);
                记录("替换 全工程清单:注释不动、顺序是 文件→行号→列",
                    清单.可改 && 清单.处数 == 3
                    && 清单.编辑.Select(k => $"{k.文件}:{k.行号}:{k.列}").SequenceEqual(new[] { "a.hb:2:3", "a.hb:3:5" , "b.hb:1:3" }),
                    string.Join(" | ", 清单.编辑));
                string 改后 = 清单.应用(文件表).First(f => f.名称 == "a.hb").内容;
                记录("替换 应用后文本对(注释里那个 x 没被改)",
                    改后 == "// x 的注释\n整数 y = 1;\n测试输出(y);\n", 改后.Replace("\n", "\\n"));
                记录("替换 幂等:同一份清单套两遍 = 套一遍",
                    string.Equals(清单.应用(清单.应用(文件表)).First(f => f.名称 == "a.hb").内容, 改后, StringComparison.Ordinal),
                    "套两遍不多改一处");
                var 回表 = new List<(string 名称, string 内容)> { ("a.hb", 改后) };
                var 回清单 = 查找替换C.替换清单("y", "x", 回表);
                记录("替换 可逆:把新词再换回旧词,与原文逐字节一致",
                   回清单.可改 && string.Equals(回清单.应用(回表)[0].内容, 文件表[1].内容, StringComparison.Ordinal),
                   回清单.可改 ? $"回改 {回清单.处数} 处" : string.Join(" | ", 回清单.问题));

                // ⑥ 报错口径
                记录("替换 空词与新旧一样都报问题(不硬改)",
                    查找替换C.替换清单("", "y", 文件表).问题.Count == 1
                    && 查找替换C.替换清单("x", "x", 文件表).问题.Count == 1
                    && 查找替换C.替换清单("x", "y", 文件表).问题.Count == 0, "空词/同词各一条");

                // ⑦ 预览文本
                string 预览 = 清单.预览();
                记录("替换 预览文本里带 文件:行:列 与设置口径(界面输出框与命令行共用一份)",
                    预览.Contains("共 3 处") && 预览.Contains("a.hb:3:6") && 预览.Contains("不区分大小写")
                    && 预览.Contains("保护注释与字符串"), 预览.Split('\n')[0]);
                // ⑧ H5:正则那一档(`正则 = true`;与编辑器自带的 Ctrl+F 面板同一套 .NET 正则口径)
                var 正则设置 = new 查找设置C { 正则 = true };
                记录("正则 字符类 + 量词(\\d+ 在 `a123 b45 c6` 上命中 3 处)",
                    查找替换C.查找("a123 b45 c6\n", @"\d+", 正则设置).Count == 3, "3 处");
                记录("正则 分组 + 或 + {n}(`[ab]\\d{2}` 命中 2 处,a5 不算)",
                    查找替换C.查找("a12 b34 a5\n", @"[ab]\d{2}", 正则设置).Count == 2, "2 处");
                记录("正则 与整词同开(`整数|小数` 整词 ⇒ 2 处,整数a 不算)",
                    查找替换C.查找("整数 整数a 小数\n", "整数|小数",
                        new 查找设置C { 正则 = true, 整词 = true }).Count == 2, "2 处");
                记录("正则 关着时 `.*` 就是两个普通字符(找不到)",
                    查找替换C.查找("ab\n", ".*").Count == 0, "0 处");

                var 分组表 = new List<(string 名称, string 内容)> { ("a.hb", "整数 x = 1;\n") };
                var 分组清单 = 查找替换C.替换清单(@"(\w+) = (\d+);", "$2 = $1;", 分组表, 正则设置);
                string 分组后 = 分组清单.应用(分组表)[0].内容;
                记录("正则 换成里的 $1 / $2 按这一处命中的分组展开(`x = 1;` ⇒ `1 = x;`)",
                    分组清单.可改 && 分组后 == "整数 1 = x;\n", 分组后.Replace("\n", "\\n"));

                var 非法清单 = 查找替换C.替换清单("([", "x", 分组表, 正则设置);
                记录("正则 写错了当场给一条人话问题(清单留空,一个字符都不改)",
                    非法清单.问题.Count == 1 && 非法清单.编辑.Count == 0
                    && 非法清单.问题[0].说明.Contains("正则", StringComparison.Ordinal)
                    && 非法清单.问题[0].说明.Contains("改法", StringComparison.Ordinal),
                    非法清单.问题.Count == 1 ? 非法清单.问题[0].说明 : "问题数不对");

                var 跨行表 = new List<(string 名称, string 内容)> { ("a.hb", "整数 x = 1;\n测试输出(x);\n") };
                var 跨行清单 = 查找替换C.替换清单(@"整数 x = 1;[\s\S]*?测试输出", "Z", 跨行表, 正则设置);
                记录("正则 命中跨行时替换不硬改(一条问题),只找那一半可以跨行",
                    跨行清单.问题.Count == 1 && 跨行清单.编辑.Count == 0
                    && 跨行清单.问题[0].说明.Contains("跨了行", StringComparison.Ordinal)
                    && 查找替换C.查找(跨行表[0].内容, @"整数 x = 1;[\s\S]*?测试输出", 正则设置).Count == 1,
                    "替换报一条 / 只找 1 处");

                记录("正则 档下『找 == 换』不再拦(字面量档照旧拦)",
                    查找替换C.替换清单("x", "x", 分组表, 正则设置).问题.Count == 0
                    && 查找替换C.替换清单("x", "x", 分组表).问题.Count == 1, "正则档放行 / 字面量档一条");

                const string 接线名 = "正则 界面勾选框与命令行 --正则 都接在同一条路上(按源码钉)";
                string? 仓根 = 找仓库根目录();
                if (仓根 == null) 跳过(接线名, "找不到仓库根(不在工作副本里跑)");
                else
                {
                    try
                    {
                        string 窗源 = File.ReadAllText(Path.Combine(仓根, "界面控件", "输入窗口.xaml.cs"));
                        string 窗xaml = File.ReadAllText(Path.Combine(仓根, "界面控件", "输入窗口.xaml"));
                        string 主窗源 = File.ReadAllText(Path.Combine(仓根, "MainWindow.窗口与文件.cs"));
                        string 命令行源 = File.ReadAllText(Path.Combine(仓根, "编译器CLI", "Program.cs"));
                        记录(接线名,
                            窗源.Contains("public static string? 问带勾选", StringComparison.Ordinal)
                            && 窗xaml.Contains("x:Name=\"勾选框\"", StringComparison.Ordinal)
                            && 主窗源.Contains("输入窗口.问带勾选(this, \"替换(当前文件)\"", StringComparison.Ordinal)
                            && 主窗源.Contains("输入窗口.问带勾选(this, \"全工程替换\"", StringComparison.Ordinal)
                            && 主窗源.Contains("new 查找设置C { 正则 = 按正则 }", StringComparison.Ordinal)
                            && 命令行源.Contains("case \"--正则\": 查找正则 = true; break;", StringComparison.Ordinal),
                            "输入窗口.问带勾选 + 两处替换 + --正则 一条路");
                    }
                    catch (Exception ex) { 记录异常(接线名, ex); }
                }
            }
            catch (Exception ex) { 记录异常("查找替换 编辑清单", ex); }
        }

        /// <summary>
        /// C2(第119批):**转到定义 / 查找引用**(P22,语义版)。引擎在 `引擎\转到定义C.cs`。
        /// 钉六类行为:① 用户函数(尾名相等,跨文件)② 同名时优先同一个文件 ③ 变量(定义 + 文本口径的引用)
        /// ④ 内建/宿主/指令/语句这些"没有源码定义"的也要**说清是哪一类**(不是静默没反应)
        /// ⑤ 结构没有单一声明行 ⑥ 没编译过 / 未定义 各有各的说明。
        /// </summary>
        private static void 转到定义自检()
        {
            try
            {
                var 名字表 = new 名字表C
                {
                    函数范围 = new List<(string 函数, int 起, int 止, string 文件)>
                    {
                        ("数学.求和", 4, 8, "主.hb"),
                        ("物理.求和", 40, 44, "副.hb"),
                        ("取总", 12, 20, "副.hb"),
                    },
                    变量 = new List<名字项C>
                    {
                        new 名字项C { 名字 = "总", 声明行 = 3, 声明文件 = "主.hb", 类型名 = "整数", 是全局 = true },
                        new 名字项C { 名字 = "总", 声明行 = 7, 声明文件 = "副.hb", 类型名 = "整数", 所属函数 = "取总" },
                    },
                    结构 = new Dictionary<string, List<字段项C>>(StringComparer.OrdinalIgnoreCase)
                    {
                        ["点"] = new List<字段项C> { new 字段项C { 名字 = "x", 类型名 = "整数", 宽度 = 4 } },
                    },
                };
                var 调用表 = new 调用关系表C();
                调用表.收(new 调用边C { 调用者 = "主程序", 调用点文件 = "主.hb", 调用点行 = 30, 被调标签 = "取总", 被调定义名 = "取总", 种类 = 调用种类C.用户函数 });
                调用表.收(new 调用边C { 调用者 = "调用方", 调用点文件 = "副.hb", 调用点行 = 15, 被调标签 = "取总", 被调定义名 = "取总", 种类 = 调用种类C.用户函数 });
                var 文件表 = new List<(string 名称, string 内容)>
                {
                    ("主.hb", "整数 总 = 0;\n测试输出(总);\n"),
                    ("副.hb", "整数 取总(整数 总) 返回 整数\n{\n返回 总;\n}\n"),
                };

                var 跨文件 = 转到定义C.计算("取总", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 用户函数:跨文件跳到定义那一行(副.hb:12)",
                    跨文件.类别 == "用户函数" && 跨文件.定义 is { } d && d.文件 == "副.hb" && d.行 == 12,
                    跨文件.ToString());
                记录("转到定义 引用来自调用边表(2 处,按 文件 → 行 排好)",
                    跨文件.引用数 == 2 && 跨文件.引用[0].文件 == "主.hb" && 跨文件.引用[0].行 == 30
                    && 跨文件.引用[1].文件 == "副.hb" && 跨文件.引用[1].行 == 15,
                    string.Join(" | ", 跨文件.引用));

                var 同文件优先 = 转到定义C.计算("求和", "副.hb", 名字表, 调用表, 文件表);
                记录("转到定义 同名尾名优先同一个文件(光标在副.hb → 跳 物理.求和;说明里点出有 2 个同名)",
                    同文件优先.定义 is { } d2 && d2.文件 == "副.hb" && d2.行 == 40
                    && 同文件优先.说明.Contains("2 个尾名一样", StringComparison.Ordinal), 同文件优先.说明);

                var 变量 = 转到定义C.计算("总", "副.hb", 名字表, 调用表, 文件表);
                记录("转到定义 变量:定义(同文件那个)+ 引用走**文本**口径(说明里写明)",
                    变量.类别 == "变量" && 变量.定义 is { } v && v.文件 == "副.hb" && v.行 == 7
                    && 变量.引用数 > 0 && 变量.说明.Contains("文本", StringComparison.Ordinal),
                    $"{变量.定义} / 引用 {变量.引用数} 处");

                var 内建 = 转到定义C.计算("存字", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 内建函数:没有源码定义但**说清是哪一类**(不静默)",
                    内建.类别 == "内建函数" && 内建.定义 == null && 内建.说明.Contains("没有源码定义", StringComparison.Ordinal),
                    内建.说明);
                var 语句 = 转到定义C.计算("输出行", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 语句关键字(输出行):类别是『语句』,不当成『未定义』",
                    语句.类别 == "语句" && 语句.定义 == null, 语句.说明);
                var 宿主 = 转到定义C.计算("当前时间", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 宿主能力(当前时间):也归在内建那一类,说明里点明由宿主实现",
                    宿主.类别 == "内建函数" && 宿主.说明.Contains("宿主能力", StringComparison.Ordinal), 宿主.说明);
                var 指令 = 转到定义C.计算("加载", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 汇编指令:类别是『指令』,不硬说成没定义",
                    指令.类别 == "指令" && 指令.定义 == null, 指令.说明);

                var 结构 = 转到定义C.计算("点", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 结构:没有单一声明行可跳,说明里写清 + 按文本给线索",
                    结构.类别 == "结构" && 结构.定义 == null && 结构.说明.Contains("结构", StringComparison.Ordinal),
                    结构.说明);

                var 没编 = 转到定义C.计算("取总", "主.hb", (名字表C?)null, null, 文件表);
                记录("转到定义 还没有编译结果:说明『先编译一次』+ 先按文本给线索",
                    没编.类别 == "还没有编译" && 没编.说明.Contains("先编译一次", StringComparison.Ordinal), 没编.说明);

                var 未定义 = 转到定义C.计算("没这个名字", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 未定义:说清『名字表里没有定义』(而不是静默没反应)",
                    未定义.类别 == "未定义" && 未定义.定义 == null
                    && (未定义.说明.Contains("没有定义", StringComparison.Ordinal) || 未定义.说明.Contains("敲错", StringComparison.Ordinal)),
                    未定义.说明);

                var 空词 = 转到定义C.计算("", "主.hb", 名字表, 调用表, 文件表);
                记录("转到定义 光标不在名字上:提示把光标放进名字里",
                    空词.类别 == "没有词" && 空词.说明.Contains("光标下面没有名字", StringComparison.Ordinal), 空词.说明);
            }
            catch (Exception ex) { 记录异常("转到定义 导航", ex); }
        }

        /// <summary>
        /// Q4c 未使用报告 → 诊断项(见 `引擎\未使用扫描C.cs` 的 `未使用诊断C`)。
        /// 这是这件交付物里**唯一能自动验证**的一层:界面怎么画没法自动验,"哪一条报成什么级别、写什么话"可以。
        /// 钉这些事:①完全没人调 → 警告级,文件/行号/规则/文案(含函数名)都对 ②递归孤岛按"只被它自己调用"报
        /// ③对外接口**默认不报**(库的对外函数不该把问题页刷满),但报告里确实有这一栏
        /// ④打开 `报对外接口` 后按**提示**级报出来 ⑤报告为空 / 报告是 null → 空列表、不炸。
        /// </summary>
        private static void 未使用诊断自检()
        {
            try
            {
                // 主.hb:一个没人调、一个递归孤岛、一个被顶层调(不报)。
                // 工具.hb:模块成员(名字带前缀 ⇒ 对外接口)。
                const string 主 = "方法 没人调() 返回 整数\n{\n返回 2;\n}\n\n" +
                    "方法 孤岛(整数 n) 返回 整数\n{\n如果 (n <= 0) {\n返回 0;\n}\n返回 孤岛(n - 1);\n}\n\n" +
                    "测试输出(1);\n停止\n";
                const string 工具 = "模块 工具\n\n方法 对外求和(整数 a) 返回 整数\n{\n返回 a;\n}\n";
                var 文件表 = new List<(string 名称, string 内容)> { ("主.hb", 主), ("工具.hb", 工具) };
                var 报告 = 未使用扫描C.扫描(new 汇编器C().汇编多文件带调试(文件表), 文件表);

                var 诊断 = 未使用诊断C.映射(报告);
                var 没人调 = 诊断.FirstOrDefault(d => d.文件 == "主.hb" && d.行 == 1);
                记录("未使用诊断 完全没人调的函数报成警告级(文件/起行/规则/文案都带上函数名)",
                    诊断.Count == 2 && 没人调 != null && 没人调.级别 == 诊断级别.警告
                    && 没人调.规则 == 未使用诊断C.规则名
                    && 没人调.文本.Contains("没人调", StringComparison.Ordinal)
                    && 没人调.文本.Contains("没有被任何地方调用", StringComparison.Ordinal),
                    $"共 {诊断.Count} 条:{string.Join(" | ", 诊断.Select(d => d.ToString()))}");

                var 孤岛 = 诊断.FirstOrDefault(d => d.文件 == "主.hb" && d.行 == 6);
                记录("未使用诊断 递归孤岛按「只被它自己调用」报出来(起行 = 声明那一行)",
                    孤岛 != null && 孤岛.级别 == 诊断级别.警告
                    && 孤岛.文本.Contains("孤岛", StringComparison.Ordinal)
                    && 孤岛.文本.Contains("递归", StringComparison.Ordinal),
                    $"{孤岛}");

                记录("未使用诊断 对外接口默认不报(报告里有这一栏,诊断里一条都没有)",
                    !诊断.Any(d => d.文件 == "工具.hb") && 报告.对外接口.Count == 1
                    && 报告.找("工具.对外求和") != null,
                    $"对外接口 {报告.对外接口.Count} 条,诊断 {诊断.Count} 条");

                var 全报 = 未使用诊断C.映射(报告, 诊断级别.警告, 报对外接口: true);
                var 对外诊断 = 全报.FirstOrDefault(d => d.文件 == "工具.hb" && d.行 == 3);
                记录("未使用诊断 打开「报对外接口」后按提示级报出来(比没人调那一档轻)",
                    全报.Count == 3 && 对外诊断 != null && 对外诊断.级别 == 诊断级别.提示
                    && 对外诊断.文本.Contains("工具.对外求和", StringComparison.Ordinal)
                    && 对外诊断.文本.Contains("对外接口", StringComparison.Ordinal)
                    && 对外诊断.文本.Contains("不建议删", StringComparison.Ordinal),
                    $"{对外诊断}");

                记录("未使用诊断 报告为空 / 报告是 null 都给空列表(不炸)",
                    未使用诊断C.映射(new 未使用报告C()).Count == 0
                    && 未使用诊断C.映射(null).Count == 0
                    && 未使用诊断C.映射(null, 诊断级别.错误, 报对外接口: true).Count == 0,
                    "空报告 → 0 条");
            }
            catch (Exception ex) { 记录异常("未使用诊断 报告→诊断项映射", ex); }
        }

        /// <summary> Q2 `程序集`:同工程随便用;别的工程(含子工程)用不了,当场报错并给改法 </summary>
        private static void 程序集自检()
        {
            try
            {
                string 根目录 = Path.Combine(AppContext.BaseDirectory, "_程序集测试");
                string 库目录 = Path.Combine(根目录, "库");
                string 程序目录 = Path.Combine(根目录, "程序");
                Directory.CreateDirectory(库目录);
                Directory.CreateDirectory(程序目录);
                string 库源码 =
                    "程序集 结构 内部点\n{\n整数 x;\n}\n" +
                    "程序集 整数 内部计数 = 5;\n" +
                    "程序集 方法 内部工具() 返回 整数\n{\n返回 7;\n}\n" +
                    "方法 公开工具() 返回 整数\n{\n内部点 q;\nq.x = 内部工具() + 内部计数;\n返回 q.x;\n}\n";
                string 库hb = Path.Combine(库目录, "库.hb");
                string 主程序hb = Path.Combine(程序目录, "主程序.hb");
                File.WriteAllText(库hb, 库源码);
                File.WriteAllText(主程序hb, "测试输出(公开工具());\n停止\n");
                new 工程文件C { 名称 = "库", 启动文件 = "库.hb", 文件 = ["库.hb"] }.保存(Path.Combine(库目录, "库.hbp"));
                string 程序hbp = Path.Combine(程序目录, "程序.hbp");
                new 工程文件C
                {
                    名称 = "程序",
                    启动文件 = "主程序.hb",
                    文件 = ["主程序.hb", Path.Combine("..", "库", "库.hb")],
                    子工程 = [Path.Combine("..", "库", "库.hbp")],
                }.保存(程序hbp);

                var 库工程 = 工程文件C.加载(Path.Combine(库目录, "库.hbp"));
                var 程序工程 = 工程文件C.加载(程序hbp);
                var 树 = 工程文件C.读取工程树(程序hbp);
                var 库表 = 库工程.读全部源文件带归属(树);
                var 程序表 = 程序工程.读全部源文件带归属(树);
                记录("程序集 借来一起编译的库文件仍算库工程",
                    程序表.Any(x => Path.GetFileName(x.名称) == "库.hb" && x.工程 == "库")
                    && 程序表.Any(x => Path.GetFileName(x.名称) == "主程序.hb" && x.工程 == "程序"),
                    string.Join("、", 程序表.Select(x => $"{Path.GetFileName(x.名称)}→{x.工程}")));

                // 正面:同一个工程里 `程序集` 成员随便用(库自己那块:函数 / 全局变量 / 结构三样都用了)
                var 同工程编译 = new 汇编器C().汇编多文件带调试(两列(库表), 优化: true, 工程归属: [.. 库表.Select(x => x.工程)]);
                记录("程序集 同一个工程里函数/全局/结构都能用", 同工程编译.机器码.Length > 0, $"机器码={同工程编译.机器码.Length} 字节");

                // 正面:库的 `公共` 函数跨工程能用(它内部用的还是库自己的 `程序集` 成员)→ 跑出 7+5=12
                var 跨工程编译 = new 汇编器C().汇编多文件带调试(两列(程序表), 工程归属: [.. 程序表.Select(x => x.工程)]);
                var vm = new 虚拟机C { 输出目标 = _ => { } };
                vm.运行(跨工程编译);
                记录("程序集 公共成员跨工程能用(内部照用 程序集 成员)", vm.寄存器[0] == 12, $"R0={vm.寄存器[0]}(期望 12)");

                // 正面:同一个工程的**不同文件**之间随便用(库自己那块是同一文件内,这里补跨文件这一条)
                var 同工程两文件 = new List<(string 名称, string 内容)>
                {
                    (Path.Combine(程序目录, "a.hb"), "程序集 方法 内部函数() 返回 整数\n{\n返回 9;\n}\n"),
                    (Path.Combine(程序目录, "b.hb"), "测试输出(内部函数());\n停止\n"),
                };
                var 同工程两文件编译 = new 汇编器C().汇编多文件带调试(同工程两文件, 优化: true,
                    堆大小: 中间层C.默认堆大小, 工程归属: ["程序", "程序"]);
                var vm同工程 = new 虚拟机C { 输出目标 = _ => { } };
                vm同工程.运行(同工程两文件编译);
                记录("程序集 同一个工程的不同文件之间能用", vm同工程.寄存器[0] == 9, $"R0={vm同工程.寄存器[0]}(期望 9)");

                // 反面:程序工程借库文件一起编译,调用库里的 `程序集` 函数 → 报错;文案必须能照着改(要出现 程序集/工程/去掉)
                // (主程序.hb 是启动文件,排在库前面 —— 函数靠预扫收档位,所以"调用在声明之前"也挡得住)
                File.WriteAllText(主程序hb, "测试输出(内部工具());\n停止\n");
                var 改过程序表 = 程序工程.读全部源文件带归属(树);
                期望异常("程序集 别的工程调用 → 报错并说清怎么改(带 程序集/工程/去掉)",
                    () => new 汇编器C().汇编多文件带调试(两列(改过程序表), 工程归属: [.. 改过程序表.Select(x => x.工程)]),
                    "程序集", "工程", "去掉");

                // 反面:结构 / 全局变量同口径(库文件排前面,声明先登记;函数靠预扫所以顺序随便)
                var 库在前 = new List<(string 名称, string 内容)>
                {
                    (库hb, 库源码),
                    (Path.Combine(程序目录, "取结构.hb"), "内部点 p;\n停止\n"),
                };
                期望异常("程序集 别的工程引用结构 → 报错",
                    () => new 汇编器C().汇编多文件带调试(库在前, 优化: true, 堆大小: 中间层C.默认堆大小, 工程归属: ["库", "程序"]),
                    "程序集", "内部点");
                var 库在前全局 = new List<(string 名称, string 内容)>
                {
                    (库hb, 库源码),
                    (Path.Combine(程序目录, "取全局.hb"), "整数 全局量 = 内部计数;\n测试输出(全局量);\n停止\n"),
                };
                期望异常("程序集 别的工程读全局变量 → 报错",
                    () => new 汇编器C().汇编多文件带调试(库在前全局, 优化: true, 堆大小: 中间层C.默认堆大小, 工程归属: ["库", "程序"]),
                    "程序集", "内部计数");

                // 反面:结构**字段**上的 `程序集` 同口径(A4,第103批)—— 别的工程碰那个字段 → 报错
                var 库在前字段 = new List<(string 名称, string 内容)>
                {
                    (库hb, "结构 内部点\n{\n程序集 整数 芯;\n整数 皮;\n}\n"),   // 结构本身公开、字段是程序集
                    (Path.Combine(程序目录, "取字段.hb"), "内部点 p;\n测试输出(p.芯);\n停止\n"),
                };
                期望异常("A4 字段程序集 别的工程碰 `程序集` 字段 → 报错并说清怎么改",
                    () => new 汇编器C().汇编多文件带调试(库在前字段, 优化: true, 堆大小: 中间层C.默认堆大小, 工程归属: ["库", "程序"]),
                    "程序集", "内部点.芯", "去掉");
                var 库在前字段同工程 = new List<(string 名称, string 内容)>
                {
                    (库hb, "结构 内部点\n{\n程序集 整数 芯;\n整数 皮;\n}\n"),
                    (Path.Combine(程序目录, "同工程字段.hb"), "内部点 p;\np.芯 = 4;\n测试输出(p.芯);\n停止\n"),
                };
                var 同工程字段编译 = new 汇编器C().汇编多文件带调试(库在前字段同工程, 优化: true,
                    堆大小: 中间层C.默认堆大小, 工程归属: ["库", "库"]);   // 同一个工程里:放行
                var 字段缓冲 = new StringBuilder();
                var 字段解码 = new 文字输出C(文本 => 字段缓冲.Append(文本));
                var vm字段 = new 虚拟机C { 输出目标 = 字段解码.写 };
                vm字段.运行(同工程字段编译);
                字段解码.收尾();
                记录("A4 字段程序集 同一个工程里能用(与顶层 `程序集` 同一条判据)",
                    字段缓冲.ToString().TrimEnd('\n') == "4", $"输出={字段缓冲.ToString().TrimEnd('\n')}");

                // 英文别名 `internal` 走同一条判据
                期望异常("程序集 英文别名 internal 同一条判据",
                    () => new 汇编器C().汇编多文件带调试(
                    [
                        ("库.hb", "internal 方法 秘密() 返回 整数\n{\n返回 1;\n}\n"),
                        ("主程序.hb", "测试输出(秘密());\n停止\n"),
                    ], 优化: true, 堆大小: 中间层C.默认堆大小, 工程归属: ["库", "程序"]), "程序集");

                // 不传工程归属 = 同一个匿名工程(单文件那条路)→ `程序集` 与 `公共` 等价
                var 匿名编译 = new 汇编器C().汇编多文件带调试(
                [
                    ("库.hb", 库源码),
                    ("主程序.hb", "测试输出(内部工具());\n停止\n"),
                ]);
                var vm匿名 = new 虚拟机C { 输出目标 = _ => { } };
                vm匿名.运行(匿名编译);
                记录("程序集 不传工程归属时与 公共 等价", vm匿名.寄存器[0] == 7, $"R0={vm匿名.寄存器[0]}(期望 7)");

                // 两个可见性前缀不能同时写(说清为什么不许,而不是当成不认识的语句)
                期望异常("程序集 一个声明只能写一个可见性前缀",
                    () => new 汇编器C().汇编多文件带调试([("a.hb", "程序集 私有 方法 f() 返回 整数\n{\n返回 1;\n}\n停止\n")]),
                    "只能写一个可见性前缀");
            }
            catch (Exception ex) { 记录异常("程序集 可见性三档", ex); }
        }

        /// <summary> (名称, 内容, 工程) → (名称, 内容):汇编器只吃两列,工程那一列单独当 `工程归属` 传 </summary>
        private static List<(string 名称, string 内容)> 两列(List<(string 名称, string 内容, string 工程)> 表)
            => [.. 表.Select(x => (x.名称, x.内容))];

        // ================= 17) 自举基础:HB 读字节流→计数→十进制输出 =================
        private static void 自举基础自检()
        {
            string? 根 = 找示例目录();
            string? 文件 = 根 == null ? null : Path.Combine(根, "汇编", "自举0_读字节计数", "主程序.hb");
            if (文件 == null || !File.Exists(文件))
            {
                记录("定位 自举0_读字节计数.hb", false, 文件 ?? "未找到 Sample 目录");
                return;
            }
            try
            {
                string 源码 = File.ReadAllText(文件);
                var 输入 = new Queue<uint?>(new uint?[] { (byte)'a', (byte)'b', (byte)'c' });
                var 输出 = new List<byte>();
                var vm = new 虚拟机C { 输入源 = () => 输入.Count > 0 ? 输入.Dequeue() : null, 输出目标 = 输出.Add };
                编译并跑(vm, 源码);
                bool 对 = 输出.Count == 2 && 输出[0] == (byte)'3' && 输出[1] == 0x0A;
                记录("自举0 读abc→输出3+换行", 对,
                    $"输出={string.Join(",", 输出.Select(b => b.ToString("X2")))}");
            }
            catch (Exception ex) { 记录异常("自举0 示例", ex); }

            // 十进制输出边界:空输入 → 0
            try
            {
                string 源码 = File.ReadAllText(文件);
                var 输入0 = new Queue<uint?>();
                var 输出0 = new List<byte>();
                new 虚拟机C { 输入源 = () => 输入0.Count > 0 ? 输入0.Dequeue() : null, 输出目标 = 输出0.Add }
                    .运行(编译(源码));
                bool 零对 = 输出0.Count == 2 && 输出0[0] == (byte)'0' && 输出0[1] == 0x0A;
                记录("自举0 空输入→输出0", 零对, $"输出={string.Join(",", 输出0.Select(b => b.ToString("X2")))}");
            }
            catch (Exception ex) { 记录异常("自举0 空输入", ex); }

            // 自举1:字符串子程序(取串长/串比较)+ 十六进制输出
            string? 文件1 = 根 == null ? null : Path.Combine(根, "汇编", "自举1_字符串与十六进制", "主程序.hb");
            if (文件1 == null || !File.Exists(文件1))
            {
                记录("定位 自举1_字符串与十六进制.hb", false, 文件1 ?? "未找到");
                return;
            }
            try
            {
                string 源码1 = File.ReadAllText(文件1);
                // 输入 "abc":长度 3,与常量 "abc" 相等 → 输出 "00000003\n00000000\n"
                string 期望1 = "00000003\n00000000\n";
                var 输入1 = new Queue<uint?>(期望前缀字节("abc"));
                var 输出1 = new List<byte>();
                new 虚拟机C { 输入源 = () => 输入1.Count > 0 ? 输入1.Dequeue() : null, 输出目标 = 输出1.Add }
                    .运行(编译(源码1));
                string 实1 = new string(输出1.Select(b => (char)b).ToArray());
                记录("自举1 字符串子程序+hex输出", 实1 == 期望1, $"输出=[{实1}]");
            }
            catch (Exception ex) { 记录异常("自举1 字符串/hex", ex); }

            // 自举2:词法取词 + 查指令词表
            string? 文件2 = 根 == null ? null : Path.Combine(根, "汇编", "自举2_词法取词查表", "主程序.hb");
            if (文件2 == null || !File.Exists(文件2))
            {
                记录("定位 自举2_词法取词查表.hb", false, 文件2 ?? "未找到");
                return;
            }
            try
            {
                string 源码2 = File.ReadAllText(文件2);
                string 跑2(string 输入行)
                {
                    var 输入 = new Queue<uint?>(期望前缀字节(输入行));
                    var 输出 = new List<byte>();
                    var vm2 = new 虚拟机C { 输入源 = () => 输入.Count > 0 ? 输入.Dequeue() : null, 输出目标 = 输出.Add };
                    var 码2 = 汇编(源码2);
                    vm2.装载(码2);
                    int 步 = 0;
                    while (!vm2.停机 && 步 < 5000)
                    {
                        vm2.单步();
                        步++;
                    }
                    if (!vm2.停机)
                        throw new Exception($"未停机 PC=0x{vm2.程序计数器:X} R0={vm2.寄存器[0]} R1={vm2.寄存器[1]} R5={vm2.寄存器[5]} R7={vm2.寄存器[7]} SP=0x{vm2.栈指针:X} 步={步}");
                    return new string(输出.Select(b => (char)b).ToArray());
                }
                string 实ADD = 跑2("ADD R0, 1");
                记录("自举2 取词查表 ADD→00000000", 实ADD == "00000000\n", $"输出=[{实ADD}]");
                string 实JMP = 跑2("JMP 标签");
                记录("自举2 取词查表 JMP→00000002", 实JMP == "00000002\n", $"输出=[{实JMP}]");
                string 实未知 = 跑2("NOPE R0");
                记录("自举2 未命中→0xFFFFFFFF", 实未知 == "FFFFFFFF\n", $"输出=[{实未知}]");
            }
            catch (Exception ex) { 记录异常("自举2 取词查表", ex); }

            // 自举3:HB 最小汇编器(HALT/ADD/LOAD_IMMEDIATE)编码结果与 C# 汇编器逐字节一致
            string? 文件3 = 根 == null ? null : Path.Combine(根, "汇编", "自举3_最小汇编器", "主程序.hb");
            if (文件3 == null || !File.Exists(文件3))
            {
                记录("定位 自举3_最小汇编器.hb", false, 文件3 ?? "未找到");
                return;
            }
            try
            {
                string 源码3 = File.ReadAllText(文件3);
                string 待汇编 = "HALT\nADD R1 R2\nLOAD_IMMEDIATE R0 5\nHALT";
                byte[] 期望码 = 汇编(待汇编); // C# 引擎作为对照
                var 输入3 = new Queue<uint?>(待汇编.Select(c => (uint?)c));
                var vm3 = new 虚拟机C { 输入源 = () => 输入3.Count > 0 ? 输入3.Dequeue() : null, 输出目标 = _ => { } };
                var 码3 = 汇编(源码3);
                vm3.装载(码3);
                int 步3 = 0;
                while (!vm3.停机 && 步3 < 200000)
                {
                    vm3.单步();
                    步3++;
                }
                bool 一致 = vm3.停机;
                string? 细节 = null;
                if (一致)
                {
                    for (int i = 0; i < 期望码.Length; i++)
                    {
                        if (vm3.内存[0x2000 + i] != 期望码[i])
                        {
                            一致 = false;
                            细节 = $"第{i}字节:HB=0x{vm3.内存[0x2000 + i]:X2} C#=0x{期望码[i]:X2}";
                            break;
                        }
                    }
                }
                else
                {
                    细节 = $"未停机 PC=0x{vm3.程序计数器:X} 步={步3}";
                }
                细节 ??= $"HB编码={BitConverter.ToString(vm3.内存[0x2000..(0x2000 + 期望码.Length)]).Replace("-", " ")} C#编码={BitConverter.ToString(期望码).Replace("-", " ")}";
                记录("自举3 HB汇编器编码==C#汇编器", 一致, 细节);
            }
            catch (Exception ex) { 记录异常("自举3 HB汇编器", ex); }

            // 自举4:HB 跳转编码(JMP/CALL 数值地址 + JZ)与 C# 一致
            string? 文件4 = 根 == null ? null : Path.Combine(根, "汇编", "自举4_跳转编码", "主程序.hb");
            if (文件4 == null || !File.Exists(文件4))
            {
                记录("定位 自举4_跳转编码.hb", false, 文件4 ?? "未找到");
                return;
            }
            try
            {
                string 源码4 = File.ReadAllText(文件4);
                // 用与 HB 汇编器等价的合法指令子集做逐字节对照(混入伪指令会导致对照失败)
                string 程序4 = "LOAD_IMMEDIATE R0 7\nJMP 12\nCALL 20\nHALT\nJZ R0 4\nADD R1 R2\nLOAD_IMMEDIATE R3 9\nHALT";
                byte[] 期望码4 = 汇编(程序4);
                var 输入4 = new Queue<uint?>(程序4.Select(c => (uint?)c));
                var vm4 = new 虚拟机C { 输入源 = () => 输入4.Count > 0 ? 输入4.Dequeue() : null, 输出目标 = _ => { } };
                var 码4 = 汇编(源码4);
                vm4.装载(码4);
                int 步4 = 0;
                while (!vm4.停机 && 步4 < 300000)
                {
                    vm4.单步();
                    步4++;
                }
                bool 一致4 = vm4.停机;
                string? 细节4 = null;
                if (一致4)
                {
                    for (int i = 0; i < 期望码4.Length; i++)
                    {
                        if (vm4.内存[0x2000 + i] != 期望码4[i])
                        {
                            一致4 = false;
                            细节4 = $"第{i}字节:HB=0x{vm4.内存[0x2000 + i]:X2} C#=0x{期望码4[i]:X2}";
                            break;
                        }
                    }
                }
                else 细节4 = $"未停机 PC=0x{vm4.程序计数器:X} 步={步4}";
                细节4 ??= $"HB编码={BitConverter.ToString(vm4.内存[0x2000..(0x2000 + 期望码4.Length)]).Replace("-", " ")}";
                记录("自举4 HB跳转编码==C#汇编器", 一致4, 细节4);
            }
            catch (Exception ex) { 记录异常("自举4 HB跳转编码", ex); }

            // 自举5:HB 两遍汇编器(标签 + 前向/后向跳转 + CALL)
            string? 文件5 = 根 == null ? null : Path.Combine(根, "汇编", "自举5_标签汇编器", "主程序.hb");
            if (文件5 == null || !File.Exists(文件5))
            {
                记录("定位 自举5_标签汇编器.hb", false, 文件5 ?? "未找到");
                return;
            }
            try
            {
                string 源码5 = File.ReadAllText(文件5);
                // C# 汇编器同样接受标签语法(ASCII 标签;HB 汇编器按字节处理,中文标签需 UTF-8 多字节方案,后续做)
                (bool 一致, string 细节) 跑一遍(string 程序, string 名称)
                {
                    byte[] 期望码 = 汇编(程序);
                    var 输入 = new Queue<uint?>(程序.Select(c => (uint?)c));
                    var vm = new 虚拟机C { 输入源 = () => 输入.Count > 0 ? 输入.Dequeue() : null, 输出目标 = _ => { } };
                    编译并装载(vm, 源码5);
                    int 步 = 0;
                    while (!vm.停机 && 步 < 400000) { vm.单步(); 步++; }
                    if (!vm.停机) return (false, $"未停机 PC=0x{vm.程序计数器:X} 步={步}");
                    for (int i = 0; i < 期望码.Length; i++)
                        if (vm.内存[0x2000 + i] != 期望码[i])
                            return (false, $"第{i}字节:HB=0x{vm.内存[0x2000 + i]:X2} C#=0x{期望码[i]:X2}");
                    return (true, $"HB编码={BitConverter.ToString(vm.内存[0x2000..(0x2000 + 期望码.Length)]).Replace("-", " ")}");
                }

                // ① 前向跳转 + 调用子程序(标签在后)
                string 程序5a = "JMP TAIL\nLOAD_IMMEDIATE R0 1\nCALL SUB\nLOAD_IMMEDIATE R0 9\nTAIL:\nLOAD_IMMEDIATE R1 2\nADD R1 R2\nHALT\nSUB:\nLOAD_IMMEDIATE R3 7\nHALT";
                var (一致5, 细节5) = 跑一遍(程序5a, "前向跳转");
                记录("自举5 HB两遍汇编器(标签)==C#汇编器", 一致5, 细节5);

                // ② 后向跳转 + 自调用 + 两个标签 + 同一标签多次引用
                string 程序5b = "LOAD_IMMEDIATE R0 5\nLOOP:\nLOAD_IMMEDIATE R1 1\nADD R0 R1\nJMP LOOP\nCALL DONE\nDONE:\nJMP DONE\nHALT";
                var (一致5b, 细节5b) = 跑一遍(程序5b, "后向跳转");
                记录("自举5 HB两遍汇编器(后向跳转) ==C#汇编器", 一致5b, 细节5b);

                // ③ H25:中文标签(UTF-8 多字节)。HB 汇编器**本来按字节处理**,词法那一层天然成立
                //    (`0x20` / `0x0A` / `0` 这些分界字节在合法 UTF-8 里不会出现在多字节字符中间);
                //    这里钉住"名字一个字符一个字节能对上 C# 那套 string 比较",往后改台账格式别把它弄丢。
                //    跑 HB 汇编器时输入要送 **UTF-8 字节**(以前那些 ASCII 例子用 (byte)'c' 恰好等价,
                //    中文要是也这么送就会把 3 字节字符截成一个字节)。
                (bool 一致, string 细节) 跑程序(string 程序, string 名称)
                {
                    byte[] 期望码 = 汇编(程序);
                    var 输入 = new Queue<uint?>(Encoding.UTF8.GetBytes(程序).Select(b => (uint?)b));
                    var vm = new 虚拟机C { 输入源 = () => 输入.Count > 0 ? 输入.Dequeue() : null, 输出目标 = _ => { } };
                    编译并装载(vm, 源码5);
                    int 步 = 0;
                    while (!vm.停机 && 步 < 400000) { vm.单步(); 步++; }
                    if (!vm.停机) return (false, $"未停机 PC=0x{vm.程序计数器:X} 步={步}");
                    for (int i = 0; i < 期望码.Length; i++)
                        if (vm.内存[0x2000 + i] != 期望码[i])
                            return (false, $"第{i}字节:HB=0x{vm.内存[0x2000 + i]:X2} C#=0x{期望码[i]:X2}");
                    return (true, $"{名称}={BitConverter.ToString(vm.内存[0x2000..(0x2000 + 期望码.Length)]).Replace("-", " ")}");
                }
                string 程序5c = "JMP 尾部\nLOAD_IMMEDIATE R0 1\nCALL 子程序\nLOAD_IMMEDIATE R0 9\n尾部:\nLOAD_IMMEDIATE R1 2\nADD R1 R2\nHALT\n子程序:\nLOAD_IMMEDIATE R3 7\nHALT";
                var (一致5c, 细节5c) = 跑程序(程序5c, "中文标签");
                记录("自举5 HB两遍汇编器(中文标签)==C#汇编器", 一致5c, 细节5c);

                // ④ H25 边界:名字区是 16 字节 = 名字(≤15 字节)+ 0 终止符。**超长必须"大声说不"**,
                //    不许像以前那样照着名字复制的字节数写下去、把下一个条目 / 地址区悄悄写坏
                //    (实测 6 个中文 = 18 字节时,标签表里留下 `FF FF FF 45` 这种溢出乱码)。
                //    这里钉的是"**没写坏**",不钉具体编码(编码是"引用了一个不存在的标签"的下游结果,
                //    换一条跳转指令就会变):① 超长那条在台账里只留一个 0xFF 哨兵(合法名字的首字节
                //    只可能是 `_` / 字母 / 中文,撞不上);② 这个哨兵**只占第 1 格的第一个字节**,
                //    第二格(0x4014 起)一个字节都不许被它碰;③ 照跑不误(不挂死、不乱跳)。
                string 程序5d = "JMP 超长标签名字啊\nHALT\n超长标签名字啊:\nHALT";
                var 输入5d = new Queue<uint?>(Encoding.UTF8.GetBytes(程序5d).Select(b => (uint?)b));
                var vm5d = new 虚拟机C { 输入源 = () => 输入5d.Count > 0 ? 输入5d.Dequeue() : null, 输出目标 = _ => { } };
                编译并装载(vm5d, 源码5);
                int 步5d = 0;
                while (!vm5d.停机 && 步5d < 400000) { vm5d.单步(); 步5d++; }
                bool 哨兵在 = vm5d.内存[0x4000] == 0xFF;
                bool 第二格没被碰 = vm5d.内存[0x4014..0x4028].All(b => b == 0);
                bool 超长安全 = vm5d.停机 && 哨兵在 && 第二格没被碰;
                记录("自举5 超长标签(>15 字节)不写坏台账:只留 0xFF 哨兵,不溢进第二格", 超长安全,
                    $"停机={vm5d.停机} 步={步5d} 第一格={BitConverter.ToString(vm5d.内存[0x4000..0x4014])} 第二格={BitConverter.ToString(vm5d.内存[0x4014..0x4028])}");
            }
            catch (Exception ex) { 记录异常("自举5 HB两遍汇编器", ex); }
        }

        private static IEnumerable<uint?> 期望前缀字节(string 文本) =>
            文本.Select(c => (uint?)c);

        // 寄存器文件扩到 16(R0~R15,编码字段本为 4 位)
        private static void 寄存器扩充自检()
        {
            跑且断言("R8~R15 可用(R15+R8→R0)", "加载立即数 R15, 9\n加载立即数 R8, 3\n加法 R8, R15\n复制 R0, R8\n停止",
                vm => 记录("R8~R15 可用", vm.寄存器[0] == 12, $"R0={vm.寄存器[0]}"));
            跑且断言("R15 装载 32 位常量", "R15 = 0x12345678\n复制 R0, R15\n停止",
                vm => 记录("R15 32位常量", vm.寄存器[0] == 0x12345678, $"R0=0x{vm.寄存器[0]:X}"));
        }

        // 指令元数据与寄存器单一事实源自检(格式表/反汇编覆盖/寄存器C 一致)
        private static void 元数据自检()
        {
            bool 全覆盖 = true; string? 细节 = null;
            // 通用化第2批(2026-10-10):上界从 0x3F 抬到 **0x47**(整数扩展九条);
            // ISA 扩容批 1/批 2(2026-10-13):抬到 **0x4B**(浮点补齐四条)再抬到 **0x53**(位与字节八条)—— 这一段本来
            // 就把"全部登记格式与名称"当判据,加指令时**这里要跟着抬**(不抬就漏检新那几条)。
            for (int op = 0; op <= 0x62; op++)
            {
                if (指令C.取格式((byte)op) is null || 指令C.取指令中文名((byte)op) is null)
                {
                    全覆盖 = false; 细节 = $"0x{op:X2} 缺格式或名称"; break;
                }
            }
            记录("指令表 0x00~0x62 全部登记格式(含 FP 相对寻址 + 立即数形式 + 比较取值 + 断点 + 宿主调用 + 索引读写 + 右移立即数 + R1-4 间接调用/跳寄存器 + 为零跳转寄存器 + 硬件浮点 8 条 + 整数扩展 9 条 + 浮点补齐 4 条 + 位与字节 8 条 + 内存与比较 6 条 + 无分支与调用 9 条)", 全覆盖, 细节);

            // 每种格式造一条指令做 反汇编 冒烟(应能还原且以中文名开头)
            bool 反汇编通 = true; string? 反汇编细节 = null;
            foreach (var 名 in 指令C.取全部中文指令名())
            {
                byte op = 指令C.取指令码表(名)!.Value;
                uint 词 = (uint)(op << 24) | (1u << 20); // 寄存器域放 R1,其余 0
                byte[] 码 = [(byte)词, (byte)(词 >> 8), (byte)(词 >> 16), (byte)(词 >> 24)];
                string? 行 = 反汇编C.反汇编一条(码, 0, out _);
                if (行 == null || !行.StartsWith(名, StringComparison.Ordinal))
                {
                    反汇编通 = false; 反汇编细节 = $"{名}(0x{op:X2}) → {(行 ?? "(null)")}"; break;
                }
            }
            记录("全部指令可反汇编", 反汇编通, 反汇编细节);

            // 寄存器C:数量与 VM 一致、R16/R8abc/空串 拒绝
            var 探针 = new 虚拟机C();
            bool 寄存器一致 = 探针.寄存器.Length == 寄存器C.数量
                && 寄存器C.名称(15) == "R15"
                && !寄存器C.解析("R16", out _) && !寄存器C.解析("R8abc", out _) && !寄存器C.解析("X", out _)
                && 寄存器C.解析("r7", out int r7) && r7 == 7;
            记录("寄存器C 单一事实源一致", 寄存器一致);
        }

        // M6 变量: 声明/初值/读写/表达式/块级遮蔽/自增/条件,及错误用例
        private static void 变量自检()
        {
            跑且断言("变量 声明初值读回", "变量 总和 = 0x12345678;\nR0 = 总和;\n停止",
                vm => 记录("变量 读回32位", vm.寄存器[0] == 0x12345678, $"R0=0x{vm.寄存器[0]:X}"));
            跑且断言("变量 当循环累加 0..4", "变量 总和 = 0;\n变量 i = 0;\n当 (i < 5) {\n总和 = 总和 + i;\ni = i + 1;\n}\nR0 = 总和;\n停止",
                vm => 记录("变量 循环累加", vm.寄存器[0] == 10, $"R0={vm.寄存器[0]}"));
            跑且断言("变量 双槽互不干扰", "变量 a = 7;\n变量 b = 9;\nR0 = a;\nR1 = b;\n停止",
                vm => 记录("变量 双槽", vm.寄存器[0] == 7 && vm.寄存器[1] == 9, $"R0={vm.寄存器[0]} R1={vm.寄存器[1]}"));
            跑且断言("变量 块级遮蔽", "变量 x = 1;\n变量 外层 = 0;\n如果 (外层 == 0) {\n变量 x = 2;\nR1 = x;\n}\nR2 = x;\n停止",
                vm => 记录("变量 遮蔽", vm.寄存器[1] == 2 && vm.寄存器[2] == 1, $"R1={vm.寄存器[1]} R2={vm.寄存器[2]}"));
            跑且断言("变量 自增 x++", "变量 n = 0;\nn++;\nn++;\nR0 = n;\n停止",
                vm => 记录("变量 自增", vm.寄存器[0] == 2, $"R0={vm.寄存器[0]}"));
            跑且断言("变量 作条件(递减求和)", "变量 n = 4;\n变量 s = 0;\n当 (n > 0) {\ns = s + n;\nn = n - 1;\n}\nR0 = s;\n停止",
                vm => 记录("变量 条件递减", vm.寄存器[0] == 10, $"R0={vm.寄存器[0]}"));
            跑且断言("变量 表达式(与其它变量混合)", "变量 s = 0;\n变量 a = 6;\n变量 b = 7;\ns = a * b;\nR0 = s;\n停止",
                vm => 记录("变量 混合表达式", vm.寄存器[0] == 42, $"R0={vm.寄存器[0]}"));

            // 编辑器"＋片段展开"场景:块引用外层变量,应携带外部绑定与槽号基数展开成功(槽号接续)
            {
                bool 片段通 = false; string? 片段细节 = null;
                try
                {
                    var 绑定 = new Dictionary<string, 变量绑定C> { ["计数"] = new 变量绑定C(new 变量槽定义("_v1", 类型C.字宽度), null) };
                    var 片段 = 中间层C.展开完整("当 (计数 < 5) {\n计数 = 计数 + 1;\n}\n", 绑定, 1);
                    片段通 = 片段.汇编文本.Contains("LOAD_WORD") && 片段.汇编文本.Contains("_v1") && 片段.变量槽.Count == 0;
                }
                catch (Exception ex) { 片段细节 = ex.Message; }
                记录("变量 片段展开携带外层上下文", 片段通, 片段细节);
            }

            // 回归:部分展开(＋)后再整篇汇编,内部标签必须续接编号,不得"标签重复定义"
            {
                bool 通 = false; string? 细节 = null;
                try
                {
                    string 块 = "变量 i = 0;\n循环 (i = 1; i <= 5; i = i + 1) {\n加立即数 R0, 1\n}\n";
                    var (标, 选) = 中间层C.展开编号起点(块);
                    string 展开块 = 中间层C.展开完整(块, null, null, 0, 标, 选).汇编文本.Trim() + "\n// 中间层恢复点:1\n";
                    string 全文 = 展开块 + "变量 j = 0;\n循环 (j = 1; j <= 3; j = j + 1) {\n加立即数 R0, 1\n}\n停止";
                    var vm = 运行(全文);
                    通 = vm.寄存器[0] == 8;
                    if (!通) 细节 = $"R0={vm.寄存器[0]}";
                }
                catch (Exception ex) { 细节 = ex.Message; }
                记录("展开块+残留块 同篇汇编不重复标签", 通, 细节);
            }

            期望异常("变量 同作用域重复声明报错", () => 汇编("变量 a = 1;\n变量 a = 2;\n停止"), "重复声明");
            期望异常("变量 未声明使用报错", () => 汇编("b = 1;\n停止"), "未声明");
            期望异常("变量 名冲突寄存器报错", () => 汇编("变量 R3 = 1;\n停止"), "不能与寄存器");
            期望异常("变量 名冲突关键字报错(第96批:文案说清是哪类保留字 + 给改法)",
                () => 汇编("变量 当 = 1;\n停止"), "不能用语言关键字", "换个名字");
            期望异常("变量 名冲突老关键字报错(记录 → 结构 改过名,名字仍占位)",
                () => 汇编("整数 记录 = 1;\n停止"), "不能用老关键字", "记录值");
            期望异常("变量 名冲突 ISA 指令名报错(存字/取字 是助记符)",
                () => 汇编("整数 存字 = 1;\n停止"), "不能用ISA 指令名", "换个名字");
            期望异常("变量 名冲突 字符串(附加类型名,不在关键字表里)也拦住",
                () => 汇编("整数 字符串 = 1;\n停止"), "不能用类型名", "字符串值");
            期望异常("变量 英文名撞关键字也拦住(int/if/record)",
                () => 汇编("整数 int = 1;\n停止"), "不能用类型名", "int_");
            记录("保留字 清单只有一份、去重、四类都覆盖(关键字/类型名/老关键字/指令名)",
                中间层指令C.全部保留字.Length == 中间层指令C.全部保留字.Distinct(StringComparer.Ordinal).Count()
                && 中间层指令C.全部保留字.Count(x => x == "返回") == 1      // `返回` 既是关键字也是 RET,只算一条
                && 中间层指令C.全部保留字.Contains("遍历") && 中间层指令C.全部保留字.Contains("foreach")
                && 中间层指令C.全部保留字.Contains("整数") && 中间层指令C.全部保留字.Contains("int")
                && 中间层指令C.全部保留字.Contains("记录") && 中间层指令C.全部保留字.Contains("record")
                && 中间层指令C.全部保留字.Contains("字符串") && 中间层指令C.全部保留字.Contains("string")
                && 中间层指令C.全部保留字.Contains("返回") && 中间层指令C.全部保留字.Contains("RET")
                && 中间层指令C.保留字对.Length == 中间层指令C.关键字表.Length + 中间层指令C.附加类型名表.Length + 中间层指令C.历史词表.Length,
                $"保留字 {中间层指令C.保留字个数} 个(关键字 {中间层指令C.关键字表.Length} + 类型名 {中间层指令C.附加类型名表.Length} + 老关键字 {中间层指令C.历史词表.Length} + 指令名去重)");
            记录("保留字 建议的替代名自己不是保留字",
                中间层指令C.建议变量名("当") == "当值" && !中间层指令C.是保留字(中间层指令C.建议变量名("当"))
                && 中间层指令C.建议变量名("int") == "int_" && !中间层指令C.是保留字(中间层指令C.建议变量名("int"))
                && 中间层指令C.为什么是保留字("遍历") is { } 遍历原因 && 遍历原因.Contains("语言关键字")
                && 中间层指令C.为什么是保留字("普通名字") == null,
                "当→当值 / int→int_");
            期望异常("声明 等号右边空着要报错(不再静默当 0)", () => 汇编("整数 初值 =;\n停止;"), "等号右边是空的");
            期望异常("声明 空右值报错时给两种改法", () => 汇编("整数 初值 =;\n停止;"), "把等号去掉");
            期望异常("数组声明 带空等号报错(数组本来就不能带初值)", () => 汇编("整数 表[3] =;\n停止;"), "去掉");
            期望异常("声明 连结尾的 ';' 都没有 → 报'没写完'(和空右值是两回事)",
                () => 汇编("整数 初值 =\n停止"), "没等到 ';'");
            跑输出断言("声明 不带初值照常能跑(默认 0)", "整数 初值;\n测试输出(初值);\n停止;", "0");
            // 初值现在允许写表达式(算进临时再按宽度写回),不再是报错;这里顺带验证一下确实生效
            跑输出断言("变量 初值可用表达式", "变量 源 = 7;\n变量 x = 源 + 1;\n测试输出(x);\n停止", "8");
        }

        // M7a 基本类型:字节/逻辑/字符/短整数 —— 宽度、字面量、零扩展/截断、紧致布局、常量范围
        private static void 类型自检()
        {
            跑且断言("字节 声明读回 200", "字节 数 = 200;\nR0 = 数;\n停止",
                vm => 记录("字节 读回", vm.寄存器[0] == 200, $"R0={vm.寄存器[0]}"));
            跑且断言("字符 字面量 'A'", "字符 键 = 'A';\nR0 = 键;\n停止",
                vm => 记录("字符 'A'", vm.寄存器[0] == 65, $"R0={vm.寄存器[0]}"));
            跑且断言("字符 转义 '\\n' 与 '\\x41'", "字符 换行 = '\\n';\n字符 字母 = '\\x41';\nR0 = 换行;\nR1 = 字母;\n停止",
                vm => 记录("字符 转义", vm.寄存器[0] == 10 && vm.寄存器[1] == 65, $"R0={vm.寄存器[0]} R1={vm.寄存器[1]}"));
            跑且断言("逻辑 真/假 与条件", "逻辑 好了 = 真;\n逻辑 坏了 = 假;\nR0 = 好了;\n如果 (坏了) {\n加载立即数 R1, 9\n}\n否则 {\n加载立即数 R1, 7\n}\n停止",
                vm => 记录("逻辑 真/假", vm.寄存器[0] == 1 && vm.寄存器[1] == 7, $"R0={vm.寄存器[0]} R1={vm.寄存器[1]}"));
            跑且断言("短整数 常量读写 0x1234", "短整数 值 = 0x1234;\nR0 = 值;\n停止",
                vm => 记录("短整数 读回", vm.寄存器[0] == 0x1234, $"R0={vm.寄存器[0]}"));
            跑且断言("短整数 变量赋值截断", "短整数 值 = 0;\n整数 源 = 0x12345;\n值 = 源;\nR0 = 值;\n停止",
                vm => 记录("短整数 截断", vm.寄存器[0] == 0x2345, $"R0={vm.寄存器[0]}"));
            跑且断言("字节 变量赋值截断", "字节 值 = 0;\n整数 源 = 0x1FF;\n值 = 源;\nR0 = 值;\n停止",
                vm => 记录("字节 截断", vm.寄存器[0] == 0xFF, $"R0={vm.寄存器[0]}"));
            跑且断言("字符 自增('A'→'B')", "字符 字母 = 'A';\n字母 = 字母 + 1;\nR0 = 字母;\n停止",
                vm => 记录("字符 自增", vm.寄存器[0] == 66, $"R0={vm.寄存器[0]}"));

            // 紧致布局:字节(1) + 短整数(2) 相邻,地址只差 1
            {
                var 器 = new 汇编器C();
                var 码 = 器.汇编("字节 字节值 = 1;\n短整数 短整值 = 2;\n停止");
                器.标签表.TryGetValue("_v1", out int 左址);
                器.标签表.TryGetValue("_v2", out int 右址);
                bool 紧 = 左址 > 0 && 右址 > 0 && 右址 - 左址 == 1 && 左址 + 3 == 码.Length;
                记录("类型 紧致布局(1+2字节)", 紧, $"左址=0x{左址:X} 右址=0x{右址:X} 码长={码.Length}");
            }

            期望异常("字节 常量越界报错", () => 汇编("字节 量 = 300;\n停止"), "超出");
            期望异常("短整数 常量越界报错", () => 汇编("短整数 量 = 70000;\n停止"), "超出");
            期望异常("逻辑 常量只能是 0/1", () => 汇编("逻辑 旗 = 2;\n停止"), "逻辑");
            期望异常("类型名不能当变量名", () => 汇编("字节 字符 = 1;\n停止"), "不能用类型名");
        }

        // M7b 结构:纯数据、字段按声明序紧排、编译期偏移访问
        private static void 结构自检()
        {
            跑且断言("结构 字段读写", "结构 点 {\n短整数 x;\n短整数 y;\n}\n点 位置;\n位置.x = 3;\n位置.y = 4;\nR0 = 位置.x;\nR1 = 位置.y;\n停止",
                vm => 记录("结构 字段读写", vm.寄存器[0] == 3 && vm.寄存器[1] == 4, $"R0={vm.寄存器[0]} R1={vm.寄存器[1]}"));
            跑且断言("结构 混合宽度字段+条件", "结构 头 {\n字节 类型;\n短整数 值;\n}\n头 头记录;\n头记录.类型 = 7;\n头记录.值 = 300;\nR0 = 头记录.类型;\n如果 (头记录.值 == 300) {\n加载立即数 R1, 1\n}\n停止",
                vm => 记录("结构 混合宽度", vm.寄存器[0] == 7 && vm.寄存器[1] == 1, $"R0={vm.寄存器[0]} R1={vm.寄存器[1]}"));
            跑且断言("结构 字段自增", "结构 计数器 {\n字节 n;\n}\n计数器 实例;\n实例.n++;\n实例.n++;\nR0 = 实例.n;\n停止",
                vm => 记录("结构 字段自增", vm.寄存器[0] == 2, $"R0={vm.寄存器[0]}"));
            跑且断言("结构 字段赋值截断", "结构 格子 {\n字节 b;\n}\n格子 格子值;\n整数 源 = 0x1FF;\n格子值.b = 源;\nR0 = 格子值.b;\n停止",
                vm => 记录("结构 字段截断", vm.寄存器[0] == 0xFF, $"R0={vm.寄存器[0]}"));
            跑且断言("结构 字段参与表达式", "结构 点 {\n短整数 x;\n短整数 y;\n}\n点 位置;\n位置.x = 2;\n位置.y = 4;\nR0 = 位置.x + 位置.y;\n停止",
                vm => 记录("结构 字段表达式", vm.寄存器[0] == 6, $"R0={vm.寄存器[0]}"));

            // 紧致布局:字段 1+2+1=4 字节,结构变量槽正好占 4 字节并紧贴代码段尾
            {
                var 器 = new 汇编器C();
                var 码 = 器.汇编("结构 混 {\n字节 a;\n短整数 b;\n字节 c;\n}\n混 混记录;\n停止");
                器.标签表.TryGetValue("_v1", out int 左址);
                bool 紧 = 左址 > 0 && 左址 + 4 == 码.Length;
                记录("结构 紧致布局(1+2+1=4字节)", 紧, $"左址=0x{左址:X} 码长={码.Length}");
            }

            期望异常("结构 未知字段报错", () => 汇编("结构 点 {\n字节 x;\n}\n点 位置;\n位置.y = 1;\n停止"), "没有字段");
            期望异常("结构 变量非零初值报错", () => 汇编("结构 点 {\n字节 x;\n}\n点 位置 = 5;\n停止"), "对字段分别赋值");
            记录("结构 能从同一种结构的另一份拷过来(点 副本 = 位置)",
                汇编("结构 点 {\n整数 x;\n}\n点 位置;\n位置.x = 9;\n点 副本 = 位置;\n停止").Length > 0, "编得过");
            期望异常("结构 字段重复报错", () => 汇编("结构 点 {\n字节 x;\n字节 x;\n}\n停止"), "字段重复");
            期望异常("结构 字段未知类型报错", () => 汇编("结构 点 {\n怪兽 x;\n}\n停止"), "未知的字段类型");
            期望异常("结构 名冲突报错", () => 汇编("结构 字节 {\n字节 x;\n}\n停止"), "结构名冲突");
        }

        // ================= 15.8) 整数边界(用户拍板的 D1)+ 运行期错误文案 =================
        /// <summary>
        /// 第88批(内核加固计划批 3):把"用户看得见、但以前既没写进用户文档也没钉过"的整数边界语义钉死。
        /// 语义是**用户拍板的**(`内核加固与语法收口计划.md` D1):
        ///   ① 溢出按**按声明宽回绕**、赋值**按声明宽截断**、未初始化是 **0**(保持现状,只补断言);
        ///   ② 移位:常量次数越界(不在 0~31)**编译期报错**;变量次数运行期取**低 5 位**(不动 ISA、不多发指令);
        ///      窄类型仍在 32 位槽里移位、结果按声明宽截断(短整数 1&lt;&lt;17 = 0);
        ///   ③ 运行期错误(除零/栈空)文案**不许漏内部指令名(DIV/MOD)与裸 PC**,查得到行号就必须带行号
        ///      (实测老样子是 `执行错误 (PC=0x03D8): 除零错误 (DIV)`,既没行号也漏内部名)。
        /// </summary>
        private static void 整数边界自检()
        {
            // ① 溢出 / 截断 / 未初始化(语义已定:回绕 + 截断 + 清零)
            try
            {
                跑输出断言("边界 短整数 32767+1 回绕成 -32768", "short 数 = 32767;\n数 = 数 + 1;\n测试输出(数);\n停止", "-32768");
                跑输出断言("边界 短整数 -32768-1 回绕成 32767", "short 数 = -32768;\n数 = 数 - 1;\n测试输出(数);\n停止", "32767");
                跑输出断言("边界 32 位乘法回绕(0xFFFFFFFF*2 = -2)", "int 数 = 0;\n数 = 0xFFFFFFFF;\n数 = 数 * 2;\n测试输出(数);\n停止", "-2");
                跑输出断言("边界 赋给字节按声明宽截断(300 → 44)", "byte 数 = 0;\n数 = 300;\n测试输出(数);\n停止", "44");
                跑输出断言("边界 没赋值的变量初值是 0", "int 数;\n测试输出(数);\n停止", "0");
            }
            catch (Exception ex) { 记录异常("边界 溢出与截断", ex); }

            // ② 移位:常量越界编译期报错(带行号),变量次数仍取低 5 位,窄类型按声明宽截断
            try
            {
                期望异常("边界 常量左移 33 位 → 编译期报错", () => 汇编("int 数 = 1 << 33;\n停止"), "移位次数", "0~31");
                期望异常("边界 常量左移 32 位 → 编译期报错", () => 汇编("int 数 = 1 << 32;\n停止"), "移位次数");
                期望异常("边界 常量左移 -1 位 → 编译期报错(负数也算越界)", () => 汇编("int 数 = 1 << -1;\n停止"), "移位次数");
                期望异常("边界 常量右移越界 → 编译期报错", () => 汇编("int 数 = 1024 >> 40;\n停止"), "移位次数");
                期望异常在第几行("边界 移位越界报错带对行号(界面靠它画红线)",
                    "int 数 = 1;\nint 移位量 = 1 << 33;\n停止", 2);
                跑输出断言("边界 变量移位次数仍取低 5 位(1<<33 = 2)", "int 数 = 0;\nint 移位量 = 33;\n数 = 1 << 移位量;\n测试输出(数);\n停止", "2");
                跑输出断言("边界 窄类型移位在 32 位槽里做、按声明宽截断(短整数 1<<17 = 0)",
                    "short 数 = 1;\n数 = 数 << 17;\n测试输出(数);\n停止", "0");
            }
            catch (Exception ex) { 记录异常("边界 移位", ex); }

            // ③ 运行期错误文案:带行号、说人话、不漏内部指令名
            try
            {
                var 编译结果 = 编译("int 被除数 = 7;\nint 除数 = 0;\n被除数 = 被除数 / 除数;\n测试输出(被除数);\n停止");
                var 机 = new 虚拟机C();
                机.取源行号 = 地址 => 执行行映射C.查源行(编译结果.调试文件表, 地址);   // 命令行/IDE 挂的是同一个回调
                string 文案 = "";
                try { 机.运行(编译结果); }
                catch (运行期错误C 运行错) { 文案 = 运行错.用户文案; }
                记录("边界 语言层除零:文案带行号 + 说人话", 文案.StartsWith("第 3 行:") && 文案.Contains("除零"), 文案);
                记录("边界 运行期错误文案不漏内部指令名与裸 PC",
                    !文案.Contains("DIV") && !文案.Contains("MOD") && !文案.Contains("PC=")
                    && !文案.Contains("InvalidOperation"), 文案);

                string 汇编文案 = "";
                try { 运行("加载立即数 R0, 7\n加载立即数 R1, 0\n除法 R0, R1\n停止"); }
                catch (运行期错误C 运行错) { 汇编文案 = 运行错.说明; }
                记录("边界 汇编层除零也不再是裸异常、不漏 DIV",
                    汇编文案.Contains("除零") && !汇编文案.Contains("DIV") && !汇编文案.Contains("PC="), 汇编文案);

                string 栈文案 = "";
                try { 运行("出栈 R0\n停止"); }
                catch (运行期错误C 运行错) { 栈文案 = 运行错.说明; }
                记录("边界 空栈报错也是运行期错误(说人话 + 给改法)",
                    栈文案.Contains("栈为空") && 栈文案.Contains("配对"), 栈文案);
            }
            catch (Exception ex) { 记录异常("边界 运行期错误文案", ex); }

            // ⑤ D2:`--run` 的退出码 —— 跑完但错误槽里有号(断言失败 / 被运行期守卫拦下)必须非 0。
            //    行为本身只能**另起进程**才验得到(自检是进程内跑引擎的),真正的端到端验证在
            //    `工具\四组合冒烟.ps1` 的「D2:--run 退出码」那一节(写两个 ASCII 探针,断言 0 / 非 0);
            //    这里钉的是"CLI 里确实有这条判定 + 用法文本写了新约定",防它被后来的改动悄悄拿掉。
            try
            {
                string? 根 = 找示例目录();
                string? cli = 根 == null ? null : Path.Combine(Directory.GetParent(根)?.FullName ?? 根, "编译器CLI", "Program.cs");
                if (cli == null || !File.Exists(cli))
                    跳过("边界 D2 --run 退出码", $"找不到 {cli}");
                else
                {
                    string 源码 = File.ReadAllText(cli);
                    记录("边界 D2 --run:跑完但没通过(错误槽有号)会把退出码置成非 0",
                        源码.Contains("跑完没通过"), "--run 的退出码判定还在");
                    记录("边界 D2 用法文本写了新的退出码约定(跑完但没通过)",
                        源码.Contains("跑完但没通过"), "--help 里写了");
                }
            }
            catch (Exception ex) { 记录异常("边界 D2 退出码", ex); }

            // ④ 用户文档里必须有这几句话(帮助速查是代码里的一份文本,能直接断言)
            try
            {
                string 速查 = 帮助文本C.中间层速查();
                记录("边界 帮助速查写了溢出回绕(和 C 一样不报错)", 速查.Contains("到边界会回绕"));
                记录("边界 帮助速查写了移位次数口径(变量取低 5 位 / 常量越界报错)",
                    速查.Contains("移位次数按 0~31 算") && 速查.Contains("移位次数 33 超出 0~31"));
                记录("边界 帮助速查写了截断与未初始化是 0", 速查.Contains("按声明宽截断") && 速查.Contains("初值都是 **0**"));
                记录("边界 帮助速查写了除零是运行期错误(带行号)", 速查.Contains("除零(除数是 0"));
            }
            catch (Exception ex) { 记录异常("边界 帮助文案", ex); }
        }

        // ================= 规模统计(P31) =================
        private static void 规模统计自检()
        {
            // 防回归:更新报告 曾在循环里把"结束标记到文件尾"整段提前追加一次,收尾又追加一次,
            // 每跑一遍 --更新报告,标记之后的正文就翻一倍(实测 全面测评报告.md 长到 43MB / 正文 2048 份)。
            try
            {
                string 临时 = Path.Combine(临时区C.基目录(), "hb_selftest_stats_report.md");
                string 尾巴 = "## 2、正确性(自动验证)\n一些内容\n\n## 8、下一步\n完\n";
                string 原文 = $"# 报告\n\n{规模统计C.开始标记}\n旧表\n{规模统计C.结束标记}\n{尾巴}";
                File.WriteAllText(临时, 原文);
                规模统计C.更新报告(临时, "新表");
                规模统计C.更新报告(临时, "新表");   // 连跑两遍也不能长个
                string 改后 = File.ReadAllText(临时);
                bool 对 = 改后.Contains("新表") && !改后.Contains("旧表")
                    && 改后.Length == 原文.Length
                    && 改后.EndsWith(尾巴, StringComparison.Ordinal);
                记录("规模统计 更新报告连跑两遍不长大(只改标记之间)", 对,
                    $"长度 {原文.Length} → {改后.Length}");
                File.Delete(临时);
            }
            catch (Exception ex) { 记录异常("规模统计 更新报告", ex); }

            // 没有标记对的文件要明说,不许猜位置乱插
            期望异常("规模统计 没有标记要报错(不去猜该插哪儿)",
                () =>
                {
                    string 临时 = Path.Combine(临时区C.基目录(), "hb_selftest_stats_nomarker.md");
                    File.WriteAllText(临时, "# 报告\n没有标记\n");
                    try { 规模统计C.更新报告(临时, "表"); }
                    finally { File.Delete(临时); }
                }, "找不到自动统计的标记");

            // ---- 第434批:HB 机器码产物**不按源码数** ----
            // 病根:IDE 的「打包方式 → 只编译」(宿主那条腿)把产物落成 `<项目目录>\<工程名>.hb`,
            // 后缀与源码一样 ⇒ 它被当源码数进去,`文档数字`(161 → 162)与 `示例回归`(多一次跳过)
            // 两条当场红灯。判据 = 前两字节 `48 42`(**二进制不是源码**),口径只有一处:`源码文件C`。
            // 这里拿一个临时目录现造三个文件:两份真文本 + 一份带 HB 头的二进制(内容随便,只看头)。
            try
            {
                string 目录 = Path.Combine(临时区C.基目录(), "hb_selftest_srccount");
                Directory.CreateDirectory(目录);
                File.WriteAllText(Path.Combine(目录, "主程序.hb"), "停止\n");
                File.WriteAllText(Path.Combine(目录, "库.hb"), "停止\n");
                File.WriteAllBytes(Path.Combine(目录, "工程名.hb"), [0x48, 0x42, 0x01, 0x00, 0xAA, 0xBB]);
                File.WriteAllText(Path.Combine(目录, "工程名.hbp"), "{\n}\n");
                int 源码数 = 规模统计C.数个数(目录, ".hb");
                int 工程数 = 规模统计C.数个数(目录, ".hbp");
                int 列出来 = 源码文件C.列源码(目录).Length;
                bool 对 = 源码数 == 2 && 工程数 == 1 && 列出来 == 2;
                记录("第434批 HB 机器码产物不按源码数(`只编译` 落下的 `<工程名>.hb` 要跳过)",
                    对,
                    对
                        ? $"3 份 .hb 里 2 份文本数出 {源码数} 个、带 HB 头那份跳过;`.hbp` {工程数} 个;`列源码` 也给出 {列出来} 个"
                        : $"`.hb` 数出 {源码数}(期望 2)/ `.hbp` {工程数}(期望 1)/ `列源码` {列出来}(期望 2)");
                Directory.Delete(目录, true);
            }
            catch (Exception ex) { 记录异常("第434批 机器码产物不按源码数", ex); }

            // F2(第135批):报告里那张表**不许过期** —— 拿"当前统计"与报告标记之间那段逐行比。
            //   · **自检那一行跳过**:报告里写的是"上一遍 `--更新报告` 跑出来的条数",本进程此刻还没跑完,比不了
            //     (它的新鲜度由"每批跑一次 `--更新报告`"这条纪律保证);
            //   · 其余各行(指令数 / 关键字 / 工程数 / 各目录行数 / 内存模型)必须逐字相同 ——
            //     忘了更新就红灯(以前报告里一直挂着"自检 1142 条 / 55 个工程"的旧数字,靠人记得刷新)。
            try
            {
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                string 报告路径 = 根 == null ? "" : Path.Combine(根, "全面测评报告.md");
                if (根 == null || !File.Exists(报告路径))
                {
                    跳过("规模统计 报告的规模表没过期(工作副本之外跑自检时跳过)", "找不到 全面测评报告.md");
                }
                else
                {
                    string 报告文本 = File.ReadAllText(报告路径);
                    int 起 = 报告文本.IndexOf(规模统计C.开始标记, StringComparison.Ordinal);
                    int 止 = 起 < 0 ? -1 : 报告文本.IndexOf(规模统计C.结束标记, 起 + 规模统计C.开始标记.Length, StringComparison.Ordinal);
                    if (起 < 0 || 止 < 0)
                    {
                        记录("规模统计 报告的规模表没过期(与当前统计逐字一致)", false, "报告里找不到自动统计的一对标记");
                    }
                    else
                    {
                        string 现表 = 报告文本.Substring(起 + 规模统计C.开始标记.Length, 止 - 起 - 规模统计C.开始标记.Length).Trim();
                        string 该表 = 规模统计C.生成表(根).Trim();
                        string 去自检行(string 表) => string.Join("\n",
                            表.Split('\n').Where(x => !x.TrimStart().StartsWith("| 自检 |", StringComparison.Ordinal)));
                        string 现表文 = 去自检行(现表), 基线文 = 去自检行(该表);
                        记录("规模统计 报告的规模表没过期(与当前统计逐字一致;自检那行由 `--更新报告` 写)",
                            现表文 == 基线文,
                            现表文 == 基线文 ? "逐字一致" : "报告里的表与当前统计不一样 —— 跑 `hbcc --stats --更新报告`");
                    }
                }
            }
            catch (Exception ex) { 记录异常("规模统计 报告表新鲜度", ex); }
        }

        // ================= 文档数字(R4-6,第197批) =================

        /// <summary>
        /// R4-6:把"人写的摘要数字"也纳入机检。
        ///
        /// 背景:原先的机检只盖住"机器生成的产物"(规模表 / 帮助站点 / 断言清单指纹 / 命名禁用词表),
        /// 摘要数字是**手抄**的 —— 清完一茬又烂一茬(批 177 清完 13 处,批 195 又冒出 16 处)。
        /// 现在的口径是 **能被机检的留下,不能的被删掉**:
        /// <list type="number">
        /// <item>**可数的全部挪进 `接手说明.md` §4 那个生成块**(`hbcc --stats --更新报告` 写),
        ///   本检查拿盘上那份跟现场生成**逐字比** —— 手改一个数字就红灯;
        ///   自检那三个数(`通过 / 失败 / 跳过`)只有跑完一遍才知道,而这条断言就在那一遍里面跑,
        ///   所以**取盘上的值回填再比**(等于不比),另用 **`通过 + 失败 + 跳过 == 条数`** 这个等式钉住
        ///   (条数来自 `工具\自检断言清单.txt`;R4-4 保证断言名唯一,于是等式成立)。</item>
        /// <item>**不可数的从文档里删掉**(五端 0 错误 / WPF 警告数 / 自检耗时 / 代码行数明细),
        ///   别处一律只许指路 —— 三个"摘要位"里凡出现 `数字 + 量词` 就红灯(生成块先整段切掉)。
        ///   三份 ISA 文档正文里本来就有大量合法的 `4 字节` 之类,按量词扫会满屏误报,
        ///   所以那里改扫一份**退役短语表**(清掉的那几句原话,一句都不许回来)。</item>
        /// </list>
        /// </summary>
        private static void 文档数字自检()
        {
            string? 示例 = 找示例目录();
            string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;

            // ---- ① `接手说明.md` §4 的"当前数字"不许过期 ----
            // **T21(2026-09-27 评测整改)起这条不在这儿了** —— 它要看"本次运行的最终三个数",
            // 而这一组排在中段(后面还有几十组没跑)。现在它在 `综合自检C.运行()` 的**收尾那一段**
            // (与 T19 跳过护栏 / T22 断言分列一起),名字叫
            // 「文档数字 接手说明的当前数字是**本次运行的结果**(手改一个数就红灯)」。
            // 这一组只剩"别处不许再手抄一份数字"那半。

            // ---- ② 摘要位不许再手抄数字 ----
            try
            {
                const string 本检查 = "文档数字 摘要位不许再手抄数字(生成块之外,一处不留)";
                var 违规 = new List<string>();

                // 数字 + 量词 = "看起来像摘要"的写法;量词表只收摘要里会用的那几个,不追求穷尽 ——
                // 目的是"再抄一份"当场可见,而不是把文档里所有数字都禁掉(生成块先整段切掉)。
                var 数字量词 = new Regex(@"[0-9]+\s*(条|个|档|类|节点|字节|字符|万行|次)");
                var 位 = new (string 文件, string 起, string 止, string 说明)[]
                {
                    ("接手说明.md", "## 4、当前数字", "## 5、下一步", "接手说明 §4"),
                    ("任务清单.md", "> **当前状态:", "## 0、清单结构", "任务清单 文件头"),
                    ("全面测评报告.md", "## 2、正确性(自动验证)", "## 3、性能", "全面测评报告 §2"),
                    // T24(2026-09-27 评测整改第 4 阶段):`帮助核对表.md` 的**基线那一小段**曾经手抄着
                    // "ISA 53 / 内建 24 / 标准工程 62 / 五端 0 错误"——四个数全过期(真值 55 / 34 / 32 / 六端)。
                    // 改法照 R4-6:那一小段只许**指路**(见 §4),数字一个都不留;下面各表里那些是"核对当时"的历史,不算。
                    ("帮助核对表.md", "> **基线**", "> **出处写法**", "帮助核对表 基线"),
                };
                foreach (var (文件, 起, 止, 说明) in 位)
                {
                    string 路径 = 根 == null ? "" : Path.Combine(根, 文件);
                    if (根 == null || !File.Exists(路径)) { 违规.Add($"{文件}: 找不到"); continue; }
                    string 文本 = File.ReadAllText(路径);
                    // 两个生成块整段切掉:那里面全是数字,而且都是被机检过的
                    foreach (var (块起, 块止) in new[]
                             {
                                 (当前数字C.开始标记, 当前数字C.结束标记),
                                 (规模统计C.开始标记, 规模统计C.结束标记),
                             })
                    {
                        string? 块 = 标记块C.取(文本, 块起, 块止);
                        if (块 != null) 文本 = 文本.Replace(块, "", StringComparison.Ordinal);
                    }
                    int a = 文本.IndexOf(起, StringComparison.Ordinal);
                    int b = a < 0 ? -1 : 文本.IndexOf(止, a + 起.Length, StringComparison.Ordinal);
                    if (a < 0 || b < 0) { 违规.Add($"{说明}: 找不到那一段"); continue; }
                    foreach (Match m in 数字量词.Matches(文本.Substring(a, b - a)))
                        违规.Add($"{说明}:`{m.Value.Trim()}`");
                }

                // 三份 ISA 文档:整篇扫"退役短语"(清掉的那几句原话)
                string[] 退役短语 = ["共 53 条", "当前使用 53 个", "当前数据(第195批刷新)"];
                foreach (string 文件 in new[] { "指令集说明.md", "指令集.md", "指令集与中间层扩展方案.md" })
                {
                    string 路径 = 根 == null ? "" : Path.Combine(根, 文件);
                    if (根 == null || !File.Exists(路径)) { 违规.Add($"{文件}: 找不到"); continue; }
                    string 文本 = File.ReadAllText(路径);
                    foreach (string 短语 in 退役短语)
                        if (文本.Contains(短语, StringComparison.Ordinal)) 违规.Add($"{文件}:`{短语}`");
                }

                记录(本检查, 违规.Count == 0, 违规.Count == 0
                    ? "三个摘要位 0 处;三份 ISA 文档的退役短语 0 处"
                    : string.Join(" / ", 违规.Take(4)) + (违规.Count > 4 ? $" … 共 {违规.Count} 处" : ""));
            }
            catch (Exception ex) { 记录异常("文档数字 摘要位", ex); }

            // ---- ③ README 这扇门:它点到的旗标与仓库内路径都得还在 ----
            // 为什么钉:README 是"陌生人照着一遍就能编出来"的那扇门,里面的命令一旦过期就是**假路**
            // (`hbcc` 的旗标改过名、文档里那几个文件搬过家,README 不会自己知道)。这一条只查
            // "点到的名字还在不在",**不查措辞** —— 文字怎么改都不该红灯。
            try
            {
                const string 本检查 = "文档数字 README 点到的旗标与仓库内路径都还在";
                string 读我 = 根 == null ? "" : Path.Combine(根, "README.md");
                if (根 == null || !File.Exists(读我)) 记录(本检查, false, "找不到 README.md");
                else
                {
                    string 文 = File.ReadAllText(读我);
                    string 命令行源 = File.ReadAllText(Path.Combine(根, "编译器CLI", "Program.cs"));
                    var 违规 = new List<string>();

                    // ① 带 `hbcc` 的那些行里出现的 `--旗标`,CLI 必须真认(别的命令行工具不归它管)
                    foreach (string 行 in 文.Replace("\r\n", "\n").Split('\n'))
                    {
                        if (!行.Contains("hbcc", StringComparison.Ordinal)) continue;
                        foreach (Match m in Regex.Matches(行, @"--[A-Za-z\u4e00-\u9fa5]+"))
                            if (!命令行源.Contains($"\"{m.Value}\"", StringComparison.Ordinal))
                                违规.Add($"旗标 `{m.Value}` CLI 不认");
                    }

                    // ② 反引号里那些"仓库内的"路径都要真在盘上(编出来的产物不算:`bin\` / `obj\` 一律跳过)
                    foreach (Match m in Regex.Matches(文, @"`([^`\n]+)`"))
                    {
                        string 项 = m.Groups[1].Value.Trim();
                        bool 带分隔 = 项.Contains('\\') || 项.Contains('/');
                        bool 裸名字 = Regex.IsMatch(项, @"^[\u4e00-\u9fa5A-Za-z][\w\u4e00-\u9fa5]*\.(md|ps1|csproj|slnx|hb|hbp|c|txt|json)$");
                        if (!带分隔 && !裸名字) continue;                      // `.hb` 这种只提后缀的不算路径
                        if (项.Contains("bin\\") || 项.Contains("obj\\")) continue;
                        if (带分隔 && !裸名字 && !项.EndsWith("\\", StringComparison.Ordinal)
                            && !Regex.IsMatch(项, @"\.(md|ps1|csproj|slnx|hb|hbp|c|txt|json)$")) continue;
                        string 落点 = Path.Combine(根, 项.TrimEnd('\\', '/').Replace('/', '\\'));
                        if (!File.Exists(落点) && !Directory.Exists(落点)) 违规.Add($"路径 `{项}` 不在");
                    }

                    var 去过重 = 违规.Distinct().ToList();
                    记录(本检查, 去过重.Count == 0, 去过重.Count == 0
                        ? "旗标与仓库内路径都在"
                        : string.Join(" / ", 去过重.Take(4)) + (去过重.Count > 4 ? $" … 共 {去过重.Count} 处" : ""));
                }
            }
            catch (Exception ex) { 记录异常("文档数字 README 钉子", ex); }

            // ---- ④ 流水线这根钉子:SDK 锁与夜间巡检都还在 ----
            // 为什么钉(R5-3):`global.json` 与 `工具\夜间巡检.ps1` 是"除了跑自检的这个人之外"的另两条腿 ——
            // 被顺手删掉、挪走、或者把锁的 SDK 换成别的大版本,谁也不会当场发现。
            // 只查**名字与硬事实在不在**(条数/措辞一概不管):锁的是不是 10.x、脚本还在不在、
            // 它调用的两条现成命令还在不在、历史结果有没有被忽略掉。
            try
            {
                const string 本检查 = "文档数字 global.json 与夜间巡检这根钉子都还在";
                var 违规 = new List<string>();

                // ① 仓库根 `global.json`:认得出 sdk 段,而且锁的是 10.x(语言面与各端 TFM 都在这条线上)
                string 全局路径 = 根 == null ? "" : Path.Combine(根, "global.json");
                if (根 == null || !File.Exists(全局路径)) 违规.Add("global.json 不在");
                else
                {
                    string 文 = File.ReadAllText(全局路径);
                    foreach (string 键 in new[] { "\"sdk\"", "\"version\"", "\"rollForward\"", "\"allowPrerelease\"" })
                        if (!文.Contains(键, StringComparison.Ordinal)) 违规.Add($"global.json 里没有 {键}");
                    var 版本 = Regex.Match(文, @"""version""\s*:\s*""([^""]+)""");
                    if (!版本.Success) 违规.Add("global.json 里认不出锁的版本");
                    else if (!版本.Groups[1].Value.StartsWith("10.", StringComparison.Ordinal))
                        违规.Add($"global.json 锁的是 `{版本.Groups[1].Value}`(这条线都是 net10.0)");
                }

                // ② 夜间巡检脚本,以及它调用的那两条现成命令
                //    2026-10-15(第439批):`工具\收口全套.ps1` 也进这张单 —— 它现在是收口的入口
                //    (生成物 + 命名 + 两条判据 + 真验一条命令),文件没了就该红,别等哪一天发现"文档指的入口没了"。
                foreach (string 相对 in new[] { @"工具\夜间巡检.ps1", @"工具\五端构建.ps1", @"工具\四组合冒烟.ps1", @"工具\收口全套.ps1" })
                    if (根 == null || !File.Exists(Path.Combine(根, 相对))) 违规.Add($"`{相对}` 不在");

                // ③ 历史结果不许进版本库(照 `工具\临时\` 同一条口径)
                string 忽略路径 = 根 == null ? "" : Path.Combine(根, ".gitignore");
                if (根 == null || !File.Exists(忽略路径)) 违规.Add(".gitignore 不在");
                else if (!File.ReadAllText(忽略路径).Contains("工具/巡检/", StringComparison.Ordinal))
                    违规.Add("`.gitignore` 里没有 `工具/巡检/`(巡检结果会进版本库)");

                var 去过重 = 违规.Distinct().ToList();
                记录(本检查, 去过重.Count == 0, 去过重.Count == 0
                    ? "global.json 锁 10.x;夜间巡检 / 五端构建 / 四组合冒烟 / 收口全套 都在;结果已忽略"
                    : string.Join(" / ", 去过重.Take(4)) + (去过重.Count > 4 ? $" … 共 {去过重.Count} 处" : ""));

                // ④ H107(2026-10-15 第449批):**"判据那一趟把解释器核并行度收到 1 路"写成机检**。
                //    为什么值得钉:那个结论(1 路连跑 8 遍 77 个工程 0 个不一致;4 路时那条断言反复假红)
                //    是拿一上午量出来的,要是只写在注释里,下一班把三份脚本里的那一行删掉 / 改回 4,
                //    谁也不会发现 —— 假红就又回来了。三份"判据跑法"的脚本各要有一行
                //    `$env:HB_解释器核并行 = '1'`(口径与代价写在 `工具\四组合冒烟.ps1` 那段注释里)。
                var 没设 = new List<string>();
                foreach (string 相对 in new[] { @"工具\四组合冒烟.ps1", @"工具\夜间巡检.ps1", @"工具\跨平台真验.ps1" })
                {
                    string 路 = 根 == null ? "" : Path.Combine(根, 相对);
                    if (根 == null || !File.Exists(路)) { 没设.Add($"`{相对}` 不在"); continue; }
                    string 文 = File.ReadAllText(路);
                    if (!文.Contains("HB_解释器核并行", StringComparison.Ordinal))
                        没设.Add($"`{相对}` 没把并行度收到 1 路");
                }
                记录("H107 判据跑法:三份判据脚本都把解释器核并行度收到 1 路(1 路实测量过 8 遍 0 个不一致)",
                    没设.Count == 0,
                    没设.Count == 0
                        ? "四组合冒烟 / 夜间巡检 / 跨平台真验 三处都设了 `HB_解释器核并行=1`" +
                          "(手工跑想快就自己设回 4;缺省本来就是 4)"
                        : string.Join(" / ", 没设.Take(4)));

                // ⑤ 同批:`--冻结秒` 要**连 `当前毫秒()` 一起冻** —— 手跑对拍那个坑的机检。
                //    坑的现场:同一份程序跑两遍,池区差十几个字节(那是 `文件.临时文件(…)` 的名字,
                //    里面掺了 `当前毫秒()`),两腿各跑一次更不一样 ⇒ 看着像"内存差一个字"的缺陷。
                //    自检那几组早就把毫秒冻住了(`冻结毫秒` + C 侧 `--hb-now-ms`),缺的只是命令行这一手。
                //    ⚠ H113 那条同样的钉子**不在这儿** —— 它挂在 `C后端跨平台` 那一组的**纯源码那半**
                //    (见 `自检\综合自检C.C后端跨平台.cs` 的「一·五」)。为什么不挂在这儿:挂在这儿就成了一条
                //    **看环境决定在不在**的断言(没 Linux 运行器那一趟它不登记)⇒ 断言清单会随环境变,
                //    而清单是进 git 的基线,「每夜巡检开了 Linux 档」那一趟会当场红。
                string? 命令行文 = 根 == null ? null : Path.Combine(根, "编译器CLI", "Program.cs");
                if (命令行文 == null || !File.Exists(命令行文)) 没设.Add(@"`编译器CLI\Program.cs` 不在");
                else
                {
                    string 文 = File.ReadAllText(命令行文);
                    bool 冻毫秒 = 文.Contains("宿主能力C.取当前毫秒 = () => 冻结毫秒(秒)", StringComparison.Ordinal)
                        && 文.Contains("--hb-now-ms", StringComparison.Ordinal);
                    记录("H78 手跑对拍可复现:`--冻结秒` 连 `当前毫秒()` 一起冻(两条腿都认 `--hb-now-ms`)",
                        冻毫秒,
                        冻毫秒
                            ? "虚拟机侧换 `宿主能力C.取当前毫秒`,原生侧命令行补 `--hb-now-ms`(同一个 `秒 × 1000`)"
                            : "`--冻结秒` 少冻了 `当前毫秒()` ⇒ 手跑对拍不可复现(临时文件名那类会逐跑不同)");
                }
            }
            catch (Exception ex) { 记录异常("文档数字 流水线钉子", ex); }

            // ---- ⑤ 依赖这根钉子:AvalonEdit 走仓库内本地包,根目录不再躺散装 dll(H21) ----
            // 为什么钉:根目录那份 `ICSharpCode.AvalonEdit.dll` **不是官方发布包**,是我们自己打过补丁再编的
            // 6.3.2(第55批:`TextView.DefaultTextHeight` —— 行距照旧生效,插入符与选择框按文字本身高度画);
            // nuget.org 上只有官方 `AvalonEdit` 6.3.1.120,**没有这处补丁** ⇒ 顺手换成官方包、或者改回
            // `HintPath` 硬引用、或者删掉本地包源,谁也不会在当场发现。这里只查**硬事实**(名字与在不在,措辞不管)。
            try
            {
                const string 本检查 = "文档数字 AvalonEdit 走仓库内本地包(根目录不再有散装 dll)";
                var 违规 = new List<string>();
                string 工程路径 = 根 == null ? "" : Path.Combine(根, "hehshihbeen-compiler.csproj");
                if (根 == null || !File.Exists(工程路径)) 违规.Add("找不到 hehshihbeen-compiler.csproj");
                else
                {
                    string 文 = File.ReadAllText(工程路径);
                    string 版本 = "";
                    var 引用 = Regex.Match(文, @"<PackageReference\s+Include=""HB\.AvalonEdit""\s+Version=""([^""]+)""");
                    if (!引用.Success) 违规.Add("csproj 里没有 `PackageReference Include=\"HB.AvalonEdit\"`");
                    else 版本 = 引用.Groups[1].Value;
                    if (文.Contains("<HintPath>", StringComparison.Ordinal)) 违规.Add("csproj 里又有 `<HintPath>`(散装 dll 那条硬引用回来了)");
                    if (文.Contains("ICSharpCode.AvalonEdit.dll", StringComparison.Ordinal)) 违规.Add("csproj 里还点着 `ICSharpCode.AvalonEdit.dll`");

                    // 散装 dll 不许躺回仓库根(它住进本地包里了)
                    if (File.Exists(Path.Combine(根, "ICSharpCode.AvalonEdit.dll"))) 违规.Add("仓库根又有散装 `ICSharpCode.AvalonEdit.dll` 了");

                    // 本地源、包本体,以及包里那一个程序集
                    string 配置路径 = Path.Combine(根, "nuget.config");
                    if (!File.Exists(配置路径)) 违规.Add("找不到 nuget.config(本地包源没了)");
                    else if (!File.ReadAllText(配置路径).Contains("本地包", StringComparison.Ordinal))
                        违规.Add("`nuget.config` 里没有本地包源");

                    if (版本.Length > 0)
                    {
                        string 包路径 = Path.Combine(根, "本地包", $"HB.AvalonEdit.{版本}.nupkg");
                        if (!File.Exists(包路径)) 违规.Add($"`本地包\\HB.AvalonEdit.{版本}.nupkg` 不在");
                        else
                        {
                            try
                            {
                                using var 包 = System.IO.Compression.ZipFile.OpenRead(包路径);
                                if (包.GetEntry("lib/net10.0-windows7.0/ICSharpCode.AvalonEdit.dll") == null)
                                    违规.Add("包里没有 `lib/net10.0-windows7.0/ICSharpCode.AvalonEdit.dll`");
                            }
                            catch (Exception 包异常) { 违规.Add($"包读不开:{包异常.GetType().Name}"); }
                        }
                    }
                }

                var 去过重 = 违规.Distinct().ToList();
                记录(本检查, 去过重.Count == 0, 去过重.Count == 0
                    ? "走本地包 HB.AvalonEdit;根目录无散装 dll;包里有程序集"
                    : string.Join(" / ", 去过重.Take(4)) + (去过重.Count > 4 ? $" … 共 {去过重.Count} 处" : ""));
            }
            catch (Exception ex) { 记录异常("文档数字 本地包钉子", ex); }

            // ---- ⑥ T23(2026-09-27 评测整改第 4 阶段):用户文档不许出现「绕法告示」 ----
            // 为什么钉:把"编译器有这个毛病、你先这么绕"写进用户面 = 把问题正常化,而且**后来者会照抄**
            // (T5 那一次,标准库十个关系比较就是这么抄进去的)。判据是"关键词 + 指路白名单":
            // 同一行同时点到 `未做任务清单` 的算"限制已登记",放行;其余命中一律红灯。
            // 扫的是**用户面正文的源头** —— `关键字与方法清单.md` 与 `引擎\帮助文本C.cs`
            // (站点 HTML 由它现场生成 ⇒ 扫源头就够;HTML 那份的新鲜度另有断言盯着)。
            try
            {
                const string 本检查 = "文档数字 用户文档不许出现「绕法告示」(T23:关键词 + 指路白名单)";
                string[] 绕法词 = ["编译器 bug", "编译器的 bug", "已知问题", "先落一个", "绕开这个"];
                var 违规 = new List<string>();
                foreach (string 相对 in new[] { "关键字与方法清单.md", Path.Combine("引擎", "帮助文本C.cs") })
                {
                    string 路径 = 根 == null ? "" : Path.Combine(根, 相对);
                    if (根 == null || !File.Exists(路径)) { 违规.Add($"{相对}: 找不到"); continue; }
                    string[] 行表 = File.ReadAllText(路径).Replace("\r\n", "\n").Split('\n');
                    for (int i = 0; i < 行表.Length; i++)
                    {
                        if (行表[i].Contains("未做任务清单", StringComparison.Ordinal)) continue;   // 白名单:限制已登记
                        foreach (string 词 in 绕法词)
                            if (行表[i].Contains(词, StringComparison.Ordinal)) 违规.Add($"{相对}:{i + 1} `{词}`");
                    }
                }
                记录(本检查, 违规.Count == 0, 违规.Count == 0
                    ? "两份用户面正文里绕法措辞 0 处(口径与白名单见 `接手说明.md` 硬规矩 18)"
                    : string.Join(" / ", 违规.Take(4)) + (违规.Count > 4 ? $" … 共 {违规.Count} 处" : ""));
            }
            catch (Exception ex) { 记录异常("文档数字 用户文档绕法告示", ex); }

            // ---- ⑦ T24(2026-09-27 评测整改第 4 阶段):关键文档的过期口径一处不回来 ----
            // 为什么钉:T24 逐条核过的那批过期 / 自相矛盾,最省事的复发方式就是"过一阵又抄回去"——
            // `发布检查单.md` 那句"五端 0 错误"(现在是六端,判据只读退出码)、`接手说明.md` 手抄的耗时数
            // 与历史占位 `XXXX`、`README.md` 手抄的"两三分钟"。做法照 R4-6 那一课:**能机检的钉住,
            // 不能的删掉只许指路**;而"最后复核日期"超 30 天**只写进详情、不当判据**(T19 那一课:
            // 时间 / 环境决定的红会天天报假红 —— 人核这件事本来也不该拦闸门)。
            try
            {
                const string 本检查 = "文档数字 关键文档的过期口径一处不回来(T24:帮助核对表 / 发布检查单 / 接手说明 / README)";
                var 违规 = new List<string>();
                string 复核说明 = "";

                // ① `发布检查单.md`:端数口径 + "最后复核日期"这一行必须在(人核这件事得有个看得见的戳)
                string 检查单路径 = 根 == null ? "" : Path.Combine(根, "发布检查单.md");
                if (根 == null || !File.Exists(检查单路径)) 违规.Add("发布检查单.md: 找不到");
                else
                {
                    string 文 = File.ReadAllText(检查单路径);
                    if (文.Contains("五端 0 错误", StringComparison.Ordinal)) 违规.Add("发布检查单.md: 那句旧口径回来了");
                    var 日期 = Regex.Match(文, @"最后复核日期\*\*[:：]\s*(\d{4}-\d{2}-\d{2})");
                    if (!日期.Success) 违规.Add("发布检查单.md: 没有 `最后复核日期:YYYY-MM-DD` 那一行");
                    else if (DateTime.TryParse(日期.Groups[1].Value, out var 复核日))
                    {
                        int 距今天 = (DateTime.Today - 复核日.Date).Days;
                        复核说明 = $";最后复核 {日期.Groups[1].Value}(距今 {距今天} 天"
                            + (距今天 > 30 ? ",该人核一遍了" : "") + ")";
                    }
                }

                // ② `接手说明.md`:整段删掉 / 改掉的旧口径不许以任何形态回来
                string 接手路径 = 根 == null ? "" : Path.Combine(根, "接手说明.md");
                if (根 == null || !File.Exists(接手路径)) 违规.Add("接手说明.md: 找不到");
                else
                {
                    string 文 = File.ReadAllText(接手路径);
                    foreach (string 词 in new[] { "XXXX", "只剩批 15", "2.6 分钟" })
                        if (文.Contains(词, StringComparison.Ordinal)) 违规.Add($"接手说明.md:`{词}`");
                }

                // ③ `README.md`:那扇门上手抄的自检耗时(与 `接手说明.md` 是同一件事,一处改了另一处容易漏)
                string 读我路径 = 根 == null ? "" : Path.Combine(根, "README.md");
                if (根 == null || !File.Exists(读我路径)) 违规.Add("README.md: 找不到");
                else if (File.ReadAllText(读我路径).Contains("两三分钟", StringComparison.Ordinal))
                    违规.Add("README.md: 手抄的耗时数回来了");

                var 去过重 = 违规.Distinct().ToList();
                记录(本检查, 去过重.Count == 0, 去过重.Count == 0
                    ? "过期口径 0 处" + 复核说明
                    : string.Join(" / ", 去过重.Take(4)) + (去过重.Count > 4 ? $" … 共 {去过重.Count} 处" : ""));
            }
            catch (Exception ex) { 记录异常("文档数字 关键文档过期口径", ex); }

            // ---- ⑧ T25(2026-09-27 评测整改第 4 阶段):`接手说明.md` 的体积口径 ----
            // 为什么钉:新会话接手的第一份文档,体积**直接等于每一轮的 token 成本**(硬规矩 13);T25 把
            // §5 那 2830 行逐批叙事整段删了(历史在 `任务清单.md` 与 git 里,一份没少),这条钉子挡住它长回去。
            // 判据不盯"整篇必须小于某个精确值"(那会随正当新增而假红),盯的是**结构**:
            // ① §5 里不许再出现逐批叙事的开头(`> **上一批` / `再上一批` / `上上批`);
            // ② §5 这一段给一个宽松上限;③ 整篇给一个宽松上限(现状约 3.3 万字符,上限留约 3 倍余量)。
            try
            {
                const string 本检查 = "文档数字 接手说明.md §5 不搬逐批正文(T25 体积口径)";
                var 违规 = new List<string>();
                int 整篇长 = 0, 五长 = 0;
                string 路径 = 根 == null ? "" : Path.Combine(根, "接手说明.md");
                if (根 == null || !File.Exists(路径)) 违规.Add("接手说明.md: 找不到");
                else
                {
                    string 文 = File.ReadAllText(路径);
                    整篇长 = 文.Length;
                    int a = 文.IndexOf("## 5、下一步", StringComparison.Ordinal);
                    int b = a < 0 ? -1 : 文.IndexOf("## 6、", a + 1, StringComparison.Ordinal);
                    if (a < 0 || b < 0) 违规.Add("认不出 §5 那一段(标题改了?那要同步这条断言)");
                    else
                    {
                        string 五 = 文.Substring(a, b - a);
                        五长 = 五.Length;
                        foreach (string 词 in new[] { "> **上一批", "> **再上一批", "> **上上批" })
                            if (五.Contains(词, StringComparison.Ordinal)) 违规.Add($"§5 里又出现 `{词}`");
                        if (五长 > 8000) 违规.Add($"§5 {五长} 字符(上限 8000)");
                    }
                    if (整篇长 > 120000) 违规.Add($"整篇 {整篇长} 字符(上限 120000)");
                }
                记录(本检查, 违规.Count == 0, 违规.Count == 0
                    ? $"§5 {五长} 字符 / 整篇 {整篇长} 字符(都在这条口径内)"
                    : string.Join(" / ", 违规.Take(4)));
            }
            catch (Exception ex) { 记录异常("文档数字 接手说明体积", ex); }
        }
        // ================= C5 代码排版 / 自动缩进 / 代码片段(第122批) =================

        /// <summary> 把空白摆出来看(细节串用;空格 → ·,制表符 → →,换行 → ⏎) </summary>
        private static string 看白(string 文本) =>
            (文本 ?? "").Replace("\t", "→").Replace(" ", "·").Replace("\r", "␍").Replace("\n", "⏎");

        private static void 代码排版自检()
        {
            try
            {
                // ---------- ① 按块深度重排(嵌套 / `} 否则 {` / 空行 / 收尾括号) ----------
                // 用户 2026-09-21 起:块括号一律另起一行 —— 这一段顺便把"拆行 + 重排"一起钉住
                string 乱 = "如果 (外条件 > 0) {\n测试输出(1);\n  如果 (内条件 > 0) {\n输出行(\"里\");\n   }\n} 否则 {\n输出行(\"外\");\n}\n";
                var 排 = 代码排版C.排版(乱);
                const string 期望 =
                    "如果 (外条件 > 0)\n{\n    测试输出(1);\n    如果 (内条件 > 0)\n    {\n        输出行(\"里\");\n    }\n}\n否则\n{\n    输出行(\"外\");\n}\n";
                记录("排版 按块深度重排缩进 + 块括号另起一行(嵌套 + `} 否则 {` 拆成三行、一起退档)",
                    string.Equals(排.文本, 期望, StringComparison.Ordinal), 看白(排.文本));
                var 再排 = 代码排版C.排版(排.文本);
                记录("排版 幂等:排好的再排一遍一行都不改",
                    再排.改了几行 == 0 && string.Equals(再排.文本, 排.文本, StringComparison.Ordinal), $"第二次 0 行");

                // ---------- ①b 拆块括号:一行块也拆;方括号初值 `= […]` 与字符串/注释里的 `{}` 一个都不动 ----------
                记录("排版 拆块括号:`结构 点 {` 与一行块 `{ … }` 都拆开,拆完的缩进正好对称",
                    string.Equals(代码排版C.排版("结构 点 {\n    整数 x;\n}\n").文本,
                        "结构 点\n{\n    整数 x;\n}\n", StringComparison.Ordinal)
                    && string.Equals(代码排版C.排版("如果 (真) { 测试输出(1); }\n").文本,
                        "如果 (真)\n{\n    测试输出(1);\n}\n", StringComparison.Ordinal),
                    $"结构『{看白(代码排版C.排版("结构 点 {\n    整数 x;\n}\n").文本)}』 " +
                    $"一行块『{看白(代码排版C.排版("如果 (真) { 测试输出(1); }\n").文本)}』");
                记录("排版 拆块括号不误伤方括号初值与字符串/注释里的花括号(只认块括号)",
                    string.Equals(代码排版C.排版("整数 数据[3] = [1, 2, 3];\n").文本, "整数 数据[3] = [1, 2, 3];\n", StringComparison.Ordinal)
                    && string.Equals(代码排版C.排版("字符串 说 = \"} {\";\n").文本, "字符串 说 = \"} {\";\n", StringComparison.Ordinal)
                    && string.Equals(代码排版C.排版("// 注释里的 { 与 } 原样\n").文本, "// 注释里的 { 与 } 原样\n", StringComparison.Ordinal),
                    $"初值『{看白(代码排版C.排版("整数 数据[3] = [1, 2, 3];\n").文本)}』 " +
                    $"字符串『{看白(代码排版C.排版("字符串 说 = \"} {\";\n").文本)}』");
                记录("排版 拆块括号在 CRLF 文本上也认(拆点是插 `\\n`,换行风格照旧)",
                    代码排版C.排版("如果 (真) {\r\n测试输出(1);\r\n}\r\n").文本
                        .StartsWith("如果 (真)\r\n{\r\n", StringComparison.Ordinal),
                    看白(代码排版C.排版("如果 (真) {\r\n测试输出(1);\r\n}\r\n").文本));

                // ---------- ② 注释:顶格分节线不动;缩进过的跟着层级;多行注释里面整行不动 ----------
                string 注 = "如果 (条件) {\n// ---- 分节 ----\n      // 里面的说明\n测试输出(1);\n}\n/* 块注释\n    里面这行   原样  \n   */\n";
                var 注排 = 代码排版C.排版(注);
                string 注期望 = "如果 (条件)\n{\n// ---- 分节 ----\n    // 里面的说明\n    测试输出(1);\n}\n/* 块注释\n    里面这行   原样  \n   */\n";
                记录("排版 顶格整行注释当分节线不动;缩进过的注释跟着层级;多行注释里面一个字不动",
                    string.Equals(注排.文本, 注期望, StringComparison.Ordinal), 看白(注排.文本));

                // ---------- ③ 字符串与行尾:字符串里的花括号不算结构;注释里的行尾空格不动 ----------
                string 串 = "字符串 说 = \"} 假的花括号 {\";\n整数 数 = 1;   // 尾注释   \n测试输出(数);   \n";
                var 串排 = 代码排版C.排版(串);
                记录("排版 字符串里的花括号不算结构(后面几行深度仍为 0)",
                    string.Equals(串排.文本, "字符串 说 = \"} 假的花括号 {\";\n整数 数 = 1;   // 尾注释   \n测试输出(数);\n", StringComparison.Ordinal),
                    看白(串排.文本));
                记录("排版 行尾空格:代码行去掉(尾注释那行连注释里的空格一起留着)",
                    串排.文本.Contains("// 尾注释   \n", StringComparison.Ordinal)
                    && 串排.文本.Contains("测试输出(数);\n", StringComparison.Ordinal), 看白(串排.文本));

                // ---------- ④ 续行:上一行以 = / 逗号收尾,这一行再缩一档 ----------
                string 续 = "整数 数 =\n1 + 2;\n测试输出(\n数);\n";
                记录("排版 续行再缩一档(`=` 与逗号收尾的多行语句)",
                    string.Equals(代码排版C.排版(续).文本, "整数 数 =\n    1 + 2;\n测试输出(\n    数);\n", StringComparison.Ordinal),
                    看白(代码排版C.排版(续).文本));

                // ---------- ⑤ 汇编标签体:标签下一档,下一个标签回原档;空行断开之后不替作者拿主意 ----------
                string 标 = "起:\n加载立即数 R0, 1\n返回\n末:\n存字 R0, [0x1000]\n";
                记录("排版 汇编标签体下一档、下一个标签回到不缩进",
                    string.Equals(代码排版C.排版(标).文本, "起:\n    加载立即数 R0, 1\n    返回\n末:\n    存字 R0, [0x1000]\n", StringComparison.Ordinal),
                    看白(代码排版C.排版(标).文本));
                string 标2 = "起:\n    加载立即数 R0, 1\n\n// ---- 另起一节 ----\n加载立即数 R0, 0x1000;\n末:\n    返回\n";
                记录("排版 标签体被空行断开后的行原样不动(示例里两种写法都有,不替作者拿主意)",
                    string.Equals(代码排版C.排版(标2).文本, 标2, StringComparison.Ordinal), 看白(代码排版C.排版(标2).文本));

                // ---------- ⑥ 设置:制表符 / 换行风格 / BOM ----------
                记录("排版 用制表符缩进(一档一个 \\t)",
                    代码排版C.排版(乱, new 排版设置C { 用制表符 = true }).文本.Contains("\n\t测试输出(1);\n", StringComparison.Ordinal),
                    看白(代码排版C.排版(乱, new 排版设置C { 用制表符 = true }).文本));
                var 宽二 = 代码排版C.排版(乱, new 排版设置C { 缩进宽度 = 2 });
                记录("排版 缩进宽度可调(2 空格一档)",
                    宽二.文本.Contains("\n  测试输出(1);\n", StringComparison.Ordinal), 看白(宽二.文本));
                string crlf = "如果 (真) {\r\n测试输出(1);\r\n}\r\n";
                string crlf后 = 代码排版C.排版(crlf).文本;
                记录("排版 换行风格保持(CRLF 进就 CRLF 出,不把整个文件的行尾换掉)",
                    crlf后.Contains("\r\n", StringComparison.Ordinal) && !crlf后.Replace("\r\n", "").Contains('\n'),
                    看白(crlf后));
                记录("排版 开头的 BOM 不被顶走(它不属于第一行的缩进)",
                    代码排版C.排版("\uFEFF如果 (真) {\n测试输出(1);\n}").文本.StartsWith("\uFEFF如果", StringComparison.Ordinal), "BOM 还在开头");

                // ---------- ⑦ 关键验收:只动空白,编译出来的机器码逐字节一致 ----------
                const string 乱程序 = "// 注释\n整数 数 = 1;\n方法 加一(整数 x) 返回 整数 {\n返回 x + 1;\n}\n如果 (数 > 0) {\n测试输出(加一(数));\n}\n停止\n";
                var 原机 = 编译(乱程序).机器码;
                var 排好程序 = 代码排版C.排版(乱程序);
                var 排后机 = 编译(排好程序.文本).机器码;
                记录("排版 不改语义:排版前后编译出来的机器码逐字节一致",
                    排好程序.改了几行 > 0 && 原机.SequenceEqual(排后机), $"{原机.Length} 字节 / 改了 {排好程序.改了几行} 行");

                // ---------- ⑧ 自动缩进(编辑器回车用) ----------
                记录("自动缩进 块里回车 → 下一档;`}` 行回车 → 回到块外",
                    代码排版C.回车后的缩进("如果 (条件 > 0) {\n测试输出(1);\n", 2) == "    "
                    && 代码排版C.回车后的缩进("如果 (条件 > 0) {\n    测试输出(1);\n}\n", 3) == "",
                    $"块内[{看白(代码排版C.回车后的缩进("如果 (条件 > 0) {\n测试输出(1);\n", 2))}] 收尾括号后[{看白(代码排版C.回车后的缩进("如果 (条件 > 0) {\n    测试输出(1);\n}\n", 3))}]");
                记录("自动缩进 空行回车不缩(连按回车不会越缩越深);续行回车再进一档",
                    代码排版C.回车后的缩进("如果 (条件) {\n\n", 2) == ""
                    && 代码排版C.回车后的缩进("整数 数 =\n", 1) == "    ",
                    $"空行[{看白(代码排版C.回车后的缩进("如果 (条件) {\n\n", 2))}] 续行[{看白(代码排版C.回车后的缩进("整数 数 =\n", 1))}]");
                记录("自动缩进 标签体里回车 → 标签下一档",
                    代码排版C.回车后的缩进("起:\n    加载立即数 R0, 1\n", 2) == "    ", "标签体一档");

                // ---------- ⑧b C16-4(用户 2026-09-19 实测报的):回车把 `}` 拆到新行,新行要与它的 `{` 同列 ----------
                // 用户那段:`{/*这点按回车后*/}` 那一行里光标停在结尾 `}` 之前按回车 ⇒ 新行是 `}`;
                // 老代码拿"空行"那套算前导,而且 `设前导` 见"行首不是空白"就 return ⇒ `}` 停在 0 列。
                string 拆括号 = "方法 取数()\n{\n    如果 (真 )\n    {/*这点按回车后*/\n}\n";
                记录("自动缩进 回车拆出来的 `}` 与它的 `{` 同列(C16-4:新行有内容就按这一行自己的写法算)",
                    代码排版C.回车后前导(拆括号, 5) == "    "
                    && string.Equals(代码排版C.回车后前导(拆括号, 5), 代码排版C.行目标缩进(拆括号, 5), StringComparison.Ordinal),
                    $"拆出来的 `}}` 前导[{看白(代码排版C.回车后前导(拆括号, 5) ?? "null")}] —— 配对的 `{{` 在第 4 行的第 5 列");
                记录("自动缩进 空行新行照旧走老规矩(C16-4 只动`新行有内容`那一半)",
                    代码排版C.回车后前导("如果 (条件) {\n    测试输出(1);\n\n", 3) == "    "
                    && 代码排版C.回车后前导("如果 (条件) {\n\n", 3) == ""
                    && 代码排版C.回车后前导("整数 数 =\n\n", 2) == "    "
                    && 代码排版C.回车后前导("方法 取数()\n{\n    停\n止;\n}\n", 4) == "    ",
                    $"块里空行[{看白(代码排版C.回车后前导("如果 (条件) {\n    测试输出(1);\n\n", 3) ?? "null")}] " +
                    $"空行回车[{看白(代码排版C.回车后前导("如果 (条件) {\n\n", 3) ?? "null")}] " +
                    $"续行[{看白(代码排版C.回车后前导("整数 数 =\n\n", 2) ?? "null")}] " +
                    $"语句尾巴[{看白(代码排版C.回车后前导("方法 取数()\n{\n    停\n止;\n}\n", 4) ?? "null")}]");
                记录("自动缩进 说不清的写法一律给 null(原样不动),绝不硬猜一个前导",
                    代码排版C.回车后前导("如果 (条件) {\n/* 块注释\n   里面这行\n*/\n", 3) == null
                    && 代码排版C.回车后前导("如果 (条件) {\n// 分节线\n", 2) == null,
                    "整行在块注释里 / 顶格整行注释(分节线)都给 null");

                // ---------- ⑨ 代码片段:表(触发唯一 / 配平 / 带光标记号) ----------
                var 片段 = 片段表C.全部;
                记录($"片段 共 {片段.Count} 条:触发词唯一、都带光标记号、花括号配平",
                    片段.Count >= 8
                    && 片段.Select(x => x.触发).Distinct().Count() == 片段.Count
                    && 片段.All(x => x.触发.Length > 0 && x.说明.Length > 0
                        && x.正文.Contains(片段项C.光标记号)
                        && x.正文.Count(c => c == '{') == x.正文.Count(c => c == '}')),
                    片段表C.清单().Replace("\n", " / "));
                记录("片段 按触发词找得到(找不到给 null,不当场炸)",
                    片段表C.按触发("方法") != null && 片段表C.按触发("没有这个片段") == null, "方法 ✓ / 没这个片段 ✗");

                // ---------- ⑩ 代码片段:展开(缩进 / 光标记号 / 幂等) ----------
                string 函 = 片段表C.展开(片段表C.按触发("方法")!, "    ", out int 光);
                记录("片段 展开按缩进起头、光标记号去掉且光标偏移指在正确位置",
                    !函.Contains(片段项C.光标记号)
                    && 函.StartsWith("    方法", StringComparison.Ordinal)
                    && 光 >= 0 && 光 <= 函.Length && 函[光..].StartsWith("返回 0;", StringComparison.Ordinal),
                    $"光标停在第 {光} 个字符:{看白(函[光..])}");
                记录("片段 展开出来的骨架再排版一行都不用改(骨架本身是排好的)",
                    片段.All(x => 代码排版C.排版(片段表C.展开(x, "")).改了几行 == 0), $"{片段.Count} 条都排好了");

                // ---------- ⑪ 代码片段:骨架真能编过(拿编译器钉住,不靠眼看) ----------
                var 编得过的 = new (string 触发, string 前缀, string 换条件, string 换标记)[]
                {
                    ("方法", "", "", ""), ("过程", "", "", ""), ("如果", "", "真", ""), ("如果否则", "", "真", ""),
                    ("当", "", "假", ""), ("循环", "", "", ""), ("选择", "var 值 = 1;\n", "", ""),
                    ("遍历", "var 当前 = 0;\nvar 游标 = 0x2000;\nvar 剩余 = 0;\n", "", ""),
                    ("结构", "", "", ""), ("测试", "", "", "真"), ("循环列表", "短整数 列表[];\n", "", ""),
                };
                var 编不过 = new List<string>();
                foreach (var (触发, 前缀, 条件, 标记) in 编得过的)
                {
                    var 项 = 片段表C.按触发(触发);
                    if (项 == null) { 编不过.Add($"{触发}:没有这条片段"); continue; }
                    string 骨架 = 片段表C.展开(项, "", out int 骨架光标);
                    if (标记.Length > 0) 骨架 = 骨架.Insert(骨架光标, 标记);   // `断言 ◆;` 这种:标记在语句中间,去掉了要补回来
                    if (条件.Length > 0) 骨架 = 骨架.Replace("条件", 条件, StringComparison.Ordinal);
                    骨架 = 前缀 + 骨架 + "\n停止\n";
                    try { 编译(骨架); }
                    catch (Exception ex) { 编不过.Add($"{触发}: {ex.Message.Split('\n')[0]}"); }
                }
                记录($"片段 {编得过的.Length} 条骨架都能真编过(◆ 换成空/条件换成真·假,按示例的写法)",
                    编不过.Count == 0, 编不过.Count == 0 ? $"{编得过的.Length} 条全过" : string.Join(" / ", 编不过));

                // ---------- ⑫ 标准示例:排版只动空白,每行内容逐字未变 ----------
                string? 根 = 找示例目录();
                if (根 == null)
                {
                    跳过("排版 标准示例:排版只动空白(每行内容逐字未变)", "找不到示例目录");
                }
                else
                {
                    // 第434批:`列源码` 剔掉 HB 机器码产物(IDE「只编译」落下的 `<工程名>.hb`)——
                    // 拿二进制当源码排版,判据与计数都会被它搅浑。
                    var 示例文件 = 源码文件C.列源码(根);
                    var 违例 = new List<string>();
                    var 要改的 = new List<string>();
                    int 改的行 = 0;
                    foreach (string 路径 in 示例文件)
                    {
                        string 原文 = File.ReadAllText(路径);
                        var 一个 = 代码排版C.排版(原文);
                        if (一个.改了几行 > 0)
                        {
                            改的行 += 一个.改了几行;
                            要改的.Add($"{Path.GetFileName(Path.GetDirectoryName(路径))}/{Path.GetFileName(路径)}×{一个.改了几行}");
                        }
                        // 逐行比"去掉前后空白之后的内容":排版**只许**动空白
                        var 原行 = 代码排版C.归一换行(原文).Split('\n');
                        var 新行 = 代码排版C.归一换行(一个.文本).Split('\n');
                        if (原行.Length != 新行.Length) { 违例.Add($"{Path.GetFileName(路径)}:行数变了"); continue; }
                        for (int i = 0; i < 原行.Length; i++)
                        {
                            if (原行[i].Trim() != 新行[i].Trim())
                            {
                                违例.Add($"{Path.GetFileName(路径)} 第 {i + 1} 行:{看白(原行[i])} → {看白(新行[i])}");
                                break;
                            }
                        }
                    }
                    // 阈值用**实数**(R4-2):扫到的 .hb 数不该少于标准工程数,也不该是 0
                    int 工程个数 = Directory.GetFiles(根, "*" + 工程文件C.扩展名, SearchOption.AllDirectories).Length;
                    记录($"排版 {示例文件.Length} 个标准示例:排版只动空白(每行去掉前后空白后逐字未变)",
                        违例.Count == 0 && 示例文件.Length > 0 && 示例文件.Length >= 工程个数,
                        违例.Count == 0
                            ? $"{示例文件.Length} 个文件全过;其中 {要改的.Count} 个文件本来就歪、共 {改的行} 行需要修"
                                + (要改的.Count > 0 ? "(" + string.Join(" / ", 要改的) + ")" : "")
                            : string.Join(" / ", 违例.Take(3)));
                }
            }
            catch (Exception ex) { 记录异常("代码排版自检", ex); }
        }

        // ================= C6 文件改名:工程文件条目与 包含 的连带改动(第123批) =================
        private static void 文件改名自检()
        {
            string 根 = Path.Combine(临时区C.基目录(), "hb_改名自检");
            try
            {
                // ---------- ① 内存里的"一个小工程"(不碰磁盘):算计划 ----------
                string 主 = Path.Combine(根, "主程序.hb");
                string 旧 = Path.Combine(根, "工具.hb");
                string 新 = Path.Combine(根, "助手.hb");
                string 库旧 = Path.Combine(根, "库", "数学.hb");
                string 库新 = Path.Combine(根, "库", "算术.hb");
                string 工程 = Path.Combine(根, "工程.hbp");
                string 注释文件 = Path.Combine(根, "注释里.hb");

                var 源码表 = new List<(string 文件, string 内容)>
                {
                    (主, "// 说明:工具.hb 是重要文件\n包含 \"库/数学.hb\"\n包含 \"工具.hb\"\n测试输出(加一(40));\n停止\n"),
                    (旧, "方法 加一(整数 n) 返回 整数 {\n    返回 n + 1;\n}\n"),
                    (库旧, "方法 减一(整数 n) 返回 整数 {\n    返回 n - 1;\n}\n"),
                    (注释文件, "// 包含 \"工具.hb\" 这句在注释里\n停止\n"),
                };
                string 工程文本 = "{\n  // 我自己的备注\n  \"名称\": \"试\",\n  \"启动文件\": \"主程序.hb\",\n  \"文件\": [\n    \"主程序.hb\",\n    \"工具.hb\"\n  ]\n}\n";
                var 工程表 = new List<(string 文件, string 内容)> { (工程, 工程文本) };

                var 计划 = 工程维护C.计划(旧, 新, 源码表, 工程表);
                记录("改名 算得出计划:工程文件 1 处 + 包含 1 处(只改一处,别处不动)",
                    计划.可改 && 计划.工程处数 == 1 && 计划.源码处数 == 1, 计划.摘要());
                记录("改名 别的文件里的 包含 \"工具.hb\" 跟着改;注释里那句一个字不动",
                    计划.编辑.Any(x => x.文件 == 主 && x.原词 == "工具.hb" && x.新词 == "助手.hb")
                    && !计划.编辑.Any(x => string.Equals(x.文件, 注释文件, StringComparison.OrdinalIgnoreCase))
                    && !计划.编辑.Any(x => x.原词.Contains("这句在注释里")),
                    计划.预览(10).Replace("\n", " / "));
                记录("改名 工程文件里的条目按『相对 .hbp 的路径』改对",
                    计划.编辑.Any(x => string.Equals(x.文件, 工程, StringComparison.OrdinalIgnoreCase)
                        && x.原词 == "\"工具.hb\"" && x.新词 == "\"助手.hb\""),
                    计划.预览(10).Replace("\n", " / "));

                // ---------- ② 套用:文本真改对,注释与别处一字不动 ----------
                var 全部表 = new List<(string 名称, string 内容)>(源码表);
                全部表.Add((工程, 工程文本));
                var 改后 = 计划.套用(全部表);
                string 改后主 = 改后.First(x => x.名称 == 主).内容;
                记录("改名 套用后:包含 换成新名,别的内容(含注释里那句)一字未变",
                    改后主 == "// 说明:工具.hb 是重要文件\n包含 \"库/数学.hb\"\n包含 \"助手.hb\"\n测试输出(加一(40));\n停止\n",
                    改后主.Replace("\n", "⏎"));
                string 改后工程 = 改后.First(x => x.名称 == 工程).内容;
                记录("改名 套用后 .hbp 条目改了、用户写的注释与排版都留着",
                    改后工程.Contains("\"助手.hb\"") && !改后工程.Contains("\"工具.hb\"")
                    && 改后工程.Contains("// 我自己的备注"), 改后工程.Replace("\n", "⏎"));
                记录("改名 幂等:同一份计划套两遍 = 套一遍",
                    string.Equals(计划.套用(改后).First(x => x.名称 == 主).内容, 改后主, StringComparison.Ordinal),
                    "套两遍不多改一处");

                // ---------- ③ 子目录里的文件:相对路径按**引用方**重算,不是换名字 ----------
                var 计划2 = 工程维护C.计划(库旧, 库新, 源码表, 工程表);
                记录("改名 子目录里的文件:按引用方目录重算相对路径(库/数学.hb → 库/算术.hb)",
                    计划2.编辑.Any(x => x.文件 == 主 && x.原词 == "库/数学.hb" && x.新词 == "库/算术.hb"),
                    计划2.预览(10).Replace("\n", " / "));

                // 被改名那个文件自己 包含 别人、又换了目录 → 它自己的包含也要重算
                string 旧路径 = Path.Combine(根, "子", "a.hb");
                string 新路径 = Path.Combine(根, "深", "更", "a.hb");
                var 源码表3 = new List<(string 文件, string 内容)> { (旧路径, "包含 \"../库/数学.hb\"\n停止\n") };
                var 计划3 = 工程维护C.计划(旧路径, 新路径, 源码表3, []);
                记录("改名 被改名文件自己换了目录:它自己的 包含 按新目录重算(../库/数学.hb → ../../库/数学.hb)",
                    计划3.编辑.Any(x => x.文件 == 旧路径 && x.原词 == "../库/数学.hb" && x.新词 == "../../库/数学.hb"),
                    // 同目录改名时它自己的包含不动
                    计划3.编辑.Count == 1
                        ? $"1 处:{计划3.编辑[0].原词} → {计划3.编辑[0].新词}"
                        : string.Join(" / ", 计划3.编辑));

                // ---------- ④ 该拦的拦下来 ----------
                记录("改名 新旧是同一个文件 → 报问题、不可改",
                    !工程维护C.计划(旧, 旧, 源码表, 工程表).可改
                    && 工程维护C.计划(旧, 旧, 源码表, 工程表).问题.Count == 1, "不可改");
                记录("改名 新名不是 .hb → 报问题(免得把源码改成别的扩展名)",
                    !工程维护C.计划(旧, Path.Combine(根, "工具.txt"), 源码表, 工程表).可改, "不可改");
                记录("改名 文件不在工程里也没人包含 → 给一句提醒(不挡路)",
                    工程维护C.计划(Path.Combine(根, "没人用.hb"), Path.Combine(根, "更没人用.hb"), 源码表, 工程表).提示.Count == 1,
                    string.Join(" / ", 工程维护C.计划(Path.Combine(根, "没人用.hb"), Path.Combine(根, "更没人用.hb"), 源码表, 工程表).提示));

                // ---------- ⑤ 工程文件加条目(新建文件走它:只动那一处,注释留着) ----------
                string 加1 = 工程维护C.工程文本加文件(工程文本, "新文件.hb", out string 说明1) ?? "";
                记录("工程文件 加文件:加在 文件 表末尾,注释与排版都留着",
                    加1.Length > 0 && 加1.Contains("\"新文件.hb\"") && 加1.Contains("// 我自己的备注")
                    && 加1.Contains("\"工具.hb\",\n    \"新文件.hb\""), 说明1 + " → " + 加1.Replace("\n", "⏎"));
                记录("工程文件 加文件:已经在表里就不再加(文本原样返回)",
                    工程维护C.工程文本加文件(工程文本, "工具.hb", out string 说明2) == 工程文本
                    && 说明2.Contains("已经"), 说明2);
                记录("工程文件 加文件:空数组也认",
                    工程维护C.工程文本加文件("{\n  \"文件\": [],\n  \"说明\": \"x\"\n}\n", "a.hb", out _) is { } 空加
                    && 空加.Contains("\"a.hb\""), "空数组");
                记录("工程文件 加文件:找不到 文件 数组就返回 null(调用方退回『读成对象再保存』)",
                    工程维护C.工程文本加文件("{ \"名称\": \"x\" }", "a.hb", out _) == null, "null");
                记录("工程文件 加文件:`.hbp` 里带 BOM / CRLF 也不慌(换行跟着原文)",
                    工程维护C.工程文本加文件("{\r\n  \"文件\": [\r\n    \"a.hb\"\r\n  ]\r\n}\r\n", "b.hb", out _) is { } crlf
                    && crlf.Contains("\"a.hb\",\r\n    \"b.hb\""), "CRLF");
                记录("工程文件 反转义/转义 往返一致(路径里的反斜杠与引号)",
                    工程维护C.反转义(工程维护C.转义("库\\左\"b.hb")) == "库\\左\"b.hb", "往返");

                // ---------- ⑥ 端到端(真磁盘):改名 → 立刻能编、能跑出对的结果 ----------
                // ⑥-A:子目录里的库文件改名,靠的是**别的文件里的 包含**改对(工程文件里本来就不列它)
                string 盘 = Path.Combine(根, "真");
                if (Directory.Exists(盘)) Directory.Delete(盘, true);
                Directory.CreateDirectory(Path.Combine(盘, "库"));
                string 盘主 = Path.Combine(盘, "主程序.hb");
                string 盘旧 = Path.Combine(盘, "库", "数学.hb");
                string 盘新 = Path.Combine(盘, "库", "算术.hb");
                string 盘工程 = Path.Combine(盘, "工程.hbp");
                File.WriteAllText(盘主, "包含 \"库/数学.hb\"\n测试输出(减一(43));\n停止\n", new UTF8Encoding(false));
                File.WriteAllText(盘旧, "方法 减一(整数 n) 返回 整数 {\n    返回 n - 1;\n}\n", new UTF8Encoding(false));
                File.WriteAllText(盘工程, "{\n  // 手工注释要留着\n  \"名称\": \"试改名\",\n  \"启动文件\": \"主程序.hb\",\n  \"文件\": [\n    \"主程序.hb\"\n  ]\n}\n", new UTF8Encoding(false));

                var 盘源码 = new List<(string 文件, string 内容)>
                {
                    (盘主, File.ReadAllText(盘主)),
                    (盘旧, File.ReadAllText(盘旧)),
                };
                var 盘工程表 = new List<(string 文件, string 内容)> { (盘工程, File.ReadAllText(盘工程)) };
                var 盘计划 = 工程维护C.计划(盘旧, 盘新, 盘源码, 盘工程表);
                File.Move(盘旧, 盘新);
                var 盘全部 = new List<(string 名称, string 内容)>(盘源码);
                盘全部.Add((盘工程, 盘工程表[0].内容));
                int 写了 = 0;
                foreach (var (名称, 内容) in 盘计划.套用(盘全部))
                {
                    if (string.Equals(名称, 盘旧, StringComparison.OrdinalIgnoreCase)) continue;    // 它已经改了名,内容没变
                    string 原 = 盘全部.First(x => string.Equals(x.名称, 名称, StringComparison.OrdinalIgnoreCase)).内容;
                    if (string.Equals(原, 内容, StringComparison.Ordinal)) continue;
                    工程维护C.写回(名称, 内容);
                    写了++;
                }
                记录("改名 端到端A:库文件改名 → 主程序里的 包含 跟着改对(磁盘上真改)",
                    写了 == 1 && !File.Exists(盘旧) && File.Exists(盘新)
                    && File.ReadAllText(盘主).Contains("包含 \"库/算术.hb\"")
                    && File.ReadAllText(盘工程).Contains("// 手工注释要留着"),
                    $"写了 {写了} 个文件");
                跑输出断言带目录("改名 端到端A:改完名**立刻能编能跑**(包含 路径对上了)",
                    File.ReadAllText(盘主), "42", 盘);

                // ⑥-B:工程文件里列着的根文件改名 —— 靠的是 **.hbp 条目**改对(不更新的话下一次编译就找不到文件)
                string 盘2 = Path.Combine(根, "真2");
                Directory.CreateDirectory(盘2);
                string 盘2主 = Path.Combine(盘2, "主程序.hb");
                string 盘2旧 = Path.Combine(盘2, "工具.hb");
                string 盘2新 = Path.Combine(盘2, "助手.hb");
                string 盘2工程 = Path.Combine(盘2, "工程.hbp");
                File.WriteAllText(盘2主, "测试输出(加一(40));\n停止\n", new UTF8Encoding(false));
                File.WriteAllText(盘2旧, "方法 加一(整数 n) 返回 整数 {\n    返回 n + 1;\n}\n", new UTF8Encoding(false));
                File.WriteAllText(盘2工程, "{\n  \"名称\": \"试改名2\",\n  \"启动文件\": \"主程序.hb\",\n  \"文件\": [\n    \"主程序.hb\",\n    \"工具.hb\"\n  ]\n}\n", new UTF8Encoding(false));

                var 盘2源码 = new List<(string 文件, string 内容)>
                {
                    (盘2主, File.ReadAllText(盘2主)),
                    (盘2旧, File.ReadAllText(盘2旧)),
                };
                var 盘2工程表 = new List<(string 文件, string 内容)> { (盘2工程, File.ReadAllText(盘2工程)) };
                var 盘2计划 = 工程维护C.计划(盘2旧, 盘2新, 盘2源码, 盘2工程表);
                File.Move(盘2旧, 盘2新);
                var 盘2全部 = new List<(string 名称, string 内容)>(盘2源码);
                盘2全部.Add((盘2工程, 盘2工程表[0].内容));
                int 写了2 = 0;
                foreach (var (名称, 内容) in 盘2计划.套用(盘2全部))
                {
                    if (string.Equals(名称, 盘2旧, StringComparison.OrdinalIgnoreCase)) continue;
                    string 原 = 盘2全部.First(x => string.Equals(x.名称, 名称, StringComparison.OrdinalIgnoreCase)).内容;
                    if (string.Equals(原, 内容, StringComparison.Ordinal)) continue;
                    工程维护C.写回(名称, 内容);
                    写了2++;
                }
                var 盘2重读 = 工程文件C.加载(盘2工程);
                记录("改名 端到端B:工程文件里列着的文件改名 → .hbp 条目跟着改对(否则下一次编译就找不到文件)",
                    写了2 == 1 && 盘2计划.工程处数 == 1 && 盘2重读.文件.Contains("助手.hb") && !盘2重读.文件.Contains("工具.hb"),
                    $".hbp 条目现在:{string.Join(", ", 盘2重读.文件)}");
                // 拿**工程文件**去编译:条目对不对,这里一试就知道
                try
                {
                    var 盘2缓冲 = new StringBuilder();
                    var 盘2解码 = new 文字输出C(文本 => 盘2缓冲.Append(文本));
                    var 盘2机 = new 虚拟机C { 输入源 = () => null, 输出目标 = 盘2解码.写, 宿主调用 = 宿主能力C.处理 };
                    var 盘2结果 = new 汇编器C().汇编多文件带调试(盘2重读.读全部源文件(), true, 盘2重读.堆字节数);
                    盘2机.运行(盘2结果);
                    盘2解码.收尾();
                    记录("改名 端到端B:改完名按工程文件编译运行,输出对(41)",
                        盘2缓冲.ToString().Trim() == "41", 盘2缓冲.ToString().Trim());
                }
                catch (Exception ex) { 记录异常("改名 端到端B 编译运行", ex); }
                var 重读 = 工程文件C.加载(盘工程);
                记录("改名 端到端:工程文件仍然读得动(注释没把 JSON 弄坏)",
                    重读.文件.Count == 1 && 重读.启动文件 == "主程序.hb", 重读.摘要());
            }
            catch (Exception ex) { 记录异常("文件改名自检", ex); }
            finally
            {
                try { if (Directory.Exists(根)) Directory.Delete(根, true); } catch { }
            }
        }

        // ================= C7 大文件流畅度(可断言的指标)+ 快捷键可配(第124批) =================
        private static void 大文件与快捷键自检()
        {
            try
            {
                // ---------- ① 逐行高亮缓存:命中就不重扫(这是"不是感觉快了"的那个数) ----------
                var 缓存 = new 增量高亮C();
                const string 行 = "整数 初值 = 1;   // 说明";
                var 直扫 = 高亮扫描C.扫一行(行, null, null);
                var 第一次 = 缓存.取行片段(行, null, null, 名字版本: "v1");
                缓存.取行片段(行, null, null, 名字版本: "v1");          // 第二次:应该全命中
                记录("高亮缓存 同一行第一次扫、第二次命中(扫描行数不涨)",
                    缓存.扫描行数 == 1 && 缓存.命中行数 == 1 && 第一次.Count == 直扫.Count
                    && 第一次.Select(x => (x.起始, x.长度, x.词类)).SequenceEqual(直扫.Select(x => (x.起始, x.长度, x.词类))),
                    $"扫描 {缓存.扫描行数} / 命中 {缓存.命中行数} / 片段 {第一次.Count}");

                缓存.取行片段("整数 初值 = 2;", null, null, 名字版本: "v1");
                记录("高亮缓存 换了一行只有那一行重扫(别的行照样命中)",
                    缓存.扫描行数 == 2 && 缓存.命中行数 == 1, $"扫描 {缓存.扫描行数} / 命中 {缓存.命中行数}");

                缓存.取行片段(行, null, null, 名字版本: "v2");
                记录("高亮缓存 名字集换了版本(声明过的名字变了)→ 重新扫,不吃旧结果",
                    缓存.扫描行数 == 3 && 缓存.命中行数 == 1, $"扫描 {缓存.扫描行数} / 命中 {缓存.命中行数}");

                var 缓存2 = new 增量高亮C();
                缓存2.取行片段("整数 初值 = 1;", null, null, 名字版本: "v");
                缓存2.取行片段("整数 初值 = 1;", null, [(12, 16)], 名字版本: "v");       // 同一行文本,但注释区间变了
                记录("高亮缓存 同一行文本、注释区间变了 → 不算命中(注释是最高档色,不能拿旧结果)",
                    缓存2.扫描行数 == 2, $"扫描 {缓存2.扫描行数}");

                var 小缓存 = new 增量高亮C(上限: 16);
                for (int i = 0; i < 40; i++) 小缓存.取行片段($"第 {i} 行;", null, null, 名字版本: "v");
                记录("高亮缓存 有条数上限(满了按『最早进来的先走』腾位置,不整表清空)",
                    小缓存.缓存条数 <= 16, $"缓存条数 {小缓存.缓存条数}");

                // ---------- ② 大文件:整篇扫一遍 vs 再扫一遍(0 次扫描) ----------
                var 大字 = new StringBuilder();
                for (int i = 0; i < 20000; i++)
                    大字.Append(i % 7 == 0 ? $"// 第 {i} 行注释\n" : $"整数 变量{i} = {i};   // 说明 {i}\n");
                string 大文本 = 大字.ToString();
                var 大缓存 = new 增量高亮C();
                var (冷行数, 冷毫秒) = 大缓存.冷扫全篇(大文本);
                var (再扫, 再命中, 再毫秒) = 大缓存.再扫全篇(大文本);
                记录("大文件 2 万行:整篇扫一遍要真扫(行数对得上)",
                    冷行数 == 20001 && 大缓存.缓存条数 > 0, $"{冷行数} 行 / {冷毫秒:0.0} ms");
                记录("大文件 2 万行:**同一份文本再扫一遍 = 0 行扫描**(全命中)",
                    再扫 == 0 && 再命中 == 20001, $"再扫扫描 {再扫} 行 / 命中 {再命中} 行 / {再毫秒:0.0} ms(冷扫 {冷毫秒:0.0} ms)");

                // ---------- ③ 结构护栏:编辑器里"整篇扫描"那条老路确实没了 ----------
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                string 界面目录 = 根 == null ? "" : Path.Combine(根, "界面控件");
                if (根 == null || !Directory.Exists(界面目录))
                {
                    跳过接线("大文件 编辑器不再整篇扫描上色(工作副本之外跑自检时跳过)", "找不到 界面控件 目录");
                }
                else
                {
                    string 补全与外观 = File.ReadAllText(Path.Combine(界面目录, "编辑器.补全与外观.cs"));
                    string 编辑器Xaml = File.ReadAllText(Path.Combine(界面目录, "编辑器.xaml"));
                    string 语法高亮 = File.ReadAllText(Path.Combine(界面目录, "语法高亮C.cs"));
                    记接线("大文件 编辑器不再整篇扫描上色(源码里没有 overlay 那条老路)",
                        !补全与外观.Contains("高亮文本(", StringComparison.Ordinal)
                        && !编辑器Xaml.Contains("高亮框", StringComparison.Ordinal)
                        && !语法高亮.Contains("public void 高亮文本", StringComparison.Ordinal),
                        "刷新高亮 只重画;逐行着色走 AvalonInlineHighlighter + 增量高亮C");
                    // C16-1:Tab / 回车 / 空格三条键分开,插入文本一律过 `补全词表C.确认文本`
                    // (空格在预览层吃掉就不会再走一遍字符输入 —— 这条只能真敲一次才知道,自检钉源码)
                    string 初始化源 = File.ReadAllText(Path.Combine(界面目录, "编辑器.初始化与交互.cs"));
                    记接线("补全 C16-1:Tab/回车只补名字、空格才补一个空格(三条键分开 + 走 确认文本)",
                        补全与外观.Contains("case System.Windows.Input.Key.Space:", StringComparison.Ordinal)
                        && 补全与外观.Contains("尝试确认候选(补空格: false)", StringComparison.Ordinal)
                        && 补全与外观.Contains("尝试确认候选(补空格: true)", StringComparison.Ordinal)
                        && 补全与外观.Contains("补全词表C.确认文本(项, 补空格)", StringComparison.Ordinal)
                        && !补全与外观.Contains("名 + \" \"", StringComparison.Ordinal)
                        && 初始化源.Contains("替换当前词(sel, 补空格: true)", StringComparison.Ordinal),
                        "预览层 switch:Tab/回车→假、空格→真;候选插入文本里没有 `+ \" \"`");
                    // 第159批:「逐步」合并到 F10 之后用户实测"按 F10 没反应" ——
                    // 根因不是单步本身,是 **F10 在 Windows 上是系统键**:WPF 把它报成 `Key.System`,
                    // 真按键在 `e.SystemKey`;只认 `e.Key` 就永远对不上表里的 F10,最后被系统拿去"激活菜单栏"。
                    // 这条按源码钉住(纯界面细节,引擎自检够不着):谁把"取系统键"那一句删了,谁就红。
                    string 主窗源 = File.ReadAllText(Path.Combine(根, "MainWindow.xaml.cs"));
                    记接线("快捷键 F10 是系统键:先取 SystemKey 再查表(不然被系统当成『激活菜单栏』)",
                        主窗源.Contains("e.Key == Key.System ? e.SystemKey : e.Key", StringComparison.Ordinal)
                        && 主窗源.Contains("if (执行快捷键(动作)) e.Handled = true;", StringComparison.Ordinal),
                        "快捷键_预览 里取系统键 + 查到动作就拦下");
                    // C16-4:界面回车那条路走 `回车后前导`,而且"行首不是空白"的行也要设前导
                    string 缩进源 = File.ReadAllText(Path.Combine(界面目录, "编辑器.缩进与片段.cs"));
                    记接线("自动缩进 C16-4:IndentLine 走 `回车后前导` + 行首不是空白的行也设前导",
                        缩进源.Contains("代码排版C.回车后前导(document.Text, line.LineNumber", StringComparison.Ordinal)
                        && !缩进源.Contains("行首不是空白:别动", StringComparison.Ordinal),
                        "新行有内容(拆出来的 `}` / 语句尾巴)也按这一行自己的写法缩;原样不动由 null 保证");
                }

                // ---------- ④ 快捷键表 ----------
                var 表 = 快捷键C.全部;
                记录($"快捷键 表里 {表.Count} 条:动作名唯一、默认键都能解析、格式往返一致",
                    表.Count >= 8 && 表.Select(x => x.动作).Distinct().Count() == 表.Count
                    && 表.All(x => 快捷键C.解析(x.默认键, out var 值) && 快捷键C.格式化(值) == x.默认键),
                    string.Join(" / ", 表.Select(x => $"{x.动作}={x.默认键}")));
                // 第159批:F9 原来是「逐语句」的,那一档合并进「逐步」下线之后让给「切换断点」
                // (VS 的习惯也是 F9 = 断点)。默认表里**不许有两个动作抢同一个键** ——
                // 撞了就是"按下去只会触发先出现的那个",这条当场红。
                记录("快捷键 默认表没有两个动作抢同一个键(逐步 F10 / 切换断点 F9 / 热重载 F6)",
                    快捷键C.冲突().Count == 0
                    && 快捷键C.默认键("逐步") == "F10" && 快捷键C.默认键("切换断点") == "F9"
                    && 快捷键C.默认键("热重载") == "F6",
                    $"逐步 = {快捷键C.默认键("逐步")} / 切换断点 = {快捷键C.默认键("切换断点")} / 热重载 = {快捷键C.默认键("热重载")} / 冲突 {快捷键C.冲突().Count} 条");
                记录("快捷键 写法容错:大小写/顺序/空格都不计较;写错了给空串(不静默乱来)",
                    快捷键C.规范("ctrl+shift+f") == "Ctrl+Shift+F"
                    && 快捷键C.规范(" Shift + F12 ") == "Shift+F12"
                    && 快捷键C.规范("f5") == "F5"
                    && 快捷键C.规范("Ctrl++") == "" && 快捷键C.规范("没有这个键") == ""
                    && 快捷键C.规范("Ctrl") == "",
                    $"ctrl+shift+f → {快捷键C.规范("ctrl+shift+f")};没有这个键 → `{快捷键C.规范("没有这个键")}`");
                记录("快捷键 解析出键与修饰键(界面拿它跟 Key/Modifiers 对)",
                    快捷键C.解析("Ctrl+Shift+F", out var 左键) && 左键.键 == "F" && 左键.控制 && 左键.换档 && !左键.替换
                    && 快捷键C.解析("F5", out var 右键) && 右键.键 == "F5" && !右键.控制 && !右键.换档,
                    "Ctrl+Shift+F → F + Ctrl + Shift");

                // ---------- ⑤ 分发:默认表 → 动作;覆盖表 → 新键位生效、旧键位让位 ----------
                记录("快捷键 默认表分发:按 F5 得到『执行』、Ctrl+Shift+F 得到『格式化当前文件』、没绑的键得到 null",
                    快捷键C.动作Of("F5", false, false, false) == "执行"
                    && 快捷键C.动作Of("F", true, true, false) == "格式化当前文件"
                    && 快捷键C.动作Of("F12", false, true, false) == "查找引用"
                    && 快捷键C.动作Of("Q", true, false, false) == null,
                    "F5→执行 / Ctrl+Shift+F→格式化 / Shift+F12→查找引用 / Ctrl+Q→没绑");
                var 覆盖 = new Dictionary<string, string>(StringComparer.Ordinal) { ["执行"] = "Ctrl+E" };
                记录("快捷键 改了键位之后:新键位能触发,旧键位让出来(不再是那个动作)",
                    快捷键C.动作Of("E", true, false, false, 覆盖) == "执行"
                    && 快捷键C.动作Of("F5", false, false, false, 覆盖) == null
                    && 快捷键C.生效键("执行", 覆盖) == "Ctrl+E",
                    $"执行 现在 = {快捷键C.生效键("执行", 覆盖)}");
                var 取消 = new Dictionary<string, string>(StringComparer.Ordinal) { ["继续"] = "" };
                记录("快捷键 留空 = 取消这个快捷键(不再分发)",
                    快捷键C.生效键("继续", 取消) == "" && 快捷键C.动作Of("F7", false, false, false, 取消) == null,
                    "继续 已取消");

                // ---------- ⑥ 冲突 / 坏配置要说出来,不能静默 ----------
                var 撞车 = new Dictionary<string, string>(StringComparer.Ordinal) { ["继续"] = "F5" };
                记录("快捷键 两个动作撞同一个键 → 报出来(不静默失效)",
                    快捷键C.冲突(撞车).Count == 1 && 快捷键C.冲突(覆盖).Count == 0,
                    快捷键C.冲突(撞车).FirstOrDefault() ?? "没冲突");
                var 坏 = new Dictionary<string, string>(StringComparer.Ordinal) { ["没有这个动作"] = "F1" };
                记录("快捷键 配置里有不认识的动作名 → 报出来并忽略",
                    快捷键C.未知动作(坏).Count == 1 && 快捷键C.未知动作(覆盖).Count == 0,
                    快捷键C.未知动作(坏).FirstOrDefault() ?? "都认识");
                记录("快捷键 清单能生成(帮助文本/选项页/命令行共用一份)",
                    快捷键C.清单().Contains("F5") && 快捷键C.清单().Contains("Ctrl+Shift+F")
                    && 快捷键C.清单(覆盖).Contains("Ctrl+E"),
                    快捷键C.清单(覆盖).Replace("\n", " / "));
            }
            catch (Exception ex) { 记录异常("大文件与快捷键自检", ex); }
        }
        // ================= 执行行(调试黄条)滚动判定(用户 2026-09-19 实测;第138批) =================

        /// <summary>
        /// 用户实测:"单步黄条始终保持在编辑器中央 → 改成离底边还有一两行时才挪到中央(不然观感太跳)"。
        /// 判定收在引擎侧 `引擎\执行行滚动C.cs`(纯逻辑),这里逐条钉住三种情形与边界;
        /// 界面那边只是照着 `滚动方式C` 决定"滚不滚、滚到中央还是上三分之一"(见 `编辑器.滚到这一行`)。
        /// </summary>
        private static void 执行行滚动自检()
        {
            try
            {
                // 视口 = 第 10~30 行
                const int 首 = 10, 末 = 30;
                记录("执行行滚动 在视口里、离底边还有 3 行以上 → 一动不动(屏幕别跟着挪)",
                    执行行滚动C.定(20, 首, 末) == 滚动方式C.不动
                    && 执行行滚动C.定(27, 首, 末) == 滚动方式C.不动,
                    $"第 20 行:{执行行滚动C.说明(执行行滚动C.定(20, 首, 末))};第 27 行:{执行行滚动C.说明(执行行滚动C.定(27, 首, 末))}");

                记录("执行行滚动 离底边只剩一两行(28/29)或更靠下(30) → 居中",
                    执行行滚动C.定(28, 首, 末) == 滚动方式C.居中
                    && 执行行滚动C.定(29, 首, 末) == 滚动方式C.居中
                    && 执行行滚动C.定(30, 首, 末) == 滚动方式C.居中
                    && 执行行滚动C.定(40, 首, 末) == 滚动方式C.居中,
                    "28→" + 执行行滚动C.说明(执行行滚动C.定(28, 首, 末)));

                记录("执行行滚动 跑到视口上面 → 靠上(黄条别看不见)",
                    执行行滚动C.定(9, 首, 末) == 滚动方式C.靠上
                    && 执行行滚动C.定(1, 首, 末) == 滚动方式C.靠上,
                    "第 9 行:" + 执行行滚动C.说明(执行行滚动C.定(9, 首, 末)));

                记录("执行行滚动 留边行数可配(0 = 到底行才滚;5 = 提前五行就滚)",
                    执行行滚动C.定(29, 首, 末, 0) == 滚动方式C.不动
                    && 执行行滚动C.定(30, 首, 末, 0) == 滚动方式C.居中
                    && 执行行滚动C.定(25, 首, 末, 5) == 滚动方式C.居中
                    && 执行行滚动C.定(24, 首, 末, 5) == 滚动方式C.不动,
                    "默认留边 " + 执行行滚动C.默认留边行数);

                记录("执行行滚动 参数不对一律不动(行号 0 / 可视范围反了)—— 宁可不滚",
                    执行行滚动C.定(0, 首, 末) == 滚动方式C.不动
                    && 执行行滚动C.定(5, 0, 0) == 滚动方式C.不动
                    && 执行行滚动C.定(5, 末, 首) == 滚动方式C.不动,
                    "三组坏参数都给了『不动』");
            }
            catch (Exception ex) { 记录异常("执行行滚动自检", ex); }
        }
        // ================= C10 撤销的边界(实测 + 写进帮助;第126批) =================
        private static void 撤销边界自检()
        {
            try
            {
                // ① 帮助里必须**明说**:撤销是每个文件自己的、跨文件没有"一次撤销整批"
                //    ⚠ 第432批(H106):这一段以前还钉着一句**维护者路径**(`工具\临时\c10\探针`)——
                //    那是给改代码的人看的,不该跑到用户面的帮助正文里。改成钉**对用户有意义的那半句**:
                //    用户真正要知道的是"哪些操作算一步撤销"(退得回去),而不是当年在哪台机器上量的。
                string 上手 = 帮助文本C.快速上手();
                记录("撤销边界 帮助里写明:撤销栈是每个文件自己的;跨文件没有『一次撤销整批』",
                    上手.Contains("撤销的边界", StringComparison.Ordinal)
                    && 上手.Contains("每个文件(每个标签页)自己的", StringComparison.Ordinal)
                    && 上手.Contains("没有\"一次撤销整批\"", StringComparison.Ordinal)
                    && 上手.Contains("逐个文件 Ctrl+Z", StringComparison.Ordinal)
                    && !上手.Contains("工具\\临时", StringComparison.Ordinal),
                    "快速上手 里那段『撤销的边界』;并且正文里不再出现维护者路径");

                // ② 结构护栏:整篇推文本必须走"对同一个文档做一次替换"
                //    (实测:设 `TextEditor.Text` 会换掉整个文档,撤销栈一起没了 —— 界面却写着 Ctrl+Z 能撤)
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                string 路径 = 根 == null ? "" : Path.Combine(根, "界面控件", "编辑器.xaml.cs");
                if (根 == null || !File.Exists(路径))
                {
                    跳过("撤销边界 整篇推文本走的是 Document.Replace(工作副本之外跑自检时跳过)", "找不到 编辑器.xaml.cs");
                }
                else
                {
                    string 源码 = File.ReadAllText(路径);
                    记录("撤销边界 整篇推文本走的是 Document.Replace(不是设 TextEditor.Text —— 那会把撤销栈换掉)",
                        源码.Contains("文档.Replace(0, 文档.TextLength, 文本)", StringComparison.Ordinal)
                        && 源码.Contains("if (文档 == null)", StringComparison.Ordinal)     // 兜底那支写明条件,不是随手设 Text
                        && 源码.Contains("撤销栈", StringComparison.Ordinal),               // 注释里写了为什么这么改
                        "编辑器.xaml.cs 的 推送绑定内容到编辑器");
                }

                // ===== C29(第171批,用户 2026-09-20 报的):载入完成后才开始算撤销 =====
                // 用户原话:"撤销不能撤得太彻底,最后一个撤销会撤出来一个空白页(应该从代码载入完成后才开始算撤销)"。
                // ① 口径本身是纯函数(界面只负责把两个事实喂进来):四条真值表逐条钉
                记录("撤销边界 C29 口径:换了页 / 页上标着这一份载入 ⇒ 算载入,其余一律算用户编辑",
                    撤销边界C.算载入(false, false) == false
                    && 撤销边界C.算载入(true, false)
                    && 撤销边界C.算载入(false, true)
                    && 撤销边界C.算载入(true, true),
                    "撤销边界C.算载入 四条组合");

                // ② 帮助里必须写明这一条(用户看得见的口径)
                记录("撤销边界 帮助里写明:C29 载入(打开文件 / 新建页 / 装载工程 / 换标签页)不算一步撤销",
                    上手.Contains("载入不算一步撤销", StringComparison.Ordinal)
                    && 上手.Contains("再按一次 `Ctrl+Z` 就撤出一张空白页", StringComparison.Ordinal),
                    "快速上手《撤销的边界》里那一条");

                // ③ 结构护栏(按源码钉):编辑器那条路真的分了"载入 / 用户动作"两条,而且载入那条清了栈
                if (根 == null || !File.Exists(Path.Combine(根, "MainWindow.窗口与文件.cs")))
                {
                    跳过("撤销边界 C29 载入那条路清空撤销栈(工作副本之外跑自检时跳过)", "找不到仓库根");
                }
                else
                {
                    string 编辑器源 = File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.xaml.cs"));
                    记录("撤销边界 编辑器:算载入走 撤销边界C.算载入;载入那一次 UndoStack.ClearAll()",
                        编辑器源.Contains("撤销边界C.算载入(", StringComparison.Ordinal)
                        && 编辑器源.Contains("UndoStack.ClearAll()", StringComparison.Ordinal)
                        && 编辑器源.Contains("if (是载入) 清空撤销栈();", StringComparison.Ordinal)
                        && 编辑器源.Contains("if (代码编辑器.Text == 文本)", StringComparison.Ordinal),
                        "编辑器.xaml.cs 的 推送绑定内容到编辑器 / 取走载入标记 / 清空撤销栈");

                    string 页源 = File.ReadAllText(Path.Combine(根, "选卡控件", "选卡页视图模型.cs"));
                    记录("撤销边界 页模型带着『这一份内容是载入』的旗子(而且旗子上记着当初那一份正文)",
                        页源.Contains("public void 标记载入(string? 载入的正文)", StringComparison.Ordinal)
                        && 页源.Contains("public bool 取走载入标记(string? 要推的文本)", StringComparison.Ordinal)
                        && 页源.Contains("_待载入正文 = null;", StringComparison.Ordinal),
                        "选卡页视图模型.cs 的 标记载入 / 取走载入标记");

                    string 窗口源 = File.ReadAllText(Path.Combine(根, "MainWindow.窗口与文件.cs"));
                    记录("撤销边界 载入路径(打开文件 / 新建页 / 装载工程都走 更新标签页内容)标了载入旗子",
                        窗口源.Contains("页.标记载入(内容);", StringComparison.Ordinal),
                        "MainWindow.窗口与文件.cs 的 更新标签页内容");
                }
            }
            catch (Exception ex) { 记录异常("撤销边界自检", ex); }
        }
        // ================= C11 安卓那一端能编了(环境 + 一条命令;第127批) =================
        private static void 安卓与五端自检()
        {
            try
            {
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null || !File.Exists(Path.Combine(根, "接手说明.md")))
                {
                    跳过("五端 有一条命令能复现『五端 0 错误』(工作副本之外跑自检时跳过)", "找不到 接手说明.md");
                    跳过("五端 安卓那条命令的理由写清楚了(必须给 RID)", "找不到 接手说明.md");
                    跳过("五端构建脚本不靠中文子串判成败(判据只读退出码)", "找不到 接手说明.md");
                    跳过("门禁 解子进程输出按 UTF-8(.NET 重定向写 UTF-8,PS 按代码页解会全乱)", "找不到 接手说明.md");
                    return;
                }
                string 接手 = File.ReadAllText(Path.Combine(根, "接手说明.md"));
                记录("五端 有一条命令能复现『五端 0 错误』(脚本存在且接手说明里指了它)",
                    File.Exists(Path.Combine(根, "工具", "五端构建.ps1"))
                    && 接手.Contains("工具\\五端构建.ps1", StringComparison.Ordinal),
                    "工具\\五端构建.ps1");

                string 脚本 = File.ReadAllText(Path.Combine(根, "工具", "五端构建.ps1"));
                记录("五端 安卓那一段:SDK/JDK 自己找 + **必须给 RuntimeIdentifier**(不给会静默失败)",
                    脚本.Contains("AndroidSdkDirectory", StringComparison.Ordinal)
                    && 脚本.Contains("JavaSdkDirectory", StringComparison.Ordinal)
                    && 脚本.Contains("RuntimeIdentifier=$rid", StringComparison.Ordinal)
                    && 脚本.Contains("android-arm64", StringComparison.Ordinal)
                    && 脚本.Contains("android-x64", StringComparison.Ordinal)
                    && 接手.Contains("RuntimeIdentifier=android-arm64", StringComparison.Ordinal),
                    "五端构建.ps1 = 五端 + 安卓(arm64/x64)");

                string 安卓csproj = File.ReadAllText(Path.Combine(根, "MobileIDE", "MobileIDE.csproj"));
                记录("五端 MobileIDE 工程里写明了安卓怎么编(免得下一个人以为是代码坏了)",
                    安卓csproj.Contains("AndroidSdkDirectory", StringComparison.Ordinal)
                    && 安卓csproj.Contains("RuntimeIdentifier", StringComparison.Ordinal),
                    "MobileIDE.csproj 顶部注释");

                // ---- T1(2026-09-27 评测整改):门禁脚本的判成败只许读**退出码** ----
                // 为什么钉:这三份脚本是"自检之外唯一那道自动门禁",而它曾经拿输出里的**中文子串**当判据
                // (`已成功生成` / `0 个错误`)—— `chcp 936` + `DOTNET_CLI_UI_LANGUAGE=zh-Hans` 下,
                // `dotnet build` 编过了(退出码 0)却被判"失败",而正文里那行中文长得跟结论一样,
                // "结论对不上正文,没人看得出来"(2026-09-26 / 09-27 两份**自动跑出来的**日志就是假红:
                // 6 端全红、退出码 1)。判据一被写回中文子串,同一处假红就再来一次 ⇒ 按源码钉住。
                string 冒烟 = File.ReadAllText(Path.Combine(根, "工具", "四组合冒烟.ps1"));
                string 巡检 = File.ReadAllText(Path.Combine(根, "工具", "夜间巡检.ps1"));
                记录("五端构建脚本不靠中文子串判成败(判据只读退出码)",
                    // ① 五端构建.ps1 的 `编一端`:读退出码,而且不再拿 `已成功生成` 判成败
                    脚本.Contains("$码 = $LASTEXITCODE", StringComparison.Ordinal)
                    && 脚本.Contains("$好 = ($码 -eq 0)", StringComparison.Ordinal)
                    && !脚本.Contains("Select-String -Pattern '已成功生成'", StringComparison.Ordinal)
                    // ② 四组合冒烟.ps1:那条 `0 个错误` 的中文子串判据已经去掉(它上面那行在看退出码)
                    && !冒烟.Contains("-notmatch '0 个错误'", StringComparison.Ordinal)
                    // ③ 夜间巡检.ps1:退出码与判据分别落日志(不再"结论对不上正文")
                    && 巡检.Contains("判据 = 退出码", StringComparison.Ordinal)
                    && 巡检.Contains("退出码 {2},{3}", StringComparison.Ordinal),
                    "五端构建.ps1 编一端 = $LASTEXITCODE -eq 0;四组合冒烟.ps1 里没有 '0 个错误' 这条中文判据;" +
                    "夜间巡检.ps1 的整篇日志与汇总都分别写出退出码与判据");

                // ---- T1 下半段(2026-09-27 评测整改,用户当班拍板并进 T1):解子进程输出一律按 UTF-8 ----
                // 为什么还差这一条:判成败换成退出码只治了"判据";可 `四组合冒烟.ps1` **还要解析子进程的中文输出**
                // (`综合自检:通过` / `全示例双跑一致` / `断言清单:` / `乱源轰炸:` / `崩 0 例`)。而 .NET 的进程
                // (dotnet / hbcc)**只要 stdout 被重定向就一律写 UTF-8**,PS 5.1 却按**控制台代码页**去解
                // (中文机 = 936)⇒ 那些中文一个都匹配不上,当场 throw「自检没有收尾那一行」。
                // 实测(CP936 子进程):`--stats` 输出里 `.Contains('标准工程')` = **False**、`--help` 里 `.Contains('用法')` = False;
                // 把"解"这一侧钉成 UTF-8 之后两个都变 True,而**脚本自己打印的中文不受影响**(实测仍走控制台代码页)。
                // 顺带:`git status` 吐的是 UTF-8 路径字节,以前按 936 解 ⇒ `引擎/` `中间层/` 前缀永远匹配不上,
                // 安卓那一维会静默漏编 —— 这一层护栏把它一起治好。
                // 只钉"该有的两处有、不该有的那一处没有"(夜间巡检抓的是 PS 自己与 schtasks,写的是控制台代码页)。
                const string 护栏 = "[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)";
                记录("门禁 解子进程输出按 UTF-8(.NET 重定向写 UTF-8,PS 按代码页解会全乱)",
                    脚本.Contains(护栏, StringComparison.Ordinal)
                    && 冒烟.Contains(护栏, StringComparison.Ordinal)
                    && !巡检.Contains(护栏, StringComparison.Ordinal),
                    "五端构建.ps1 与 四组合冒烟.ps1 各一处;夜间巡检.ps1 故意没有(它抓的是 PS 自己与 schtasks,写的是控制台代码页)");
            }
            catch (Exception ex) { 记录异常("安卓与五端自检", ex); }
        }
        // ================= D1 运行进程(白名单 + 同步等待 + 超时;第128批) =================
        private static void 进程启动自检()
        {
            string 临时目录 = Path.Combine(临时区C.基目录(), "hb_进程自检");
            try
            {
                string cmd = Path.Combine(Environment.SystemDirectory, "cmd.exe");
                记录("进程启动 测试用的 cmd.exe 在(System32)", File.Exists(cmd), cmd);

                // ---------- ① 工程文件里的 `可执行文件` 表:往返 + 形状校验 ----------
                Directory.CreateDirectory(临时目录);
                string 工程路径 = Path.Combine(临时目录, "工程.hbp");
                File.WriteAllText(Path.Combine(临时目录, "主程序.hb"), "停止\n");
                var 工程 = new 工程文件C
                {
                    名称 = "试进程",
                    启动文件 = "主程序.hb",
                    文件 = ["主程序.hb"],
                };
                工程.可执行文件["cmd"] = cmd;
                工程.保存(工程路径);
                var 重读 = 工程文件C.加载(工程路径);
                记录("进程启动 工程文件的 `可执行文件` 表能存能读(名字 → 路径)",
                    重读.可执行文件.Count == 1
                    && string.Equals(重读.可执行文件["cmd"], cmd, StringComparison.OrdinalIgnoreCase),
                    string.Join(" / ", 重读.可执行文件.Select(x => $"{x.Key}={x.Value}")));

                重读.可执行文件[""] = "x.exe";
                重读.可执行文件["带 空格"] = "y.exe";
                重读.可执行文件["空路径"] = "  ";
                var 形状问题 = 重读.检查();
                记录("进程启动 白名单形状写错会报出来(空名字 / 名字带空格 / 没写路径)",
                    形状问题.Count(x => x.Contains("可执行文件") || x.Contains("名字")) >= 3,
                    string.Join(" | ", 形状问题));

                // ---------- ② 直接问宿主能力层:没挂 / 不在白名单 / 路径不存在 ----------
                var (内存, 参数区, 头址) = 造进程请求("cmd", "/c\necho hi", 3000);
                宿主能力C.清运行痕迹();
                记录("进程启动 没挂白名单(手机端 / 独立 exe)→ 状态『没挂能力』,不是崩溃",
                    宿主能力C.处理(内存, 参数区, 宿主能力C.功能_运行进程) == 宿主能力C.状态_没挂能力,
                    宿主能力C.说明(宿主能力C.状态_没挂能力));

                宿主能力C.设可执行白名单(new Dictionary<string, string> { ["别的"] = cmd });
                记录("进程启动 名字不在白名单里 → 直接拒绝(连试都不试)",
                    宿主能力C.处理(内存, 参数区, 宿主能力C.功能_运行进程) == 宿主能力C.状态_不在白名单,
                    宿主能力C.说明(宿主能力C.状态_不在白名单));

                宿主能力C.设可执行白名单(new Dictionary<string, string> { ["cmd"] = Path.Combine(临时目录, "没有这个.exe") });
                记录("进程启动 白名单里那条路径不存在 → 状态『打不开』",
                    宿主能力C.处理(内存, 参数区, 宿主能力C.功能_运行进程) == 宿主能力C.状态_打不开,
                    "路径存在性留给运行时判(换机器/换安装路径不该让工程打不开)");

                // ---------- ③ 超时:杀掉整个进程树 + 退出码记 0xFFFFFFFF ----------
                宿主能力C.设可执行白名单(new Dictionary<string, string> { ["cmd"] = cmd });
                var (超时内存, 超时区, _) = 造进程请求("cmd", "/c\nfor /l %i in (1,0,2) do @rem", 400);
                int 超时状态 = 宿主能力C.处理(超时内存, 超时区, 宿主能力C.功能_运行进程);
                记录("进程启动 超时 → 状态『超时』且退出码记 0xFFFFFFFF(整个进程树被杀)",
                    超时状态 == 宿主能力C.状态_超时 && 宿主能力C.上次退出码 == 0xFFFFFFFF,
                    $"{宿主能力C.说明(超时状态)} / 退出码 {宿主能力C.上次退出码}");

                // ---------- ④ 端到端:真起子进程,拿输出、拿退出码 ----------
                宿主能力C.设可执行白名单(new Dictionary<string, string> { ["cmd"] = cmd });
                var (跑内存, 跑区, 跑头址) = 造进程请求("cmd", "/c\necho 你好", 5000);
                int 跑状态 = 宿主能力C.处理(跑内存, 跑区, 宿主能力C.功能_运行进程);
                string 跑输出 = 读字符串(跑内存, 跑头址);
                记录("进程启动 真起一个子进程:成功 + 输出写进字符串变量 + 退出码 0",
                    跑状态 == 宿主能力C.状态_成功 && 跑输出.Trim() == "你好" && 宿主能力C.上次退出码 == 0,
                    $"状态={跑状态} 输出=「{跑输出.Trim()}」 退出码={宿主能力C.上次退出码}");

                var (坏内存, 坏区, _) = 造进程请求("cmd", "/c\nexit 7", 5000);
                int 坏状态 = 宿主能力C.处理(坏内存, 坏区, 宿主能力C.功能_运行进程);
                记录("进程启动 退出码非 0 → 返回 假(但 `取退出码()` 给真实值,能跟'起不来'分开)",
                    坏状态 == 宿主能力C.状态_退出码非零 && 宿主能力C.上次退出码 == 7,
                    $"{宿主能力C.说明(坏状态)} / 退出码 {宿主能力C.上次退出码}");

                // ---------- ⑤ 走一整条路子(HB 源码 → 中间层 → 虚拟机 → 宿主能力) ----------
                string 源 = "字符串 输出;\n" +
                    "逻辑 成 = 运行进程(\"cmd\", \"/c\\necho 你好\", 输出, 5000);\n" +
                    "如果 (成) {\n输出行(输出);\n}\n" +
                    "测试输出(取退出码());\n停止\n";
                var (_, 程序输出) = 运行带输出(源);
                记录("进程启动 HB 程序里调用:返回 真 + 输出行拿到子进程的输出 + 取退出码() == 0",
                    程序输出.Replace("\r\n", "\n") == "你好\n\n0\n",
                    程序输出.Replace("\r\n", "\n").Replace("\n", "|") + "(子进程自己那个换行**原样保留**,输出行 又加一个 → 空一行)");

                string 失败源 = "字符串 输出;\n" +
                    "逻辑 成 = 运行进程(\"cmd\", \"/c\\nexit 3\", 输出, 5000);\n" +
                    "如果 (成) {\n输出行(\"成了\");\n} 否则 {\n输出行(\"没成\");\n}\n" +
                    "测试输出(取退出码());\n停止\n";
                var 失败编 = 编译(失败源);
                var 失败缓冲 = new StringBuilder();
                var 失败解码 = new 文字输出C(文本 => 失败缓冲.Append(文本));
                var 失败机 = new 虚拟机C
                {
                    输入源 = () => null,
                    输出目标 = 失败解码.写,
                    宿主调用 = 宿主能力C.处理,
                };
                失败机.运行(失败编);
                失败解码.收尾();
                记录("进程启动 子进程失败也**不写错误槽、不停机**(与其它宿主能力同一套:失败看返回值)",
                    string.IsNullOrEmpty(失败编.查运行期报错(失败机.内存))
                    && 失败缓冲.ToString().Replace("\r\n", "\n") == "没成\n3\n",
                    $"输出={失败缓冲.ToString().Replace("\r\n", "\n").Replace("\n", "|")} 报错={失败编.查运行期报错(失败机.内存)}");

                // ---------- ⑥ 名字/说明都在(高亮 / 补全 / 帮助 / 中英切换自动跟上) ----------
                记录("进程启动 两个名字进了内建函数名表,且有帮助说明",
                    中间层指令C.内建函数名表.Any(x => x.中文 == "运行进程" && x.英文 == "runprocess")
                    && 中间层指令C.内建函数名表.Any(x => x.中文 == "取退出码" && x.英文 == "exitcode")
                    && (中间层指令C.取说明("runprocess") ?? "").Length > 0
                    && (中间层指令C.取说明("exitcode") ?? "").Length > 0);
                期望异常("进程启动 参数个数不对 → 报错(说清四个参数各是什么)",
                    () => 汇编("字符串 输出;\n测试输出(运行进程(\"cmd\", \"/c\", 输出));\n停止"), "四个参数");
                期望异常("进程启动 输出变量写成字面量 → 报错",
                    () => 汇编("测试输出(运行进程(\"cmd\", \"/c\", \"字面量\", 100));\n停止"), "字符串");
            }
            catch (Exception ex) { 记录异常("进程启动自检", ex); }
            finally
            {
                宿主能力C.清运行痕迹();
                try { if (Directory.Exists(临时目录)) Directory.Delete(临时目录, true); } catch { }
            }
        }
        /// <summary> 造一个"运行进程"请求块(直接问宿主能力层用;布局与 `宿主能力C.处理运行进程` 一致) </summary>
        private static (byte[] 内存, uint 参数区, uint 头址) 造进程请求(string 名字, string 参数, uint 超时毫秒)
        {
            var 内存 = new byte[16384];
            uint 名字址 = 0x100, 参址 = 0x300, 头址 = 0x500, 数据址 = 0x600;
            uint 池指针槽 = 0x700, 池末槽 = 0x704, 参数区 = 0x800, 池起 = 0x1000, 池末 = 0x3000;
            var 名字字节 = Encoding.UTF8.GetBytes(名字);
            var 参数字节 = Encoding.UTF8.GetBytes(参数);
            Array.Copy(名字字节, 0, 内存, 名字址, 名字字节.Length);
            Array.Copy(参数字节, 0, 内存, 参址, 参数字节.Length);
            void 写(uint 址, uint 值)
            {
                内存[址] = (byte)(值 & 0xFF);
                内存[址 + 1] = (byte)((值 >> 8) & 0xFF);
                内存[址 + 2] = (byte)((值 >> 16) & 0xFF);
                内存[址 + 3] = (byte)((值 >> 24) & 0xFF);
            }
            写(头址, 数据址);
            写(头址 + 4, 0);
            写(头址 + 8, 64);                 // 初始容量 64:输出更长时会走"从池里换一块"那条路
            写(池指针槽, 池起);
            写(池末槽, 池末);
            写(参数区 + 0, 名字址);
            写(参数区 + 4, (uint)名字字节.Length);
            写(参数区 + 8, 头址);
            写(参数区 + 12, 池指针槽);
            写(参数区 + 16, 池末槽);
            写(参数区 + 20, 参址);
            写(参数区 + 24, (uint)参数字节.Length);
            写(参数区 + 28, 超时毫秒);
            return (内存, 参数区, 头址);
        }

        /// <summary> 从字符串头里读出内容(头:数据地址 / 长度 / 容量) </summary>
        private static string 读字符串(byte[] 内存, uint 头址)
        {
            uint 址 = (uint)(内存[头址] | (内存[头址 + 1] << 8) | (内存[头址 + 2] << 16) | (内存[头址 + 3] << 24));
            uint 长 = (uint)(内存[头址 + 4] | (内存[头址 + 5] << 8) | (内存[头址 + 6] << 16) | (内存[头址 + 7] << 24));
            if (长 == 0) return "";
            return Encoding.UTF8.GetString(内存, (int)址, (int)长);
        }
        // ================= D2 删目录 / 移动到 / 复制到(第129批) =================
        private static void 目录与文件操作自检()
        {
            string 根 = Path.Combine(临时区C.基目录(), "hb_目录自检");
            try
            {
                if (Directory.Exists(根)) Directory.Delete(根, true);
                Directory.CreateDirectory(根);
                string 工作 = Path.Combine(根, "工作");
                Directory.CreateDirectory(工作);
                string 斜(string 路径) => 路径.Replace('\\', '/');          // HB 字符串里 `\` 是转义,写路径一律用 `/`

                // ---------- ① 直接问宿主能力层:三个新状态码 ----------
                string 有东西的目录 = Path.Combine(工作, "有东西");
                Directory.CreateDirectory(有东西的目录);
                File.WriteAllText(Path.Combine(有东西的目录, "里面.txt"), "x");
                var (删内存, 删区) = 造路径请求(有东西的目录);
                记录("目录操作 删目录只删空目录:里面还有东西 → 状态『目录不空』(不递归删)",
                    宿主能力C.处理(删内存, 删区, 宿主能力C.功能_删目录) == 宿主能力C.状态_目录不空,
                    宿主能力C.说明(宿主能力C.状态_目录不空));

                string 一个文件 = Path.Combine(工作, "一个文件.txt");
                File.WriteAllText(一个文件, "内容");
                var (文件删内存, 文件删区) = 造路径请求(一个文件);
                记录("目录操作 给 `删目录` 传文件 → 状态『不是目录』(说清该用 删文件)",
                    宿主能力C.处理(文件删内存, 文件删区, 宿主能力C.功能_删目录) == 宿主能力C.状态_不是目录,
                    宿主能力C.说明(宿主能力C.状态_不是目录));

                var (搬内存, 搬区) = 造路径请求(Path.Combine(工作, "没有这个.txt"), Path.Combine(工作, "目标.txt"));
                记录("目录操作 移动/复制的源不存在 → 状态『打不开』,不当成成功",
                    宿主能力C.处理(搬内存, 搬区, 宿主能力C.功能_移动到) == 宿主能力C.状态_打不开
                    && 宿主能力C.处理(搬内存, 搬区, 宿主能力C.功能_复制到) == 宿主能力C.状态_打不开, "源不存在");

                // ---------- ② 走一整条路子(HB 源码):建目录 → 删空目录 → 移动 → 复制 ----------
                string 源目录 = Path.Combine(工作, "源目录");
                string 源子目录 = Path.Combine(工作, "源目录", "子");
                string 副本目录 = Path.Combine(工作, "副本目录");
                Directory.CreateDirectory(源子目录);
                File.WriteAllText(Path.Combine(源子目录, "深.txt"), "深内容");

                string 源 = "字符串 清单;\n" +
                    $"如果 (建目录(\"{斜(Path.Combine(工作, "新目录"))}\")) {{\n输出行(\"建好了\");\n}}\n" +
                    $"如果 (删目录(\"{斜(Path.Combine(工作, "新目录"))}\")) {{\n输出行(\"删空了\");\n}}\n" +
                    // 整棵目录复制(源目录 下面是 子/深.txt)
                    $"如果 (复制到(\"{斜(源目录)}\", \"{斜(副本目录)}\")) {{\n输出行(\"复制好了\");\n}}\n" +
                    // 移动文件(副本目录/子/深.txt → 副本目录/浅.txt)
                    $"如果 (移动到(\"{斜(Path.Combine(副本目录, "子", "深.txt"))}\", \"{斜(Path.Combine(副本目录, "浅.txt"))}\")) {{\n输出行(\"移动好了\");\n}}\n" +
                    // 已经存在 → 假(不覆盖)
                    $"如果 (复制到(\"{斜(Path.Combine(副本目录, "浅.txt"))}\", \"{斜(源目录)}\")) {{\n输出行(\"覆盖了\");\n}} 否则 {{\n输出行(\"没覆盖\");\n}}\n" +
                    // 列目录:副本目录 现在应该只剩 浅.txt
                    $"如果 (列目录(\"{斜(副本目录)}\", 清单, 4096)) {{\n输出行(清单);\n}}\n" +
                    "停止\n";
                var (_, 程序输出) = 运行带输出(源);
                记录("目录操作 HB 程序里整条路子:建目录 → 删空目录 → 整棵目录复制 → 移动文件 → 目标已存在不覆盖",
                    程序输出.Replace("\r\n", "\n") == "建好了\n删空了\n复制好了\n移动好了\n没覆盖\n子\n浅.txt\n",
                    程序输出.Replace("\r\n", "\n").Replace("\n", "|"));
                记录("目录操作 复制目录是**整棵**:子目录与里面的文件都复制过来了,源原样还在",
                    Directory.Exists(Path.Combine(副本目录, "子"))
                    && File.Exists(Path.Combine(副本目录, "浅.txt"))
                    && File.ReadAllText(Path.Combine(副本目录, "浅.txt")) == "深内容"
                    && File.Exists(Path.Combine(源目录, "子", "深.txt")),
                    "副本目录/子 在、副本目录/浅.txt 内容对(它是从复制过来的 副本目录/子/深.txt 移过去的)、源目录/子/深.txt 原样(复制不是搬)");
                记录("目录操作 移动以后旧路径没了、新路径在(移动文件)",
                    !File.Exists(Path.Combine(副本目录, "子", "深.txt")) && File.Exists(Path.Combine(副本目录, "浅.txt")),
                    "旧的没了,新的在");

                // ---------- ③ 移动整个目录 + 失败不写错误槽 ----------
                string 搬家目录 = Path.Combine(工作, "搬家目录");
                string 移动源 = "如果 (移动到(\"" + 斜(副本目录) + "\", \"" + 斜(搬家目录) + "\")) {\n输出行(\"搬好了\");\n}\n停止\n";
                var 移动编 = 编译(移动源);
                var 移动缓冲 = new StringBuilder();
                var 移动解码 = new 文字输出C(文本 => 移动缓冲.Append(文本));
                var 移动机 = new 虚拟机C { 输入源 = () => null, 输出目标 = 移动解码.写, 宿主调用 = 宿主能力C.处理 };
                移动机.运行(移动编);
                移动解码.收尾();
                记录("目录操作 移动整个目录(HB 程序里也一样):旧目录没了、新目录在、错误槽干净",
                    移动缓冲.ToString().Replace("\r\n", "\n") == "搬好了\n"
                    && !Directory.Exists(副本目录) && File.Exists(Path.Combine(搬家目录, "浅.txt"))
                    && string.IsNullOrEmpty(移动编.查运行期报错(移动机.内存)),
                    $"输出={移动缓冲.ToString().Replace("\r\n", "\n").Replace("\n", "|")} 报错={移动编.查运行期报错(移动机.内存)}");

                // ---------- ④ 名字与帮助说明都在 ----------
                记录("目录操作 三个名字进了内建函数名表,且有帮助说明(高亮/补全/中英切换自动跟上)",
                    中间层指令C.内建函数名表.Any(x => x.中文 == "删目录" && x.英文 == "rmdir")
                    && 中间层指令C.内建函数名表.Any(x => x.中文 == "移动到" && x.英文 == "moveto")
                    && 中间层指令C.内建函数名表.Any(x => x.中文 == "复制到" && x.英文 == "copyto")
                    && (中间层指令C.取说明("rmdir") ?? "").Length > 0
                    && (中间层指令C.取说明("moveto") ?? "").Length > 0
                    && (中间层指令C.取说明("copyto") ?? "").Length > 0);
                期望异常("目录操作 参数个数不对 → 报错(说清几个参数)",
                    () => 汇编("测试输出(移动到(\"a.txt\"));\n停止"), "要2个参数");
                期望异常("目录操作 删目录 参数个数不对 → 报错",
                    () => 汇编("测试输出(删目录(\"源目录\", \"副本目录\"));\n停止"), "要1个参数");
            }
            catch (Exception ex) { 记录异常("目录与文件操作自检", ex); }
            finally
            {
                try { if (Directory.Exists(根)) Directory.Delete(根, true); } catch { }
            }
        }

        /// <summary> 造一个"路径类"请求块(路径址/长 [, 第二路径址/长];布局与 `宿主能力C` 那三条一致) </summary>
        private static (byte[] 内存, uint 参数区) 造路径请求(params string[] 串们)
        {
            var 内存 = new byte[4096];
            uint 参数区 = 0x800;
            void 写(uint 址, uint 值)
            {
                内存[址] = (byte)(值 & 0xFF);
                内存[址 + 1] = (byte)((值 >> 8) & 0xFF);
                内存[址 + 2] = (byte)((值 >> 16) & 0xFF);
                内存[址 + 3] = (byte)((值 >> 24) & 0xFF);
            }
            for (int i = 0; i < 串们.Length; i++)
            {
                uint 址 = (uint)(0x100 + i * 0x200);
                var 字节 = Encoding.UTF8.GetBytes(串们[i]);
                Array.Copy(字节, 0, 内存, 址, 字节.Length);
                写(参数区 + (uint)i * 8, 址);
                写(参数区 + (uint)i * 8 + 4, (uint)字节.Length);
            }
            return (内存, 参数区);
        }

        // ================= D3 分块读大文件(第131批) =================
        private static void 分块读自检()
        {
            string 根 = Path.Combine(临时区C.基目录(), "hb_分块读自检");
            int 取到错 = 宿主能力C.状态_成功;
            try
            {
                Directory.CreateDirectory(根);
                // 造一个 1MB 的文件:内容按确定性公式生成(能不能逐字节对得上,一测就知道)
                string 大文件 = Path.Combine(根, "大文件.bin");
                int 总长 = 1024 * 1024;
                var 期望 = new byte[总长];
                for (int i = 0; i < 总长; i++) 期望[i] = (byte)((i * 31 + 7) % 251);
                File.WriteAllBytes(大文件, 期望);
                string 空文件 = Path.Combine(根, "空.bin");
                File.WriteAllBytes(空文件, []);

                // ---------- ① 验收原文:1MB 文件分 10 次读(每次 100KB),与一次读**逐字节一致** ----------
                var 拼起来 = new List<byte>();
                uint 偏移 = 0;
                int 块大小 = 100 * 1024, 读了几块 = 0;
                while (读了几块 <= 100)
                {
                    var (状态, 字节) = 直读一块(大文件, 偏移, (uint)块大小);
                    if (状态 == 宿主能力C.状态_到末尾) break;
                    if (状态 != 宿主能力C.状态_成功) { 取到错 = 状态; break; }
                    拼起来.AddRange(字节);
                    偏移 += (uint)字节.Length;
                    读了几块++;
                }
                记录("分块读 1MB 文件按 100KB 一块读(10 个整块 + 零头):拼起来的字节与一次读**逐字节一致**",
                    取到错 == 宿主能力C.状态_成功 && 读了几块 == 11 && 拼起来.Count == 总长 && 拼起来.SequenceEqual(期望),
                    $"{读了几块} 块 / {拼起来.Count} 字节(期望 {总长} = 10 个整块 + 一块零头),错={取到错}");
                记录("分块读 读到末尾给状态『到末尾』(不抛、不当成功),循环能自然收尾",
                    直读一块(大文件, (uint)总长, 4096).状态 == 宿主能力C.状态_到末尾
                    && 直读一块(大文件, (uint)总长 + 999, 4096).状态 == 宿主能力C.状态_到末尾
                    && 直读一块(空文件, 0, 4096).状态 == 宿主能力C.状态_到末尾,
                    "偏移 ≥ 长度 / 空文件 都算到头");
                记录("分块读 到头那一次把内容变量清空(不把上一块留在里面骗人)",
                    直读一块(大文件, 4096, 4096).状态 == 宿主能力C.状态_成功
                    && 直读一块(大文件, (uint)总长, 4096).内容.Length == 0, "清空");
                记录("分块读 `上限` 是硬上限:要 100 字节就给 100 字节(不多读)",
                    直读一块(大文件, 0, 100) is { 状态: 宿主能力C.状态_成功 } 小
                    && 小.内容.Length == 100, "100 字节");
                记录("分块读 文件不存在 → 状态『打不开』(不当成功)",
                    直读一块(Path.Combine(根, "没有这个.bin"), 0, 100).状态 == 宿主能力C.状态_打不开, "打不开");

                // ---------- ② 走一整条路子(HB 源码):`当` 循环里一块块读,数字节与偏移 ----------
                // 内容用**纯 ASCII**:HB 的 `.长度()` 数的是"文字"不是字节(中文一个字 3 字节),
                // 而这里验的正是字节数,所以一个字符摆一个字节最清楚;另外**不把整文件拼进一个字符串** ——
                // 编译器自己的字符串池只有 32KB,拼 12KB 这类累积会把池吃光(那是语言既有约束,与分块读无关)
                string 小文件 = Path.Combine(根, "小.txt");
                string 小内容 = string.Concat(Enumerable.Range(0, 3000).Select(i => "a" + (i % 10)));
                File.WriteAllText(小文件, 小内容, new UTF8Encoding(false));
                long 小长度 = new FileInfo(小文件).Length;
                string 斜(string 路径) => 路径.Replace('\\', '/');
                string 源 = "字符串 块;\n无符号整数 偏移 = 0;\n无符号整数 总 = 0;\n" +
                    $"当 (读文件块(\"{斜(小文件)}\", 偏移, 块, 1024)) {{\n" +
                    "    总 = 总 + 块.长度();\n" +
                    "    偏移 = 偏移 + 块.长度();\n" +
                    "}\n" +
                    "测试输出(总);\n" +
                    "测试输出(偏移);\n" +
                    $"测试输出(读文件块(\"{斜(小文件)}\", 偏移, 块, 1024));\n" +
                    "停止\n";
                var (_, 程序输出) = 运行带输出(源);
                string 实际 = 程序输出.Replace("\r\n", "\n");
                记录("分块读 HB 程序里整条路子:`当 (读文件块(…))` 拼完整个文件,长度/偏移/末尾都对",
                    实际 == $"{小长度}\n{小长度}\n0\n", 实际.Replace("\n", "|") + $"(期望 {小长度}|{小长度}|0|)");

                // ---------- ③ `读文件` 的上限现在真生效(以前是摆设) ----------
                string 上限源 = $"字符串 内容;\n如果 (读文件(\"{斜(小文件)}\", 内容, 100)) {{\n测试输出(内容.长度());\n}}\n停止\n";
                var (_, 上限输出) = 运行带输出(上限源);
                记录("分块读 顺带修好:`读文件` 的 `上限` 现在是硬上限(以前文件多大读多大)",
                    上限输出.Replace("\r\n", "\n") == "100\n", 上限输出.Replace("\r\n", "\n").Replace("\n", "|"));

                // ---------- ④ 名字/说明/报错 ----------
                记录("分块读 名字进了内建函数名表,且有帮助说明(高亮/补全/中英切换自动跟上)",
                    中间层指令C.内建函数名表.Any(x => x.中文 == "读文件块" && x.英文 == "readchunk")
                    && (中间层指令C.取说明("readchunk") ?? "").Length > 0);
                期望异常("分块读 参数个数不对 → 报错(说清四个参数)",
                    () => 汇编("字符串 块;\n测试输出(读文件块(\"a.txt\", 0, 块));\n停止"), "四个参数");
                期望异常("分块读 上限不是编译期数字 → 报错",
                    () => 汇编("字符串 块;\n整数 上限 = 8;\n测试输出(读文件块(\"a.txt\", 0, 块, 上限));\n停止"), "编译期就定下来的数字");
            }
            catch (Exception ex) { 记录异常("分块读自检", ex); }
            finally
            {
                try { if (Directory.Exists(根)) Directory.Delete(根, true); } catch { }
            }
        }

        /// <summary> 直接问宿主能力层:从 路径 的第 偏移 字节起读 上限 字节 → (状态, 读到的内容) </summary>
        private static (int 状态, byte[] 内容) 直读一块(string 路径, uint 偏移, uint 上限)
        {
            var 内存 = new byte[2 * 1024 * 1024];
            uint 参数区 = 0x1000, 路径址 = 0x100, 头址 = 0x800, 数据址 = 0x100000;
            uint 池指针槽 = 0x900, 池末槽 = 0x904, 池起 = 0x120000, 池末 = 0x1F0000;
            var 路径字节 = Encoding.UTF8.GetBytes(路径);
            Array.Copy(路径字节, 0, 内存, 路径址, 路径字节.Length);
            void 写(uint 址, uint 值)
            {
                内存[址] = (byte)(值 & 0xFF);
                内存[址 + 1] = (byte)((值 >> 8) & 0xFF);
                内存[址 + 2] = (byte)((值 >> 16) & 0xFF);
                内存[址 + 3] = (byte)((值 >> 24) & 0xFF);
            }
            写(头址, 数据址);
            写(头址 + 4, 0);
            写(头址 + 8, 200 * 1024);
            写(池指针槽, 池起);
            写(池末槽, 池末);
            写(参数区 + 0, 路径址);
            写(参数区 + 4, (uint)路径字节.Length);
            写(参数区 + 8, 头址);
            写(参数区 + 12, 池指针槽);
            写(参数区 + 16, 池末槽);
            写(参数区 + 20, 偏移);
            写(参数区 + 24, 上限);
            int 状态 = 宿主能力C.处理(内存, 参数区, 宿主能力C.功能_读文件块);
            // 按**字节**取内容(字符串变量就是"数据地址 + 长度"):二进制文件不能过 UTF-8 解码再编码,
            // 那样非法序列会变成替换符、字节数就不一样了(踩过:1MB 比出来 1082660)
            uint 址 = (uint)(内存[头址] | (内存[头址 + 1] << 8) | (内存[头址 + 2] << 16) | (内存[头址 + 3] << 24));
            uint 长 = (uint)(内存[头址 + 4] | (内存[头址 + 5] << 8) | (内存[头址 + 6] << 16) | (内存[头址 + 7] << 24));
            var 字节 = new byte[长];
            if (长 > 0) Array.Copy(内存, 址, 字节, 0, (int)长);
            return (状态, 字节);
        }
        // ================= D4 系统文件/目录选择器(第132批) =================
        private static void 选择器自检()
        {
            string 根 = Path.Combine(临时区C.基目录(), "hb_选择器自检");
            try
            {
                if (Directory.Exists(根)) Directory.Delete(根, true);
                Directory.CreateDirectory(根);
                string 有工程 = Path.Combine(根, "有工程");
                Directory.CreateDirectory(有工程);
                File.WriteAllText(Path.Combine(有工程, "主程序.hb"), "停止\n");
                File.WriteAllText(Path.Combine(有工程, "试.hbp"), "{ \"名称\": \"试\", \"启动文件\": \"主程序.hb\", \"文件\": [\"主程序.hb\"] }\n");
                string 只有源 = Path.Combine(根, "只有源");
                Directory.CreateDirectory(只有源);
                File.WriteAllText(Path.Combine(只有源, "a.hb"), "停止\n");
                string 空目录 = Path.Combine(根, "空的");
                Directory.CreateDirectory(空目录);

                // ---------- ① 没挂选择器:返回 null(不是"用户取消了"),也不会炸 ----------
                选择器C.清空();
                记录("选择器 没挂(桌面/命令行/手机没装选择器)时:返回 null,而**不是假装用户取消了**",
                    !选择器C.有系统选择器
                    && 选择器C.选目录同步(new 选择请求C { 要目录 = true }) == null
                    && 选择器C.选文件同步(new 选择请求C()) == null,
                    "有选择器=" + 选择器C.有系统选择器);

                // ---------- ② 替身挂上:请求 → 拿到路径,且请求内容原样传下去 ----------
                var 替身 = new 选择器替身C();
                替身.挂上();
                替身.排队路径(Path.Combine(有工程, "试.hbp"));
                var 结果 = 选择器C.选文件同步(new 选择请求C { 标题 = "打开工程文件", 后缀 = [".hbp"] });
                记录("选择器 挂上替身之后:拿到路径,而且标题/后缀/要目录都**原样传给了平台那一层**",
                    选择器C.有文件选择器 && 结果 is { 有路径: true }
                    && string.Equals(结果.路径, Path.Combine(有工程, "试.hbp"), StringComparison.OrdinalIgnoreCase)
                    && 替身.请求记录.Count == 1 && 替身.请求记录[0].标题 == "打开工程文件"
                    && 替身.请求记录[0].后缀.SequenceEqual(new[] { ".hbp" }) && !替身.请求记录[0].要目录,
                    结果 == null ? "(null)" : 结果.说明 + " / " + 替身.请求记录[0].说明);

                // ---------- ③ 用户取消:说得明明白白 ----------
                替身.排队取消("你在系统选择器里按了返回");
                var 取消 = 选择器C.选目录同步(new 选择请求C { 要目录 = true, 标题 = "选工程目录" });
                记录("选择器 用户取消 → 取消标记 + 一句说明(界面直接显示,不用自己猜)",
                    取消 is { 取消: true, 有路径: false } && 取消.说明.Contains("返回")
                    && 替身.请求记录.Count == 2 && 替身.请求记录[1].要目录,
                    取消?.说明 ?? "(null)");

                // ---------- ④ 排队几个答案:按顺序一个个给 ----------
                替身.排队路径(Path.Combine(只有源, "a.hb"));
                替身.排队路径(Path.Combine(空目录));
                var 左结果 = 选择器C.选文件同步(new 选择请求C());
                var 右结果 = 选择器C.选文件同步(new 选择请求C());
                记录("选择器 排队多个答案时按顺序取(替身能演『连着挑几次』的界面流程)",
                    左结果 is { 有路径: true } && 右结果 is { 有路径: true }
                    && 左结果.路径.EndsWith("a.hb", StringComparison.OrdinalIgnoreCase)
                    && 右结果.路径.EndsWith("空的", StringComparison.OrdinalIgnoreCase)
                    && 替身.请求记录.Count == 4,
                    $"{Path.GetFileName(左结果?.路径 ?? "")} → {Path.GetFileName(右结果?.路径 ?? "")}");

                // 答案用完了再问 → null(模拟平台没回应)
                记录("选择器 替身答案用完再问给 null(不糊弄成空路径)",
                    替身.处理(new 选择请求C()).Result == null, "null");

                // ---------- ⑤ 卸掉替身:又回到"没挂" ----------
                替身.卸载();
                记录("选择器 卸载之后又回到『没挂』(换平台/退出工程时不留上一个平台的委托)",
                    !选择器C.有系统选择器 && 选择器C.选文件同步(new 选择请求C()) == null, "已清空");

                // ---------- ⑥ 挑完目录立刻知道"能不能开工" ----------
                var 看工程 = 选择器C.看目录(有工程);
                var 看源 = 选择器C.看目录(只有源);
                var 看空 = 选择器C.看目录(空目录);
                var 看不存在的 = 选择器C.看目录(Path.Combine(根, "没有这个目录"));
                var 看空串 = 选择器C.看目录("");
                记录("选择器 挑完目录能立刻判『能不能当工程目录用』(有 .hbp / 只有 .hb / 都没有 / 不是目录 / 空)",
                    看工程.可用 && 看工程.工程文件.EndsWith("试.hbp", StringComparison.OrdinalIgnoreCase)
                    && 看源.可用 && 看源.工程文件.Length == 0
                    && !看空.可用 && !看不存在的.可用 && !看空串.可用,
                    $"有工程:{看工程.说明} / 只有源:{看源.说明} / 空:{看空.说明} / 不存在:{看不存在的.说明} / 空串:{看空串.说明}");

                // ---------- ⑥-b 挑回来的是 SAF 的**虚拟路径**时也要认(第329批真机抓到的漏改) ----------
                //   真机实测:系统目录挑回来的路径是 `内容://…`,而 `看目录` 当时拿真文件系统的
                //   `Directory.Exists` 去认 ⇒ 挑中了也一律报"这个路径不是目录"。这条钉住"虚拟树里也能开工"。
                {
                    const string 本检查 = "选择器 H64:系统目录(虚拟路径)挑回来也能判『能不能当工程目录用』(别拿真文件系统去认)";
                    var 虚拟替身 = new 内存文件替身C();
                    try
                    {
                        虚拟文件C.挂上(new 路径分派表C().挂("内容://树primary", 虚拟替身));
                        虚拟文件C.写文本("内容://树primary/工程/试.hbp", "{}");
                        虚拟文件C.写文本("内容://树primary/工程/主程序.hb", "停止\n");
                        var 虚拟看 = 选择器C.看目录("内容://树primary/工程");
                        记录(本检查, 虚拟看.可用 && 虚拟看.工程文件.Length > 0,
                            $"虚拟树:{虚拟看.说明} / 工程文件 `{虚拟路径C.显示(虚拟看.工程文件)}`");
                    }
                    catch (Exception ex) { 记录异常(本检查, ex); }
                    finally { 虚拟文件C.摘掉(); }
                }

                // ---------- ⑦ 文案 ----------
                记录("选择器 请求说明写清了『挑目录还是挑文件 + 后缀 + 能不能多选』",
                    选择器C.摘要(new 选择请求C { 要目录 = true }) == "选一个目录"
                    && 选择器C.摘要(new 选择请求C { 后缀 = [".hb", ".hbp"] }).Contains(".hb / .hbp")
                    && 选择器C.摘要(new 选择请求C { 要目录 = true, 可多选 = true }).Contains("可多选"),
                    选择器C.摘要(new 选择请求C { 后缀 = [".hb", ".hbp"], 可多选 = true }));

                // ================= H9:文件选择器多选(第233批) =================

                // ---------- ⑧ 一次挑多个:结果装得下好几条 ----------
                const string 多条名 = "选择器 一次挑多个:结果装得下好几条(路径 = 第一条,条数 = 挑的个数)";
                try
                {
                    var 多 = 选择结果C.由路径表([Path.Combine(有工程, "试.hbp"), Path.Combine(只有源, "a.hb"), 空目录]);
                    记录(多条名,
                        多.有路径 && !多.取消 && 多.条数 == 3 && 多.路径表.Count == 3
                        && string.Equals(多.路径, Path.Combine(有工程, "试.hbp"), StringComparison.OrdinalIgnoreCase)
                        && 多.说明.Contains("3 个"),
                        $"条数 {多.条数} / 路径 {Path.GetFileName(多.路径)} / 说明 {多.说明}");
                }
                catch (Exception ex) { 记录异常(多条名, ex); }

                // ---------- ⑨ 多条路径先清洗:去空白 / 丢空串 / 去重 ----------
                const string 清洗名 = "选择器 多条路径先清洗:去两头空白 / 丢掉空串 / 同一个文件挑两遍只算一条(序数比、不分大小写)";
                try
                {
                    var 洗 = 选择结果C.由路径表(
                        [" " + Path.Combine(有工程, "试.hbp") + " ", "", "   ", Path.Combine(有工程, "试.HBP"), Path.Combine(只有源, "a.hb"), null!]);
                    记录(清洗名,
                        洗.条数 == 2 && 洗.路径表[0].EndsWith("试.hbp", StringComparison.OrdinalIgnoreCase)
                        && 洗.路径表[1].EndsWith("a.hb", StringComparison.OrdinalIgnoreCase)
                        && 洗.路径 == 洗.路径表[0] && 洗.说明.Contains("2 个"),
                        string.Join(" | ", 洗.路径表));
                }
                catch (Exception ex) { 记录异常(清洗名, ex); }

                // ---------- ⑩ 一条都不剩 ⇒ 没选到(不给半截结果) ----------
                const string 全空名 = "选择器 一条都不剩时当成『没选到』(取消标记 + 空路径表,不给半截结果)";
                try
                {
                    var 全空 = 选择结果C.由路径表(["", "   ", null!]);
                    记录(全空名, 全空.取消 && !全空.有路径 && 全空.条数 == 0, 全空.说明);
                }
                catch (Exception ex) { 记录异常(全空名, ex); }

                // ---------- ⑪ 替身能演多选:请求原样传下去,回来那几条顺序不变 ----------
                const string 替身多名 = "选择器 替身能演多选:请求(含『可多选』)原样传下去,拿回来的那几条顺序不变";
                try
                {
                    var 多替身 = new 选择器替身C();
                    多替身.挂上();
                    多替身.排队路径表(Path.Combine(有工程, "试.hbp"), Path.Combine(只有源, "a.hb"));
                    var 多结果 = 选择器C.选文件同步(new 选择请求C { 标题 = "一次挑几个", 后缀 = [".hb"], 可多选 = true });
                    记录(替身多名,
                        多结果 is { 有路径: true, 条数: 2 } && 多替身.请求记录.Count == 1
                        && 多替身.请求记录[0].可多选 && 多替身.请求记录[0].后缀.SequenceEqual(new[] { ".hb" })
                        && 多结果.路径表[0].EndsWith("试.hbp", StringComparison.OrdinalIgnoreCase)
                        && 多结果.路径表[1].EndsWith("a.hb", StringComparison.OrdinalIgnoreCase),
                        多结果 == null ? "(null)" : $"{多结果.条数} 条:{多结果.说明}");
                    多替身.卸载();
                }
                catch (Exception ex) { 记录异常(替身多名, ex); }

                // ---------- ⑫ 老那条单条路没变(直接写 路径 的写法照旧能用) ----------
                const string 单条名 = "选择器 一条的那条老路没变:直接写 路径 时它就是唯一一条(路径表里也只有它)";
                try
                {
                    var 单 = new 选择结果C { 路径 = Path.Combine(有工程, "试.hbp") };
                    记录(单条名,
                        单.有路径 && !单.取消 && 单.条数 == 1 && 单.路径表.Count == 1 && 单.路径 == 单.路径表[0],
                        单.说明);
                }
                catch (Exception ex) { 记录异常(单条名, ex); }

                // ---------- ⑬⑭⑮ 手机那一端:多选真的接到系统那一手、多选进来的文件真参与编译(按源码钉) ----------
                // 手机端 UI 与 MAUI 都不在命令行自检的编译范围里(硬规矩 6 也不许开窗),所以这几条只能读源码文本。
                const string 平台名 = "选择器 手机宿主:请求里说『可多选』才走系统多选那一手(PickMultipleAsync),没说就还是一次一个";
                const string 消费名 = "选择器 手机 IDE:多选进来的那几个跟第一个文件一起编(启动文件排第一)";
                const string 帮助名 = "选择器 帮助《第24节·手机端》写明『打开文件…』一次能挑好几个";
                string? 仓库根 = 找仓库根目录();
                if (仓库根 == null)
                {
                    跳过(平台名, "找不到仓库根(不在工作副本里跑)");
                    跳过(消费名, "找不到仓库根(不在工作副本里跑)");
                    跳过(帮助名, "找不到仓库根(不在工作副本里跑)");
                }
                else
                {
                    try
                    {
                        string 平台源 = File.ReadAllText(Path.Combine(仓库根, "MobileIDE", "手机选择器.cs"));
                        记录(平台名,
                            平台源.Contains("请求?.可多选 == true", StringComparison.Ordinal)
                            && 平台源.Contains("FilePicker.Default.PickMultipleAsync", StringComparison.Ordinal)
                            && 平台源.Contains("选择结果C.由路径表(路径表)", StringComparison.Ordinal),
                            "手机选择器.cs:可多选 → PickMultipleAsync → 由路径表(去空白 / 去重)");
                    }
                    catch (Exception ex) { 记录异常(平台名, ex); }

                    try
                    {
                        string 页源 = File.ReadAllText(Path.Combine(仓库根, "MobileIDE", "MainPage.xaml.cs"));
                        记录(消费名,
                            页源.Contains("可多选: true", StringComparison.Ordinal)
                            && 页源.Contains("_附加文件.AddRange(结果.路径表.Skip(1));", StringComparison.Ordinal)
                            && 页源.Contains("var 文件表 = new List<(string 名称, string 内容)> { (文件名, 源码编辑框.Text ?? \"\") };", StringComparison.Ordinal)
                            && 页源.Contains("var 编 = 前端契约C.服务.编译.汇编多文件带调试(文件表);", StringComparison.Ordinal),
                            "MainPage.xaml.cs:打开文件可多选 → 其余排进 _附加文件 → 汇编时一起进文件表");
                    }
                    catch (Exception ex) { 记录异常(消费名, ex); }

                    try
                    {
                        string 帮助源 = File.ReadAllText(Path.Combine(仓库根, "引擎", "帮助文本C.cs"));
                        记录(帮助名,
                            帮助源.Contains("「打开文件…」**一次可以挑好几个**", StringComparison.Ordinal)
                            && 帮助源.Contains("其余的**跟着一起汇编**", StringComparison.Ordinal),
                            "帮助《第24节·手机端》:一次挑好几个 + 其余跟着一起汇编");
                    }
                    catch (Exception ex) { 记录异常(帮助名, ex); }
                }
            }
            catch (Exception ex) { 记录异常("选择器自检", ex); }
            finally
            {
                选择器C.清空();
                try { if (Directory.Exists(根)) Directory.Delete(根, true); } catch { }
            }
        }
        // ================= 第137批:编辑器悬停查位置的护栏(用户实测的 Invalid document) =================

        /// <summary>
        /// 用户实测:示例 59 转汇编时鼠标一动就抛 `System.ArgumentException: Invalid document`
        /// (`界面控件\编辑器.代码与诊断.cs` 的 `GetPositionFromPoint` 那一行)。
        /// 根因:进/出汇编视图换的是**文档对象**,`TextArea.TextView` 要等一次重新排版才跟上;
        /// 这中间 `TextEditor.Document` 与 `TextView.Document` 不是同一个,AvalonEdit 就抛。
        /// 这条**按源码断言**(纯界面护栏,引擎侧自检够不着):引用比较的护栏与 try/catch 都在,
        /// 谁删了谁就红;顺带钉住 C23"逐步不再展开编辑器"(旧的汇编只读视图整段退场)。
        /// </summary>
        private static void 编辑器悬停护栏自检()
        {
            try
            {
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("编辑器 悬停查位置有护栏(换文档期间不查 + 不外抛)", "工作副本之外跑自检时跳过");
                    跳过("编辑器 逐步不再展开编辑器(C23:只逐条走,编辑器永远是源码)", "工作副本之外跑自检时跳过");
                    return;
                }
                string 诊断路径 = Path.Combine(根, "界面控件", "编辑器.代码与诊断.cs");
                if (!File.Exists(诊断路径))
                {
                    记录("编辑器 悬停查位置有护栏(换文档期间不查 + 不外抛)", false, $"找不到 {诊断路径}");
                    记录("编辑器 逐步不再展开编辑器(C23:只逐条走,编辑器永远是源码)", false, $"找不到 {诊断路径}");
                    return;
                }
                string 诊断 = File.ReadAllText(诊断路径);
                int 护栏数 = 诊断.Split("ReferenceEquals(代码编辑器.TextArea.TextView.Document, doc)").Length - 1;
                记录("编辑器 悬停查位置有护栏:TextView 文档与 Document 对不上就不查(两处入口都有)",
                    护栏数 >= 2 && 诊断.Contains("换文档期间不查位置", StringComparison.Ordinal)
                    && 诊断.Contains("位置 = 代码编辑器.GetPositionFromPoint", StringComparison.Ordinal)
                    && 诊断.Contains("鼠标事件里绝不外抛", StringComparison.Ordinal),
                    $"护栏 {护栏数} 处 / GetPositionFromPoint 外包裹 try-catch");

                string 主窗路径 = Path.Combine(根, "MainWindow.xaml.cs");
                string 主窗 = File.Exists(主窗路径) ? File.ReadAllText(主窗路径) : "";
                string 调试源 = File.ReadAllText(Path.Combine(根, "MainWindow.调试与断点.cs"));
                记录("编辑器 逐步不再展开编辑器(C23:只逐条走,编辑器永远是源码)",
                    主窗.Contains("前端契约C.服务.调试.逐步一次()", StringComparison.Ordinal)
                    && !主窗.Contains("进入汇编调试视图", StringComparison.Ordinal)
                    && !调试源.Contains("进入汇编调试视图", StringComparison.Ordinal)
                    && !调试源.Contains("换单步视图", StringComparison.Ordinal),
                    "旧的「汇编只读视图」整段退场;整篇展开改在新页里看(C20 自动开 / C23 工具栏开)");
            }
            catch (Exception ex) { 记录异常("编辑器悬停护栏自检", ex); }
        }

        // ================= 第141批:编辑器"视口要有界"+"换文档必卸折叠器"(C12 卡死的两个根因) =================

        /// <summary>
        /// 第141批实测定位的根因(用户报"整篇展开到汇编,点了一下整个窗口卡死,没反应"):
        /// <list type="number">
        /// <item>**视口给了无限高** —— `编辑器.xaml` 原来把 `代码框` 套在一层 `ScrollViewer`(外层滚动)里,
        ///       ScrollViewer 量孩子时给的是**无限高**,AvalonEdit 于是把**整篇每一行**都排一遍:
        ///       headless 探针实测展开汇编 5846 行 ⇒ 可视行 5846 / 进一次视图 **7.0 s**(界面上就是"卡死");
        ///       拆掉那层之后 ⇒ 可视行 27 / 进视图 **30 ms**(滚动交给 AvalonEdit 自己,只排看得见的那几十行)。</item>
        /// <item>**折叠器没跟着换文档** —— `FoldingManager` 绑死在装它那一刻的 `TextDocument` 上;
        ///       换文档对象(进/出汇编视图)却不卸它,排版时 `FoldingElementGenerator.StartGeneration`
        ///       抛 `ArgumentException: Invalid document`,**一行可视行都建不出来**(探针实测 可视行 -1)——
        ///       也就是"点下去没反应"。规矩:`卸掉折叠器()` → 换文档 → `装上折叠器()`。</item>
        /// </list>
        /// 这两条都是纯界面的事(引擎侧自检够不着),所以**按源码断言**:谁把外层 ScrollViewer 加回来、
        /// 谁把卸/装折叠器删掉,这里直接红灯。
        /// </summary>
        private static void 编辑器视口与折叠器自检()
        {
            try
            {
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("编辑器 视口要有界(不许给 TextEditor 套外层 ScrollViewer)", "工作副本之外跑自检时跳过");
                    记录("编辑器 折叠边距是替身(无连线)+ 装/卸折叠器这对护栏都在(FoldingManager 绑死在一个 TextDocument 上)",
                        true, "工作副本之外跑自检时跳过");
                    return;
                }
                string 界面 = Path.Combine(根, "界面控件");
                string xaml = File.ReadAllText(Path.Combine(界面, "编辑器.xaml"));
                记录("编辑器 视口要有界(不许给 TextEditor 套外层 ScrollViewer —— C12 卡死根因)",
                    !xaml.Contains("<ScrollViewer", StringComparison.Ordinal)
                    && xaml.Contains("无限高度", StringComparison.Ordinal)
                    && xaml.Contains("可视行 5846", StringComparison.Ordinal),
                    $"编辑器.xaml 里 ScrollViewer {xaml.Split("<ScrollViewer").Length - 1} 处(应为 0)、根因注释在不在");

                string 折叠 = File.ReadAllText(Path.Combine(界面, "编辑器.折叠与外观选项.cs"));
                string 初始化 = File.ReadAllText(Path.Combine(界面, "编辑器.初始化与交互.cs"));
                string 补全 = File.ReadAllText(Path.Combine(界面, "编辑器.补全与外观.cs"));
                记录("编辑器 折叠边距是替身(无连线)+ 装/卸折叠器这对护栏都在(FoldingManager 绑死在一个 TextDocument 上)",
                    !折叠.Contains("折叠器?.Clear()", StringComparison.Ordinal)
                    && 折叠.Contains("无连线折叠边距", StringComparison.Ordinal)
                    && 折叠.Contains("FoldingManager.Uninstall(折叠器)", StringComparison.Ordinal)
                    && 初始化.Contains("装上折叠器();", StringComparison.Ordinal),
                    "构造时装上;`卸掉折叠器` 里手动摘替身边距(Uninstall 不认替身);旧写法 折叠器?.Clear() 已删");
                记录("编辑器 不再有'外层滚动'那套内外同步(C12 拆掉的就是它)",
                    !初始化.Contains("外层滚动.", StringComparison.Ordinal)
                    && !补全.Contains("外层滚动", StringComparison.Ordinal)
                    && !初始化.Contains("内部滚动", StringComparison.Ordinal),
                    $"初始化 {初始化.Split("外层滚动.").Length - 1} 处字段访问 / 补全 {补全.Split("外层滚动").Length - 1} 处(都应为 0)");
            }
            catch (Exception ex) { 记录异常("编辑器视口与折叠器自检", ex); }
        }

        // ================= 第144批:断点红点跟着滚动条跑 + 补全框跑到任务栏 =================

        /// <summary>
        /// 用户实测报的两个 bug(第144批):
        /// <list type="number">
        /// <item>**断点红点跟着滚动条跑**(点编译停止那条黄条是正常的)——
        ///       `断点边距.OnRender` 的纵坐标是 `VisualTop − TextView.VerticalOffset`,画完就不再重画;
        ///       滚动之后红点留在原处、代码滚走了 ⇒ 看过去整篇的红点都在漂。
        ///       修法:订 `VisualLinesChanged` + `ScrollOffsetChanged` 重画(AvalonEdit 自带的
        ///       `LineNumberMargin` 就是这么活的)。不弹窗探针(c16)实测:滚动 0 / 60 / 120 像素时,
        ///       红点修前**始终停在 y=116**(应在 116 → 57 → 看不见),修后跟着代码走。</item>
        /// <item>**智能补全的候选框跑到 Windows 任务栏上** —— 两个原因叠在一起:
        ///       ① `编辑器.xaml` 的 `PlacementTarget` 绑的是 `源代码框`,全仓库没有这个名字
        ///          (探针实测 `PlacementTarget = null`),按编辑器坐标算出来的偏移量落到了兜底目标上;
        ///       ② 落点只算"光标下面 4 像素",下面放不下就把整个框推到编辑区外,而 WPF 的弹窗遇到屏幕底边
        ///          会按贴边规则把整个框对齐到屏幕底边(就是任务栏那一片)。
        ///       修法:目标在构造里钉死成 `代码框` + 落点一律过 `弹窗定位C.算`(放不下翻到光标上面,绝不出编辑区)。</item>
        /// </list>
        /// 落点规则是纯函数,自检直接喂数比;界面那两处只能按源码断言。
        /// </summary>
        private static void 断点与补全框自检()
        {
            try
            {
                // —— ① 落点规则:纯函数喂数(容器 800×400,光标行高 18,弹窗 200×120)——
                var 下面放得下 = 弹窗定位C.算(100, 50, 18, 200, 120, 800, 400);
                记录("补全框 下面放得下就落在光标下面那一行",
                    Math.Abs(下面放得下.X - 100) < 0.01 && Math.Abs(下面放得下.Y - (50 + 18 + 弹窗定位C.间距)) < 0.01,
                    $"落点 ({下面放得下.X:F0}, {下面放得下.Y:F0});应为 (100, {50 + 18 + 弹窗定位C.间距:F0})");

                var 翻到上面 = 弹窗定位C.算(100, 350, 18, 200, 120, 800, 400);
                记录("补全框 下面放不下就翻到光标上面(整框仍在编辑区内)",
                    翻到上面.Y >= 0 && 翻到上面.Y + 120 <= 350 && Math.Abs(翻到上面.Y - (350 - 120 - 弹窗定位C.间距)) < 0.01,
                    $"光标 y=350、框高 120、容器高 400 ⇒ 落点 y={翻到上面.Y:F0}(应为 {350 - 120 - 弹窗定位C.间距:F0};旧写法会给 372,整个框都在编辑区外面)");

                var 上下都放不下 = 弹窗定位C.算(100, 200, 18, 200, 500, 800, 400);
                记录("补全框 框比编辑区还高时贴顶,不越出容器",
                    Math.Abs(上下都放不下.Y) < 0.01,
                    $"框高 500 > 容器高 400 ⇒ 落点 y={上下都放不下.Y:F0}(应为 0;绝不给负数把它甩到屏幕外)");

                var 右边放不下 = 弹窗定位C.算(700, 50, 18, 200, 120, 800, 400);
                var 太宽 = 弹窗定位C.算(700, 50, 18, 900, 120, 800, 400);
                记录("补全框 右边放不下就往左收,宽度超过编辑区时贴左边",
                    右边放不下.X + 200 <= 800 && Math.Abs(太宽.X) < 0.01,
                    $"光标 x=700、框宽 200 ⇒ x={右边放不下.X:F0}(右边不越出);框宽 900 > 800 ⇒ x={太宽.X:F0}(应为 0)");

                // —— ② 界面两处:只能按源码断言 ——
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("编辑器 断点红点跟着滚动重画(订 VisualLinesChanged)", "工作副本之外跑自检时跳过");
                    跳过("编辑器 候选框目标钉死在 代码框 + 落点过 弹窗定位C", "工作副本之外跑自检时跳过");
                    return;
                }
                string 界面 = Path.Combine(根, "界面控件");
                string 边距 = File.ReadAllText(Path.Combine(界面, "断点边距.cs"));
                记录("编辑器 断点红点跟着滚动/换行重画(用户实测:红点跟着滚动条跑)",
                    边距.Contains("VisualLinesChanged +=", StringComparison.Ordinal)
                    && 边距.Contains("ScrollOffsetChanged +=", StringComparison.Ordinal)
                    && 边距.Contains("InvalidateVisual();", StringComparison.Ordinal)
                    && 边距.Contains("protected override void OnTextViewChanged", StringComparison.Ordinal),
                    $"断点边距.cs:VisualLinesChanged {边距.Split("VisualLinesChanged +=").Length - 1} 处、"
                    + $"ScrollOffsetChanged {边距.Split("ScrollOffsetChanged +=").Length - 1} 处(都应为 1)");

                string xaml = File.ReadAllText(Path.Combine(界面, "编辑器.xaml"));
                string 补全 = File.ReadAllText(Path.Combine(界面, "编辑器.补全与外观.cs"));
                string 初始化 = File.ReadAllText(Path.Combine(界面, "编辑器.初始化与交互.cs"));
                记录("编辑器 候选框的放置目标必须是真的控件名(旧写法绑了不存在的 源代码框)",
                    xaml.Contains("PlacementTarget=\"{Binding ElementName=代码框}\"", StringComparison.Ordinal)
                    && !xaml.Contains("ElementName=源代码框", StringComparison.Ordinal)
                    && 初始化.Contains("popupInit.PlacementTarget = 代码编辑器;", StringComparison.Ordinal),
                    $"编辑器.xaml 里绑错名 {xaml.Split("ElementName=源代码框").Length - 1} 处(应为 0);"
                    + $"构造里钉死目标 {(初始化.Contains("popupInit.PlacementTarget = 代码编辑器;", StringComparison.Ordinal) ? "有" : "缺")}");
                记录("编辑器 候选框落点一律过 弹窗定位C(旧的 PointToScreen + FontSize+4 已删)",
                    补全.Contains("弹窗定位C.算(", StringComparison.Ordinal)
                    && 补全.Contains("光标矩形.Y - textView.VerticalOffset", StringComparison.Ordinal)
                    && !补全.Contains(".PointToScreen(", StringComparison.Ordinal)
                    && !补全.Contains("代码编辑器.FontSize + 4", StringComparison.Ordinal),
                    $"补全与外观.cs:弹窗定位C {补全.Split("弹窗定位C.算(").Length - 1} 处、"
                    + $"光标矩形减滚动偏移 {(补全.Contains("光标矩形.Y - textView.VerticalOffset", StringComparison.Ordinal) ? "有" : "缺")}、"
                    + $"PointToScreen 调用 {补全.Split(".PointToScreen(").Length - 1} 处(应为 0)");
            }
            catch (Exception ex) { 记录异常("断点与补全框自检", ex); }
        }

        // ================= 第145批:断点续跑的断言缓冲(+ C23 起断点只剩源码行一种口径) =================

        /// <summary>
        /// 用户实测报的两个 bug(第145批,示例 55):
        /// <list type="number">
        /// <item>**断点续跑后"输出断言"只算最后一段** —— `跑一遍()` 一进来就无条件 `本次程序输出.Clear()`,
        ///       有断点时第二次"执行"(接着跑)又清一遍 ⇒ 断言只比得到断点之后那半截(用户贴的实际输出少了
        ///       `张·三|3|进来是 你好|你好!|98|1|aBc` 这 7 段)。修法:`跑一遍(…, 接上一次的输出)`,
        ///       接着跑那次**不清**缓冲、也不重打项目名头;界面"输出"页同样只有"从头跑"才清。</item>
        /// <item>**汇编单步视图里下的断点存不下来** —— 那种视图里编辑器给的是**展开文本行号**,
        ///       直接存进 `断点.hbd` 就张冠李戴(红点反查对不上、下次编译被 `清失效` 清掉)。
        ///       修法:`执行行映射C.查源行按显示行` 换成源码行再存(与 `刷新断点显示()` 是同一张表的两头)。</item>
        /// </list>
        /// 换算规则是纯函数(自检直接喂真展开表往返比);清缓冲那一格是纯界面的事,只能按源码断言。
        /// </summary>
        private static void 断点续跑与汇编断点自检()
        {
            try
            {
                // —— ① 显示行 → 源码行:拿一份**真展开**往返比 ——
                var 表 = 执行行映射C.建全工程表([("主程序.hb", "整数 初值 = 1;\n测试输出(初值);\n停止")]);
                var 段 = 表.Count > 0 ? 表[0] : null;
                int? 地址 = 段 == null || 段.地址到显示行.Count == 0 ? null : 段.地址到显示行.Keys.OrderBy(x => x).First();
                int 显示行 = 地址.HasValue ? 段!.地址到显示行[地址.Value] : 0;
                int 期望源行 = 地址.HasValue && 段!.地址到源行.TryGetValue(地址.Value, out int 源) ? 源 : 0;
                记录("汇编断点 显示行换回源码行(与 地址到源行 往返一致)",
                    段 != null && 显示行 > 0 && 期望源行 > 0 && 执行行映射C.查源行按显示行(段, 显示行) == 期望源行,
                    $"地址 {地址?.ToString() ?? "-"} / 显示行 {显示行} → 查得 {执行行映射C.查源行按显示行(段, 显示行)}(应为 {期望源行})");

                var 假段 = new 文件映射C
                {
                    文件 = "主程序.hb",
                    地址到显示行 = { [100] = 5, [104] = 6, [108] = 7 },
                    地址到源行 = { [100] = 3, [108] = 3 },
                };
                记录("汇编断点 编译器生成那段(没有源码行)换出来就是 0",
                    执行行映射C.查源行按显示行(假段, 6) == 0 && 执行行映射C.查源行按显示行(假段, 5) == 3,
                    $"显示行 6(生成段)→ {执行行映射C.查源行按显示行(假段, 6)};显示行 5 → {执行行映射C.查源行按显示行(假段, 5)}(应为 3)");
                记录("汇编断点 取不到时给 0(空段 / 第 0 行 / 不存在的显示行)",
                    执行行映射C.查源行按显示行(null, 5) == 0 && 执行行映射C.查源行按显示行(假段, 0) == 0
                    && 执行行映射C.查源行按显示行(假段, 99) == 0, "查不到就 0,绝不硬猜一个行号");

                // —— ② 第161批:跑完停机之后再按 F5 必须重新装载(用户实测"输出断言 实际 <>") ——
                // 判据收在引擎里(`虚拟机C.需要重新装载`),这里喂数比;界面那句按源码断言。
                var 重装 = new 虚拟机C { 输出目标 = _ => { } };
                var 重装码 = new 汇编器C().汇编("加载立即数 R0, 1;\n输出字符 R0;\n停止");
                重装.装载(重装码);
                记录("执行 刚装载还没跑:同一份机器码不用重复装载(卡在等你输入那档靠它不被冲)",
                    !重装.需要重新装载(重装码),
                    $"停机={重装.停机} PC=0x{重装.程序计数器:X} ⇒ 不动它:PC 与输入队列都得留着");
                重装.运行(重装码);
                记录("执行 上一轮已经停机:同一份机器码也要重新装载(这是「实际 <>」那个 bug 的根)",
                    重装.停机 && 重装.需要重新装载(重装码),
                    $"停机={重装.停机} PC=0x{重装.程序计数器:X} ⇒ 不重装就会「停在停机那一条上,一条指令都没跑、输出是空的」");
                记录("执行 换过机器码当然要重新装载(与停机那一条同一个判据)",
                    重装.需要重新装载(new 汇编器C().汇编("停止")) && new 虚拟机C().需要重新装载(重装码),
                    "装的不是这一份 → 要;空虚拟机(机器码是空的)→ 要");

                // —— ③ 界面两处:按源码断言 ——
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("编辑器 接着跑不清输出缓冲(断言要比整个程序)", "工作副本之外跑自检时跳过");
                    跳过("编辑器 C23 起断点只剩源码行一种口径(编辑器不再换成展开汇编)", "工作副本之外跑自检时跳过");
                    跳过("执行 F5 跑完再按 = 重新装载(跑的是从头,不是空转)", "工作副本之外跑自检时跳过");
                    return;
                }
                string 运行 = File.ReadAllText(Path.Combine(根, "MainWindow.运行与调试器.cs"));
                string 断点 = File.ReadAllText(Path.Combine(根, "MainWindow.调试与断点.cs"));
                记录("执行 F5 跑完再按 = 重新装载(跑的是从头,不是空转)",
                    运行.Contains("if (机.需要重新装载(当前机器码))", StringComparison.Ordinal)
                    && 运行.Contains("装载执行机();", StringComparison.Ordinal)
                    && 运行.Contains("装载调试会话();", StringComparison.Ordinal)
                    && !运行.Contains("if (!ReferenceEquals(机.机器码, 当前机器码)) 装载(机);", StringComparison.Ordinal),
                    "跑一遍 那一格用引擎判据;装载走契约(`调试服务C.装载` / `装载会话`),界面不再自己拼『有编译结果而且就是这一份』那两句");
                // —— ④ 装载前必须把工程文件里的 `内存` 设上去(用户实测:F5 跑 `示例60_大内存档` 抛
                //      「机器码 1083320 字节装不进这台虚拟机的内存(1048576 字节)」)——
                //      容量是**随装载帧**带给子进程那一台的(`跨进程虚拟机C.装载` 里 `写.Write(内存大小)`),
                //      调用方不设就一直是默认 1MB。这一格是界面接线,引擎侧没有可喂数的口 ⇒ 按源码断言。
                string 外壳 = File.ReadAllText(Path.Combine(根, "MainWindow.xaml.cs"));
                记录("执行 装载前把工程文件里的 `内存` 交给契约(大内存档 F5 跑得起来)",
                    外壳.Contains("前端契约C.服务.调试.按内存装载(前端契约C.服务.调试.机器, 当前机器码, 当前内存大小);", StringComparison.Ordinal)
                    && 外壳.Contains("前端契约C.服务.调试.会话内存大小 = 当前内存大小;", StringComparison.Ordinal)
                    && !外壳.Contains("机.设内存大小(当前内存大小)", StringComparison.Ordinal),
                    "`装载执行机` 走契约的 `按内存装载`、`装载调试会话` 递 `会话内存大小`;" +
                    "容量随装载帧走,不设就是默认 1MB ⇒ 示例60_大内存档(代码 + 静态数据 1083320 字节)当场抛『装不进这台虚拟机的内存』。" +
                    "**比一比、不一样才设**那两句收在契约里(界面侧不许直接摸引擎:前后端边界棘轮只许少不许多)");
                // ⚠ 第429批(2026-10-13)按**真实写法**更新过一次哨兵:第423批给"F5 在跑时按 = 重新执行"加了一档
                //   `!刚停过`,于是 `bool 接着跑 = …` 从**单行**变成多行 `&&` 链 ⇒ 老哨兵钉的那句
                //   (`bool 接着跑 = 前端契约C.服务.调试.断点个数 > 0`)已经不存在,这一条一直红。
                //   **判据的意图一个字没变**(接着跑 = 同一个会话、输出连着攒;输出断言比的是整个程序):
                //   改的只是**调用点那一段判定的文本**,形参名 `接上一次的输出` 一个字没动。
                //   顺手把"形参那一句"也钉上(原来只靠另外两句间接认它 —— 形参改了名照样绿,那是个漏)。
                记录("编辑器 接着跑不清输出缓冲(输出断言要比整个程序,不是最后一段)",
                    运行.Contains("bool 接上一次的输出 = false", StringComparison.Ordinal)
                    && 运行.Contains("if (!接上一次的输出) 本次程序输出.Clear();", StringComparison.Ordinal)
                    && 运行.Contains("接上一次的输出: 接着跑", StringComparison.Ordinal)
                    && 运行.Contains("bool 接着跑 = !刚停过", StringComparison.Ordinal)
                    && 运行.Contains("&& 前端契约C.服务.调试.断点个数 > 0", StringComparison.Ordinal)
                    && 运行.Contains("&& 前端契约C.服务.调试.会话已执行步数 > 0 && !前端契约C.服务.调试.会话已停机;", StringComparison.Ordinal),
                    $"运行与调试器.cs:接上一次的输出 {运行.Split("接上一次的输出").Length - 1} 处" +
                    "(形参 `bool 接上一次的输出 = false` / 清缓冲那格 `if (!接上一次的输出) 本次程序输出.Clear();` / " +
                    "接着跑那次调用 `接上一次的输出: 接着跑`);接着跑那一档 = 有断点 + 会话跑了一半(已执行步数 > 0 且没停机)," +
                    "而 `!刚停过` 管的是「F5 在跑时按 = 重新执行 ⇒ 从头跑、不接上一次」");
                记录("编辑器 C23 起断点只剩源码行一种口径(编辑器不再换成展开汇编)",
                    !断点.Contains("汇编调试视图", StringComparison.Ordinal)
                    && 断点.Contains("前端契约C.服务.调试.切换断点(全称, 存行)", StringComparison.Ordinal)
                    && !断点.Contains("断点表.切换(全称, 行号)", StringComparison.Ordinal),
                    "调试与断点.cs:红点 / 下断点 / 黄条全按源码行(展开文本行号那条换算路随只读视图一起退场;断点表 H38-2 起住在契约里)");
            }
            catch (Exception ex) { 记录异常("断点续跑与汇编断点自检", ex); }
        }

        // ================= C13:代码折叠(多行 `{}` 都要折;单行不折) =================

        /// <summary>
        /// C13(用户 2026-09-19:"只要出现 `{}` 的都要有折叠;一行写的那种不用"):规则本体在引擎 `折叠区C.算()`,
        /// 这里直接喂源码比区段;界面那两处"怎么贴到 AvalonEdit 上"只能按源码断言。
        /// 用户报"看不见折叠"的两个根因:
        /// <list type="number">
        /// <item>**行号被当成偏移**传给了 `NewFolding(起, 止)` —— AvalonEdit 认的是**字符偏移**,
        ///       拿行号当偏移之后每条折叠都缩成"第 1 行里的一小段"(探针实测 `1-1 / 1-1`),三角点不出来;</item>
        /// <item>**折叠边距装了 2 个** —— `FoldingManager.Install()` 内部自己会挂一个,
        ///       `编辑器.初始化与交互.cs` 里又手加了一个。</item>
        /// </list>
        /// </summary>
        private static void 折叠区自检()
        {
            try
            {
                // —— 规则本体:用 c12 探针那段一模一样的源码(多行函数 / 单行 `如果` / 字符串里的 `{` / 注释里的 `{`) ——
                string 源码 = string.Join("\n", new[]
                {
                    "方法 取全名(字符串 出 结果, 字符串 姓, 字符串 名)",
                    "{",
                    "    结果 = 姓;",
                    "    拼接到(结果, \"·\", 名);",
                    "}",
                    "",
                    "如果 (1 == 1) { 输出行(\"对上\"); }",
                    "",
                    "输出行(\"{\");",
                    "",
                    "如果 (2 == 2)",
                    "{",
                    "    输出行(\"多行块\");",
                    "}",
                    "// 注释里的 { 不算",
                    "停止",
                });
                var 区 = 折叠区C.算(源码);
                var 段 = 区.Select(x => $"{测试行号(源码, x.起始)}-{测试行号(源码, x.结束)}").ToList();
                // 第151批(用户看过实际效果复核):折叠标记**落在 `当 (…)` / 签名那一行**,
                // 不是 `{` 那一行 —— 起点回到"上一行行尾"。
                记录("折叠 多行 { } 折得出来、单行 { } 不折(期望 1-5 / 11-14,起点落在签名 / 条件那一行)",
                    段.SequenceEqual(new[] { "1-5", "11-14" }), $"算出 {段.Count} 段:{string.Join(" / ", 段)}");

                string 字面量 = "输出行(\"{\");\n甲 = 1;\n输出行(\"}\");\n文字 括号 = '{';\n停止";
                var 假块 = 折叠区C.算(字面量);
                记录("折叠 字符串/字符字面量里的 {} 不算块括号", 假块.Count == 0, $"算出 {假块.Count} 段(应为 0)");

                string 单行 = "如果 (真) { 输出行(\"左\"); }\n停止";
                int 单行段 = 折叠区C.算(单行).Count;
                记录("折叠 单行 `{ … }` 不折(用户点名的那种写法)", 单行段 == 0, $"算出 {单行段} 段(应为 0)");

                string 注释文本 = "// 左\n// 右\n左 = 1;\n// 单行注释不该折\n停止";
                var 注释区 = 折叠区C.算(注释文本);
                记录("折叠 连续两行 // 折一段、单行注释不折",
                    注释区.Count == 1 && 测试行号(注释文本, 注释区[0].起始) == 1 && 测试行号(注释文本, 注释区[0].结束) == 2,
                    $"算出 {注释区.Count} 段:{string.Join(" / ", 注释区.Select(x => $"{测试行号(注释文本, x.起始)}-{测试行号(注释文本, x.结束)}"))}");

                string 块文本 = "左 = 1;\n/* 左\n   右 */\n停止";
                var 块 = 折叠区C.算(块文本);
                记录("折叠 跨行 /* */ 折一段",
                    块.Count == 1 && 测试行号(块文本, 块[0].起始) == 2 && 测试行号(块文本, 块[0].结束) == 3,
                    $"算出 {块.Count} 段:{string.Join(" / ", 块.Select(x => $"{测试行号(块文本, x.起始)}-{测试行号(块文本, x.结束)}"))}");

                string 假块注释 = "输出行(\"/*\");\n甲 = 1;\n停止";
                int 假注释段 = 折叠区C.算(假块注释).Count;
                记录("折叠 字符串里的 /* 不算块注释", 假注释段 == 0, $"算出 {假注释段} 段(应为 0)");

                // `{` 独占一行(本项目常见的"花括号另起一行")⇒ 折叠从**上一行行尾**起:
                // 标记落在 `当 (…)` / 函数签名那一行(用户 2026-09-19 复核:要对齐的是这一行),折起来那一行还看得见。
                string 另起一行 = "方法 取数()\n{\n    停止\n}\n停止";
                var 另起 = 折叠区C.算(另起一行);
                记录("折叠 { 独占一行时从上一行行尾起(标记落在 `当 (…)` / 签名那一行)",
                    另起.Count == 1 && 测试行号(另起一行, 另起[0].起始) == 1 && 测试行号(另起一行, 另起[0].结束) == 4,
                    $"算出 {另起.Count} 段:{string.Join(" / ", 另起.Select(x => $"{测试行号(另起一行, x.起始)}-{测试行号(另起一行, x.结束)}"))}");

                // ---- C24(用户 2026-09-20 实测):`{` 跟在同一行尾巴上时,起点取**行首**会把整行签名一起折掉,
                //      折叠后屏幕上只剩一个 `…`(原话:"当 (轮 < 100) { …} 这个折叠后变成 `+ ...`")。
                //      起点必须落在**那个 `{` 自己**上 ⇒ 折点前面的签名文字留在折叠区外,折叠后是 `当 (轮 < 100) …`。
                //      示例 58 第 33 行 / 示例 59 第 64 行就是这种写法,所以拿它们同一句话当样本。
                string 同行 = "当 (轮 < 100) {                              // 累加 100 次\n    轮 = 轮 + 1;\n}\n停止";
                var 同行区 = 折叠区C.算(同行);
                int 花括号位 = 同行.IndexOf('{', StringComparison.Ordinal);
                string 折点前的字 = 同行区.Count == 1 ? 同行[..同行区[0].起始] : "";
                记录("折叠 `{` 跟在同一行尾巴上:起点 = 那个 `{` 自己(整行签名留在折叠区外,折叠后不是光秃秃一个 `…`)",
                    同行区.Count == 1 && 同行区[0].起始 == 花括号位
                    && 折点前的字.Contains("轮 < 100", StringComparison.Ordinal)
                    && 测试行号(同行, 同行区[0].结束) == 3,
                    $"起点偏移 {同行区[0].起始}(行首 0、`{{` 在 {花括号位});折叠区外的行首文字 = 『{折点前的字.Trim()}』;" +
                    $"折叠看不见的行 = {测试行号(同行, 同行区[0].起始)}-{测试行号(同行, 同行区[0].结束)}");

                记录("折叠 空文本 / 只有换行都算出 0 段且不抛异常",
                    折叠区C.算("").Count == 0 && 折叠区C.算("\n\n").Count == 0, "空与空行");

                // —— 界面那两处(纯界面,引擎侧自检够不着,只能按源码钉) ——
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("折叠 界面按字符偏移登记折叠区(不再拿行号当偏移)", "工作副本之外跑自检时跳过");
                    跳过("折叠 折叠边距只许 FoldingManager.Install 自带那一个", "工作副本之外跑自检时跳过");
                    return;
                }
                string 折叠源 = File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.折叠与外观选项.cs"));
                string 初始化源 = File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.初始化与交互.cs"));
                记录("折叠 界面按字符偏移登记折叠区(不再拿行号当偏移)",
                    折叠源.Contains("new ICSharpCode.AvalonEdit.Folding.NewFolding(区[i].起始, 区[i].结束)", StringComparison.Ordinal)
                    && !折叠源.Contains("NewFolding(开.行", StringComparison.Ordinal),
                    "传 `折叠区C` 算好的字符偏移;旧写法 NewFolding(行号, 行号) 已删");
                记录("折叠 折叠边距只许 FoldingManager.Install 自带那一个",
                    !初始化源.Contains("new ICSharpCode.AvalonEdit.Folding.FoldingMargin()", StringComparison.Ordinal),
                    $"编辑器.初始化与交互.cs 里手加折叠边距 {初始化源.Split("new ICSharpCode.AvalonEdit.Folding.FoldingMargin()").Length - 1} 处(应为 0)");
            }
            catch (Exception ex) { 记录异常("折叠区自检", ex); }
        }

        /// <summary> 测试用:字符偏移 → 行号(1 起) </summary>
        private static int 测试行号(string 正文, int 偏移)
        {
            int 行 = 1;
            for (int i = 0; i < 偏移 && i < 正文.Length; i++) if (正文[i] == '\n') 行++;
            return 行;
        }

        // ================= C16 花括号嵌套彩虹色 + C21 页头星号(用户 2026-09-19 点名) =================

        /// <summary>
        /// C16:规则本体在引擎 `花括号层号C.扫()` —— 这里直接喂源码逐条比"哪个 `{` / `}` 在第几层"、
        /// 第 1 层不上色、7 档循环、色表就是"2/3 饱和度那 7 个色相"。
        /// 界面那几处(逐行涂色 / 缓存键 / 页头绑定)按源码钉,与 `折叠区自检` 同一套办法。
        /// </summary>
        private static void 花括号与页头自检()
        {
            try
            {
                // —— C16 规则本体 ——
                // 记法:`{` 自己占的层 = 遇到它之前已开的层数 + 1;`}` 与它配对的 `{` **同层**(先减再记);
                // `每行开头层号` = 那一行**第一个字符处**已经开了几层(所以第 10 行看到的还是 `}` 处理前的 3)。
                string 源码 = string.Join("\n", new[]
                {
                    "方法 取全名()",              // 第 1 行
                    "{",                          // 第 2 行 `{` 第 1 层
                    "    输出行(\"{}\");",        // 第 3 行:字符串里的 `{` `}` 不算
                    "    如果 (真)",              // 第 4 行
                    "    {",                      // 第 5 行 `{` 第 2 层
                    "        如果 (真)",          // 第 6 行
                    "        {",                  // 第 7 行 `{` 第 3 层
                    "            停止",           // 第 8 行
                    "        }",                  // 第 9 行 `}` 与第 7 行那个 `{` 同层(3)
                    "    }",                      // 第 10 行 `}` 与第 5 行那个 `{` 同层(2)
                    "    // 注释里的 }",          // 第 11 行:注释里的不算
                    "}",                          // 第 12 行 `}` 与第 2 行那个 `{` 同层(1)
                });
                var 表 = 花括号层号C.扫(源码);
                记录("花括号 多行嵌套的 `{`/`}` 层号(含跨行函体)",
                    string.Join(",", 花括号层号C.取行括号(表, 2).Select(x => $"{x.列}@{x.层号}")) == "0@1"
                    && string.Join(",", 花括号层号C.取行括号(表, 5).Select(x => $"{x.列}@{x.层号}")) == "4@2"
                    && string.Join(",", 花括号层号C.取行括号(表, 7).Select(x => $"{x.列}@{x.层号}")) == "8@3"
                    && string.Join(",", 花括号层号C.取行括号(表, 9).Select(x => $"{x.列}@{x.层号}")) == "8@3"
                    && string.Join(",", 花括号层号C.取行括号(表, 10).Select(x => $"{x.列}@{x.层号}")) == "4@2"
                    && string.Join(",", 花括号层号C.取行括号(表, 12).Select(x => $"{x.列}@{x.层号}")) == "0@1",
                    $"第2行 {花括号层号C.取行括号(表, 2).Count} 个 / 第5行 {花括号层号C.取行括号(表, 5).Count} 个 / " +
                    $"第7行 {花括号层号C.取行括号(表, 7).Count} 个 / 第12行 {花括号层号C.取行括号(表, 12).Count} 个");

                记录("花括号 字符串 / 字符字面量与注释里的 {} 一律不算",
                    花括号层号C.取行括号(表, 3).Count == 0 && 花括号层号C.取行括号(表, 11).Count == 0,
                    $"第3行(字符串里) {花括号层号C.取行括号(表, 3).Count} 个、第11行(注释里) {花括号层号C.取行括号(表, 11).Count} 个");

                记录("花括号 每行开头层号(第 1 行 1 → 第 5 行 2 → 第 7 行 3 → 第 10 行 3 → 第 12 行 2)",
                    花括号层号C.取层号(表, 1) == 1 && 花括号层号C.取层号(表, 5) == 2 && 花括号层号C.取层号(表, 7) == 3
                    && 花括号层号C.取层号(表, 10) == 3 && 花括号层号C.取层号(表, 12) == 2,
                    $"第1行={花括号层号C.取层号(表, 1)} 第5行={花括号层号C.取层号(表, 5)} 第7行={花括号层号C.取层号(表, 7)} " +
                    $"第10行={花括号层号C.取层号(表, 10)} 第12行={花括号层号C.取层号(表, 12)}");

                // C16-2(用户 2026-09-19 改口径):彩虹色**从第 1 层开始** —— 第 1 层赤、第 7 层紫、
                // 第 8 层又回到赤(7 档一轮);配对的两个括号同色。
                记录("花括号 彩虹从第 1 层开始、7 档循环(第 1 与第 8 层同档)",
                    花括号层号C.取色档(1) == 0
                    && 花括号层号C.取色档(2) == 1
                    && 花括号层号C.取色档(7) == 6
                    && 花括号层号C.取色档(8) == 0
                    && 花括号层号C.取色档(9) == 1
                    && 花括号层号C.取色档(0) == 0          // 越界(0 层)也按第 1 层算:返回值恒在 0~6,绝不返回负数
                    && 花括号层号C.取色(0) == 花括号层号C.取色(7),
                    $"层1→{花括号层号C.取色档(1)} 层2→{花括号层号C.取色档(2)} 层7→{花括号层号C.取色档(7)} " +
                    $"层8→{花括号层号C.取色档(8)} 层9→{花括号层号C.取色档(9)}");

                记录("花括号 空文本 / 只有换行 / 多出来的 `}` 都不抛异常且按第 1 层算",
                    花括号层号C.取层号(花括号层号C.扫(""), 1) == 1
                    && 花括号层号C.扫("\n\n").行括号.Count == 0
                    && 花括号层号C.取行括号(花括号层号C.扫("}\n{"), 1)[0].层号 == 1,
                    "空 / 空行 / 孤立 `}`");

                // —— 色表:7 档各不同 + 亮度 0.5 + 饱和度就是 2/3(沿用 C15 那 7 个色相)——
                // 注意:**"压到 2/3"是照 HLS 定义算出来的**,那个 0.663 不是算飘了 —— HLS 的饱和度是
                // 相对亮度的(diff / (2-2L)),8 位取整后就是 0.663,再回推也只是同一个 2/3。
                var 色 = 花括号层号C.色表;
                bool 都亮半 = 色.All(x => Math.Abs(亮度(x) - 0.5) < 0.01);
                bool 都三分之二 = 色.All(x => Math.Abs(饱和度(x) - 2.0 / 3.0) < 0.005);
                bool 都不同 = 色.Distinct(StringComparer.OrdinalIgnoreCase).Count() == 色.Length;
                记录("花括号 7 档色表:各档不同色 / 亮度 0.5 / 饱和度是 2/3",
                    色.Length == 7 && 都不同 && 都亮半 && 都三分之二,
                    $"{string.Join(" ", 色)};亮度 {string.Join("/", 色.Select(x => 亮度(x).ToString("F2")))};" +
                    $"饱和度 {string.Join("/", 色.Select(x => 饱和度(x).ToString("F3")))}");

                // —— C16-3:缩进导引线(规则在引擎;界面那个渲染器只把列号换算成像素) ——
                // 竖线画在**配对的 `}` 那一列**(用户 2026-09-21 定的基准:彩虹对齐线以结束符为准):
                // `{` 行下半行、中间行整行、`}` 行不画 —— 正好把一对花括号连起来;
                // **这一列上站着字的那一段跳过**(压字不好看,用户点名)。
                string 导引嵌套 = string.Join("\n", new[]
                {
                    "方法 取数()",          // 第 1 行
                    "{",                  // 第 2 行 `{` 第 1 层、第 0 列
                    "    如果 (真 )",      // 第 3 行
                    "    {",              // 第 4 行 `{` 第 2 层、第 4 列
                    "        当 (真 )",    // 第 5 行
                    "        {",          // 第 6 行 `{` 第 3 层、第 8 列
                    "            停止;",   // 第 7 行
                    "        }",          // 第 8 行 `}` 第 3 层(收尾行不画)
                    "    }",              // 第 9 行 `}` 第 2 层(收尾行不画)
                    "}",                  // 第 10 行 `}` 第 1 层(收尾行不画)
                }) + "\n";
                var 导引表 = 缩进导引线C.算(导引嵌套);
                string 导引段们(int 行) => string.Join(",", 缩进导引线C.取行段(导引表, 行)
                    .Select(x => $"{x.层号}:{x.列}@{x.起比例:F1}-{x.止比例:F1}"));
                记录("导引线 从第 1 层起、竖线画在 `}` 那一列、收尾行不画、这一列上有字就跳过(C16-3 / 用户 2026-09-21)",
                    导引段们(1) == ""
                    && 导引段们(2) == ""                                // `{` 自己那一列上站着 `{` → 跳过
                    && 导引段们(3) == "1:0@0.0-1.0"
                    && 导引段们(4) == "1:0@0.0-1.0"                     // 内层 `{` 那一列上有字 → 内层那段跳过
                    && 导引段们(5) == "1:0@0.0-1.0,2:4@0.0-1.0"
                    && 导引段们(6) == "1:0@0.0-1.0,2:4@0.0-1.0"
                    && 导引段们(7) == "1:0@0.0-1.0,2:4@0.0-1.0,3:8@0.0-1.0"
                    && 导引段们(8) == "1:0@0.0-1.0,2:4@0.0-1.0"
                    && 导引段们(9) == "1:0@0.0-1.0"
                    && 导引段们(10) == "",
                    $"2『{导引段们(2)}』 3『{导引段们(3)}』 4『{导引段们(4)}』 6『{导引段们(6)}』 7『{导引段们(7)}』 9『{导引段们(9)}』 10『{导引段们(10)}』");
                // 老写法(`结构 点 {`,`{` 在第 5 列、`}` 在第 0 列):基准取 `}` 那一列 ⇒ 块头那一行被 `结构` 顶掉、
                // 里面两行照画;里面那行要是顶格(`整数 x;` 的 `整` 正压在第 0 列)那一段就不画
                string 导引老写法 = "结构 点 {\n    整数 x;\n    整数 y;\n}\n";
                string 老段们(int 行) => string.Join(",", 缩进导引线C.取行段(缩进导引线C.算(导引老写法), 行)
                    .Select(x => $"{x.层号}:{x.列}@{x.起比例:F1}-{x.止比例:F1}"));
                记录("导引线 老写法(`结构 点 {`)也以 `}` 那一列为基准:块头行的字与顶格行跳过,里面缩进的两行照画",
                    老段们(1) == "" && 老段们(2) == "1:0@0.0-1.0" && 老段们(3) == "1:0@0.0-1.0" && 老段们(4) == ""
                    && 缩进导引线C.算("结构 点 {\n整数 x;\n}\n").Count == 0,
                    $"老写法 1『{老段们(1)}』 2『{老段们(2)}』 4『{老段们(4)}』;顶格那行算出来 " +
                    $"{缩进导引线C.算("结构 点 {\n整数 x;\n}\n").Count} 段");
                记录("导引线 单行 `{ … }` / 字符串与注释里的 `{}` / 空文本都不画",
                    缩进导引线C.算("如果 (真) { 输出行(\"左\"); }\n停止").Count == 0
                    && 缩进导引线C.算("输出行(\"{\");\n停止").Count == 0
                    && 缩进导引线C.算("/* {\n   里面 } */\n停止").Count == 0
                    && 缩进导引线C.算("").Count == 0 && 缩进导引线C.算("\n\n").Count == 0,
                    "单行块 / 字符串里的 `{` / 块注释里的 `{}` / 空文本都算 0 段");
                记录("导引线 颜色跟着括号那一层(与花括号同一套 7 档;透明度够看得见,别再调回淡灰)",
                    花括号层号C.导引线透明度 >= 0xA0
                    && 花括号层号C.取色档(2) == 1 && 花括号层号C.取色档(3) == 2
                    && 花括号层号C.取色(花括号层号C.取色档(2)) == 花括号层号C.取色(1),
                    $"透明度 {花括号层号C.导引线透明度:X2};第 2 / 3 层色档 = {花括号层号C.取色档(2)} / {花括号层号C.取色档(3)}");

                // —— C16 界面那两处:逐行涂色 + 层号进缓存键(纯界面,只能按源码钉)——
                // —— C21 页头星号:口径 = `主程序.hb *` ——
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("花括号 界面逐行涂色 + 层号进缓存键(工作副本之外跳过)", "工作副本之外跑自检时正常");
                    跳过("页头 有未保存更改时标题加 ` *`(工作副本之外跳过)", "工作副本之外跑自检时正常");
                    return;
                }
                string 逐行源 = File.ReadAllText(Path.Combine(根, "界面控件", "AvalonInlineHighlighter.cs"));
                string 增量源 = File.ReadAllText(Path.Combine(根, "引擎", "增量高亮C.cs"));
                string 页模型源 = File.ReadAllText(Path.Combine(根, "选卡控件", "选卡页视图模型.cs"));
                string 主窗Xaml = File.ReadAllText(Path.Combine(根, "MainWindow.xaml"));
                记录("花括号 界面逐行涂色:层号表按文档版本缓存 + 不再有『跳过第 1 层』那一档",
                    逐行源.Contains("花括号层号C.扫(全文)", StringComparison.Ordinal)
                    && 逐行源.Contains("花括号层号C.取色档(层号)", StringComparison.Ordinal)
                    && !逐行源.Contains("色档 < 0", StringComparison.Ordinal),
                    "AvalonInlineHighlighter 里查引擎层号表;取色档不再有 -1(C16-2 彩虹从第 1 层开始)");
                记录("花括号 层号进逐行缓存键(上面几行动了也要重算)",
                    逐行源.Contains("花括号签名(行首层号, 行括号)", StringComparison.Ordinal)
                    && 增量源.Contains("string 花括号签名 = \"\"", StringComparison.Ordinal)
                    && 增量源.Contains("花括号签名 ?? \"\"", StringComparison.Ordinal),
                    "AvalonInlineHighlighter 算签名 / `增量高亮C.取行片段` 收签名并进缓存键");

                // C16-3:导引线那个渲染器(背景层 + 按文档版本缓存 + 只画看得见的那几十行)
                string 导引源 = File.ReadAllText(Path.Combine(根, "界面控件", "缩进导引线渲染.cs"));
                记录("导引线 界面渲染器:背景层 + 按文档版本缓存 + 只遍历可视行 + 颜色跟层号(C16-3)",
                    导引源.Contains("IBackgroundRenderer", StringComparison.Ordinal)
                    && 导引源.Contains("KnownLayer.Background", StringComparison.Ordinal)
                    && 导引源.Contains("缩进导引线C.算(doc.Text)", StringComparison.Ordinal)
                    && 导引源.Contains("foreach (var 可视行 in textView.VisualLines)", StringComparison.Ordinal)
                    && 导引源.Contains("textView.ScrollOffset.X", StringComparison.Ordinal)
                    && 导引源.Contains("VisualTop - textView.VerticalOffset", StringComparison.Ordinal)
                    && 导引源.Contains("花括号层号C.取色档(段.层号)", StringComparison.Ordinal)
                    && 导引源.Contains("高亮器.取花括号线刷(归一)", StringComparison.Ordinal),
                    "缩进导引线渲染:引擎算表 + 只遍历可视行 + 减滚动偏移(文档坐标 -> 视口坐标)+ 按层号取线刷");
                string 高亮源 = File.ReadAllText(Path.Combine(根, "界面控件", "语法高亮C.cs"));
                记录("导引线 颜色 = 括号那一层的色 + 引擎给的透明度(界面不另调色)",
                    高亮源.Contains("_花括号色[归一]", StringComparison.Ordinal)
                    && 高亮源.Contains("花括号层号C.导引线透明度", StringComparison.Ordinal),
                    "语法高亮C.取花括号线刷:同一套 7 档色(H8 起可在选项页里改)+ `花括号层号C.导引线透明度`");

                // C16-3b(第152批):折叠符那一栏那条灰线是 AvalonEdit 折叠边距自己画的,要换掉它
                string 无连线边距源 = File.ReadAllText(Path.Combine(根, "界面控件", "无连线折叠边距.cs"));
                string 折叠外观源 = File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.折叠与外观选项.cs"));
                记录("折叠边距 只留 +/- 标记:替身把 OnRender 空掉(不画 AvalonEdit 那两条范围线)",
                    无连线边距源.Contains("class 无连线折叠边距 : FoldingMargin", StringComparison.Ordinal)
                    && 无连线边距源.Contains("protected override void OnRender", StringComparison.Ordinal)
                    && !无连线边距源.Contains("base.OnRender(", StringComparison.Ordinal),
                    "无连线折叠边距:OnRender 有意不调 base(FoldingMargin 在那里画竖线 + 结束横线)");
                记录("折叠边距 换上去 / 摘下来都接上了(Uninstall 不认得替身,得手动摘)",
                    折叠外观源.Contains("换成无连线边距()", StringComparison.Ordinal)
                    && 折叠外观源.Contains("边距们[i] = 新", StringComparison.Ordinal)
                    && 折叠外观源.Contains("OfType<无连线折叠边距>().ToList()", StringComparison.Ordinal),
                    "装上折叠器 换边距;卸掉折叠器 手动摘替身(免得换文档来回几次越攒越多)");
                记录("导引线 挂到了编辑器上(C16-3)",
                    File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.初始化与交互.cs"))
                        .Contains("导引线渲染 = new 缩进导引线渲染(高亮器);", StringComparison.Ordinal)
                    && File.ReadAllText(Path.Combine(根, "界面控件", "编辑器.初始化与交互.cs"))
                        .Contains("BackgroundRenderers.Add(导引线渲染)", StringComparison.Ordinal),
                    "编辑器.初始化与交互.cs 里随执行高亮/调用处一起挂(带高亮器:线刷要按层号取;存一份给 H8 那个开关)");

                记录("页头 有未保存更改时标题加 ` *`(写法 `主程序.hb *`,保存后消失)",
                    页模型源.Contains("有未保存更改 ? $\"{标题} *\" : 标题 ?? \"\"", StringComparison.Ordinal)
                    && 页模型源.Contains("OnPropertyChanged(nameof(显示标题))", StringComparison.Ordinal)
                    && 主窗Xaml.Contains("{Binding 显示标题", StringComparison.Ordinal),
                    "选卡页视图模型.显示标题 的实现 + 页头绑它");
            }
            catch (Exception ex) { 记录异常("花括号与页头自检", ex); }
        }

        /// <summary> C16 自检用:配色词类C 的颜色 → HLS 的亮度(0~1)。认不了就返回 -1 </summary>
        private static double 亮度(string 颜色)
        {
            var (r, g, b) = 配色词类C.取RGB(颜色);
            if (r < 0) return -1;
            return (Math.Max(r, Math.Max(g, b)) + Math.Min(r, Math.Min(g, b))) / 2.0 / 255.0;
        }

        /// <summary> C16 自检用:配色词类C 的颜色 → HLS 的饱和度(0~1)。认不了就返回 -1 </summary>
        private static double 饱和度(string 颜色)
        {
            var (r, g, b) = 配色词类C.取RGB(颜色);
            if (r < 0) return -1;
            int 大 = Math.Max(r, Math.Max(g, b)), 小 = Math.Min(r, Math.Min(g, b));
            double 亮 = (大 + 小) / 2.0 / 255.0;
            double 差 = (大 - 小) / 255.0;
            if (差 == 0) return 0;
            return 亮 > 0.5 ? 差 / (2 - 2 * 亮) : 差 / (2 * 亮);
        }

        // ================= D5 网络能力(第133批) =================

        /// <summary> 造一个"取网址"请求块(直接问宿主能力层用;布局与 `宿主能力C.处理取网址` 一致) </summary>
        private static (byte[] 内存, uint 参数区, uint 头址) 造网址请求(string 网址, uint 上限, uint 超时毫秒)
        {
            var 内存 = new byte[16384];
            uint 网址址 = 0x100, 头址 = 0x500, 数据址 = 0x600;
            uint 池指针槽 = 0x700, 池末槽 = 0x704, 参数区 = 0x800, 池起 = 0x1000, 池末 = 0x3000;
            var 网址字节 = Encoding.UTF8.GetBytes(网址);
            Array.Copy(网址字节, 0, 内存, 网址址, 网址字节.Length);
            void 写(uint 址, uint 值)
            {
                内存[址] = (byte)(值 & 0xFF);
                内存[址 + 1] = (byte)((值 >> 8) & 0xFF);
                内存[址 + 2] = (byte)((值 >> 16) & 0xFF);
                内存[址 + 3] = (byte)((值 >> 24) & 0xFF);
            }
            写(头址, 数据址);
            写(头址 + 4, 0);
            写(头址 + 8, 64);                 // 初始容量 64:响应更长时会走"从池里换一块"那条路
            写(池指针槽, 池起);
            写(池末槽, 池末);
            写(参数区 + 0, 网址址);
            写(参数区 + 4, (uint)网址字节.Length);
            写(参数区 + 8, 头址);
            写(参数区 + 12, 池指针槽);
            写(参数区 + 16, 池末槽);
            写(参数区 + 20, 超时毫秒);
            写(参数区 + 24, 上限);
            写(参数区 + 28, 0xFFFFFFFF);
            写(参数区 + 32, 0);
            return (内存, 参数区, 头址);
        }

        /// <summary>
        /// 自检用的**本地回环**小服务器:裸 `TcpListener` + 手写 HTTP 响应。
        /// 为什么不用 `HttpListener`:那要走 HTTP.sys,监听地址得先注册 URL ACL(要管理员),
        /// 而裸 TCP 只碰 127.0.0.1 的临时端口 —— **不出网、不装东西、响应字节完全由我们定**,断言才稳定。
        /// </summary>
        private sealed class 回环服务器C : IDisposable
        {
            private readonly System.Net.Sockets.TcpListener _听;
            private readonly System.Threading.Thread _线程;
            private volatile bool _停;

            public int 端口 { get; }

            public 回环服务器C(Func<string, (int 状态码, byte[] 正文)> 应答)
            {
                _听 = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 0);   // 0 = 让系统挑一个空闲端口
                _听.Start();
                端口 = ((System.Net.IPEndPoint)_听.LocalEndpoint).Port;
                _线程 = new System.Threading.Thread(() => 循环(应答)) { IsBackground = true };
                _线程.Start();
            }

            private void 循环(Func<string, (int 状态码, byte[] 正文)> 应答)
            {
                while (!_停)
                {
                    System.Net.Sockets.TcpClient 客;
                    try { 客 = _听.AcceptTcpClient(); }
                    catch { return; }                       // Dispose 里 Stop 掉监听:Accept 抛异常就是收工信号
                    try
                    {
                        using (客)
                        {
                            var 流 = 客.GetStream();
                            var 收 = new MemoryStream();
                            while (true)                    // 读到请求头结束(\r\n\r\n)为止(GET 没有 body)
                            {
                                int b = 流.ReadByte();
                                if (b < 0) break;
                                收.WriteByte((byte)b);
                                byte[] 缓冲 = 收.GetBuffer();
                                int n = (int)收.Length;
                                if (n >= 4 && 缓冲[n - 4] == 13 && 缓冲[n - 3] == 10 && 缓冲[n - 2] == 13 && 缓冲[n - 1] == 10) break;
                            }
                            var (码, 正文) = 应答(Encoding.ASCII.GetString(收.ToArray()));
                            string 头 = $"HTTP/1.1 {码} {状态文本(码)}\r\n" +
                                "Content-Type: text/plain; charset=utf-8\r\n" +
                                $"Content-Length: {正文.Length}\r\nConnection: close\r\n\r\n";
                            流.Write(Encoding.ASCII.GetBytes(头));
                            流.Write(正文);
                            流.Flush();
                        }
                    }
                    catch { /* 客户端提前断开(超时用例就是这样)不算错 */ }
                }
            }

            private static string 状态文本(int 码) => 码 switch
            {
                200 => "OK",
                404 => "Not Found",
                500 => "Internal Server Error",
                _ => "X",
            };

            public void Dispose()
            {
                _停 = true;
                try { _听.Stop(); } catch { }
            }
        }

        private static void 网络能力自检()
        {
            try
            {
                // ---------- ① 白名单:解析(三种写法 + 三类错)/ 命中判据(主机 + 端口;路径不管) ----------
                var 白名单 = 网址白名单C.由文本([
                    "127.0.0.1:8080", "例子.测试", "https://api.example.com",
                    "有 空格", "ftp://只有协议", "主机:99999", "127.0.0.1:8080",
                ]);
                bool 允许(string 网址) => 白名单.允许(new Uri(网址), out _);
                记录("网络 网址白名单解析:认 `主机:端口` / `主机` / `https://主机` 三种写法,重复的悄悄去掉",
                    白名单.项表.Count == 3 && 白名单.文本 == "127.0.0.1:8080、例子.测试、api.example.com",
                    白名单.文本 + " / 表里 " + 白名单.项表.Count + " 条");
                记录("网络 网址白名单解析:空行/带空格/协议不支持/端口越界都**报出来**(不会静默放行)",
                    白名单.问题.Count == 3 && 白名单.问题.All(x => x.Contains("网址")),
                    string.Join(" | ", 白名单.问题));
                记录("网络 白名单只认 `主机 + 端口`(不管路径与查询串;端口留空 = 协议默认端口;主机名不分大小写)",
                    允许("http://127.0.0.1:8080/随便/什么?x=1") && 允许("http://例子.测试/")
                    && 允许("https://API.Example.COM/取值")
                    && !允许("http://127.0.0.1:8081/") && !允许("http://127.0.0.2:8080/")
                    && !允许("ftp://127.0.0.1:8080/"),
                    "127.0.0.1:8080 ✓ / 127.0.0.1:8081 ✗ / 127.0.0.2:8080 ✗ / ftp ✗");

                // ---------- ② 工程文件:`.hbp` 的 `网址` 表能存能读,写错会报 ----------
                string 根 = Path.Combine(临时区C.基目录(), "hb_网络自检");
                if (Directory.Exists(根)) Directory.Delete(根, true);
                Directory.CreateDirectory(根);
                string 工程路径 = Path.Combine(根, "工程.hbp");
                File.WriteAllText(Path.Combine(根, "主程序.hb"), "停止\n");
                var 工程 = new 工程文件C { 名称 = "试网络", 启动文件 = "主程序.hb", 文件 = ["主程序.hb"] };
                工程.网址.AddRange(["127.0.0.1:8080", "写 错了"]);
                工程.保存(工程路径);
                var 重读工程 = 工程文件C.加载(工程路径);
                记录("网络 工程文件的 `网址` 表能存能读(一行一条,原样往返)",
                    重读工程.网址.Count == 2 && 重读工程.网址[0] == "127.0.0.1:8080"
                    && string.Join("|", 重读工程.检查().Where(x => x.Contains("网址"))) .Contains("写 错了"),
                    string.Join(" / ", 重读工程.网址) + " → " + string.Join(" | ", 重读工程.检查().Where(x => x.Contains("网址"))));

                // ---------- ③ 没挂白名单(手机端 / 独立 exe / 没给工程文件)→ 状态『没挂能力』 ----------
                宿主能力C.清运行痕迹();
                var (空内存, 空区, _) = 造网址请求("http://127.0.0.1:1/", 4096, 500);
                记录("网络 没挂白名单时 → 状态『没挂能力』且程序不崩(与 `运行进程` 同一套边界)",
                    宿主能力C.处理(空内存, 空区, 宿主能力C.功能_取网址) == 宿主能力C.状态_没挂能力,
                    宿主能力C.说明(宿主能力C.状态_没挂能力));

                // ---------- ④ 白名单外:连都不连(用替身证明"传输一次都没被调") ----------
                var 调过 = new List<string>();
                网络能力C.传输 = 请求 => { 调过.Add(请求.网址.ToString()); return new 网络应答C { 状态 = 0, HTTP状态码 = 200, 内容 = Encoding.UTF8.GetBytes("替身给的") }; };
                try
                {
                    宿主能力C.设网址白名单(网址白名单C.由文本(["127.0.0.1:8080"]));
                    var (外内存, 外区, _) = 造网址请求("http://127.0.0.1:9999/", 4096, 500);
                    记录("网络 主机端口不在白名单里 → 状态『网址不在白名单』,而且**连试都没试**(替身零调用)",
                        宿主能力C.处理(外内存, 外区, 宿主能力C.功能_取网址) == 宿主能力C.状态_网址不在白名单 && 调过.Count == 0,
                        $"{宿主能力C.说明(宿主能力C.状态_网址不在白名单)}(替身被调 {调过.Count} 次)");

                    var (协内存, 协区, _) = 造网址请求("ftp://127.0.0.1:8080/", 4096, 500);
                    记录("网络 协议不是 http/https → 状态『协议不支持』(不是含糊的『白名单外』)",
                        宿主能力C.处理(协内存, 协区, 宿主能力C.功能_取网址) == 宿主能力C.状态_协议不支持 && 调过.Count == 0,
                        宿主能力C.说明(宿主能力C.状态_协议不支持));

                    var (坏内存, 坏区, _) = 造网址请求("这不是网址", 4096, 500);
                    记录("网络 网址本身写错 → 状态『参数不合法』(说清是参数的问题,不是网络的问题)",
                        宿主能力C.处理(坏内存, 坏区, 宿主能力C.功能_取网址) == 宿主能力C.状态_参数不合法,
                        宿主能力C.说明(宿主能力C.状态_参数不合法));

                    // ---------- ⑤ 白名单内 + 替身:响应体真的写进了那个字符串变量 ----------
                    var (内内存, 内区, 内头址) = 造网址请求("http://127.0.0.1:8080/取值", 4096, 500);
                    int 内状态 = 宿主能力C.处理(内内存, 内区, 宿主能力C.功能_取网址);
                    记录("网络 白名单内 → 替身被调一次,响应体写进字符串变量,HTTP 状态码写回请求块",
                        内状态 == 宿主能力C.状态_成功 && 调过.Count == 1 && 读字符串(内内存, 内头址) == "替身给的"
                        && 宿主能力C.上次网址状态码 == 200,
                        $"状态={内状态} 内容=「{读字符串(内内存, 内头址)}」HTTP={宿主能力C.上次网址状态码}");

                    var (码内存, 码区, _) = 造网址请求("http://127.0.0.1:8080/取值", 4096, 500);
                    宿主能力C.处理(码内存, 码区, 宿主能力C.功能_取网址状态码);
                    记录("网络 `取网址状态码()` 给的是**上一次**的 HTTP 状态码(与 `取退出码()` 一个套路)",
                        (码内存[码区] | (码内存[码区 + 1] << 8) | (码内存[码区 + 2] << 16) | (码内存[码区 + 3] << 24)) == 200,
                        "写回 200");
                }
                finally { 网络能力C.清替身(); }

                // ---------- ⑥ 回环端到端:真走一次 HTTP(200 / 404 / 上限超了 / 超时) ----------
                byte[] 正文 = Encoding.UTF8.GetBytes("来自回环服务器的正文");
                byte[] 大正文 = new byte[5000];
                Array.Fill(大正文, (byte)'x');
                using var 服务器 = new 回环服务器C(请求 => 请求.Contains("/missing") ? (404, Encoding.UTF8.GetBytes("没有这个"))
                    : 请求.Contains("/big") ? (200, 大正文)
                    : (200, 正文));
                using var 慢服务器 = new 回环服务器C(请求 => { System.Threading.Thread.Sleep(3000); return (200, 正文); });
                宿主能力C.设网址白名单(网址白名单C.由文本([$"127.0.0.1:{服务器.端口}", $"127.0.0.1:{慢服务器.端口}"]));

                // 路径一律写 ASCII:网址里的中文会被 HttpClient 转成 %XX,服务器那边按原样路由就对不上了
                var (正内存, 正区, 正头址) = 造网址请求($"http://127.0.0.1:{服务器.端口}/ok", 65536, 5000);
                int 正状态 = 宿主能力C.处理(正内存, 正区, 宿主能力C.功能_取网址);
                记录("网络 回环端到端:200 → 真,响应体(UTF-8 中文)一个字节不差地进字符串变量",
                    正状态 == 宿主能力C.状态_成功 && 读字符串(正内存, 正头址) == "来自回环服务器的正文"
                    && 宿主能力C.上次网址状态码 == 200,
                    $"状态={正状态} 内容=「{读字符串(正内存, 正头址)}」HTTP={宿主能力C.上次网址状态码}");

                var (缺内存, 缺区, _) = 造网址请求($"http://127.0.0.1:{服务器.端口}/missing", 65536, 5000);
                int 缺状态 = 宿主能力C.处理(缺内存, 缺区, 宿主能力C.功能_取网址);
                记录("网络 HTTP 非 2xx(404)→ 假,而且 `取网址状态码()` 给真实状态码(能跟'连不上'分开)",
                    缺状态 == 宿主能力C.状态_响应出错 && 宿主能力C.上次网址状态码 == 404,
                    $"状态={缺状态}({宿主能力C.说明(缺状态)}) / HTTP={宿主能力C.上次网址状态码}");

                var (大内存, 大区, _) = 造网址请求($"http://127.0.0.1:{服务器.端口}/big", 100, 5000);
                int 大状态 = 宿主能力C.处理(大内存, 大区, 宿主能力C.功能_取网址);
                记录("网络 响应超过 `上限` → 状态『放不下』(**不截断**:截断会让人以为拿到了全文)",
                    大状态 == 宿主能力C.状态_放不下,
                    $"状态={大状态}(5000 字节的响应 / 上限 100)");

                var (慢内存, 慢区, _) = 造网址请求($"http://127.0.0.1:{慢服务器.端口}/slow", 65536, 300);
                int 慢状态 = 宿主能力C.处理(慢内存, 慢区, 宿主能力C.功能_取网址);
                记录("网络 超时 → 状态『网络超时』(这次请求被掐掉,程序继续往下走)",
                    慢状态 == 宿主能力C.状态_网络超时, $"状态={慢状态}({宿主能力C.说明(慢状态)})");

                var (连内存, 连区, _) = 造网址请求("http://127.0.0.1:1/nobody", 65536, 3000);
                宿主能力C.设网址白名单(网址白名单C.由文本(["127.0.0.1:1"]));      // 先放行,再看"连不上"这条
                int 连状态 = 宿主能力C.处理(连内存, 连区, 宿主能力C.功能_取网址);
                记录("网络 端口没人听 → 状态『连不上』(网络层的失败与『白名单外』分得清)",
                    连状态 == 宿主能力C.状态_连不上, $"状态={连状态}({宿主能力C.说明(连状态)})");

                // ---------- ⑦ 走一整条路子(HB 源码 → 中间层 → 虚拟机 → 宿主能力) ----------
                宿主能力C.设网址白名单(网址白名单C.由文本([$"127.0.0.1:{服务器.端口}"]));
                string 源 = "字符串 内容;\n" +
                    $"逻辑 成 = 取网址(\"http://127.0.0.1:{服务器.端口}/ok\", 内容, 65536, 5000);\n" +
                    "如果 (成) {\n输出行(内容);\n} 否则 {\n输出行(\"没成\");\n}\n" +
                    "测试输出(取网址状态码());\n停止\n";
                var (_, 程序输出) = 运行带输出(源);
                记录("网络 HB 程序里调用:返回 真 + 内容进字符串变量 + `取网址状态码()` == 200",
                    程序输出.Replace("\r\n", "\n") == "来自回环服务器的正文\n200\n",
                    程序输出.Replace("\r\n", "\n").Replace("\n", "|"));

                string 失败源 = "字符串 内容;\n" +
                    $"逻辑 成 = 取网址(\"http://127.0.0.1:{服务器.端口}/missing\", 内容, 65536, 5000);\n" +
                    "如果 (成) {\n输出行(\"成了\");\n} 否则 {\n输出行(\"没成\");\n}\n" +
                    "测试输出(取网址状态码());\n停止\n";
                var 失败编 = 编译(失败源);
                var 失败缓冲 = new StringBuilder();
                var 失败解码 = new 文字输出C(文本 => 失败缓冲.Append(文本));
                var 失败机 = new 虚拟机C { 输入源 = () => null, 输出目标 = 失败解码.写, 宿主调用 = 宿主能力C.处理 };
                失败机.运行(失败编);
                失败解码.收尾();
                记录("网络 取不到也**不写错误槽、不停机**(与其它宿主能力同一套:失败靠返回值处理)",
                    string.IsNullOrEmpty(失败编.查运行期报错(失败机.内存))
                    && 失败缓冲.ToString().Replace("\r\n", "\n") == "没成\n404\n",
                    $"输出={失败缓冲.ToString().Replace("\r\n", "\n").Replace("\n", "|")} 报错={失败编.查运行期报错(失败机.内存)}");

                // ---------- ⑧ 顺带钉住:字符串里的 `//` 不再是注释(网址能写出来) ----------
                string 带注释 = 代码解析器.去注释("字符串 s = \"http://x/y\"; // 尾巴注释\n");
                记录("网络 字符串里的 `//` 不当注释(以前 `取网址(\"http://…\")` 会被当成注释,网址根本写不出来)",
                    带注释.Contains("http://x/y") && !带注释.Contains("尾巴注释")
                    && 代码解析器.去注释("// 整行注释\n字符串 s = \"a\";").Trim().StartsWith("字符串"),
                    "去注释后:" + 带注释.Trim());

                // ---------- ⑨ 名字/说明都在(高亮 / 补全 / 帮助自动跟上),参数护栏也钉住 ----------
                记录("网络 两个名字进了内建函数名表,且有帮助说明",
                    中间层指令C.内建函数名表.Any(x => x.中文 == "取网址" && x.英文 == "fetch")
                    && 中间层指令C.内建函数名表.Any(x => x.中文 == "取网址状态码" && x.英文 == "httpstatus")
                    && (中间层指令C.取说明("fetch") ?? "").Length > 0
                    && (中间层指令C.取说明("httpstatus") ?? "").Length > 0);
                期望异常("网络 参数个数不对 → 报错(说清四个参数各是什么)",
                    () => 汇编("字符串 内容;\n测试输出(取网址(\"http://127.0.0.1:1/\", 内容, 4096));\n停止"), "四个参数");
                期望异常("网络 收响应体的参数写成字面量 → 报错",
                    () => 汇编("测试输出(取网址(\"http://127.0.0.1:1/\", \"字面量\", 4096, 500));\n停止"), "字符串");
                期望异常("网络 `上限` 写成变量 → 报错(上限必须是编译期数字)",
                    () => 汇编("字符串 内容;\n整数 上限 = 4096;\n测试输出(取网址(\"http://127.0.0.1:1/\", 内容, 上限, 500));\n停止"), "编译期");
            }
            catch (Exception ex) { 记录异常("网络能力自检", ex); }
            finally { 宿主能力C.清运行痕迹(); 网络能力C.清替身(); }
        }
        // ================= 第193批:资源管理器那三条(同文件只开一份 / 右键编译不开汇编页 / 右键补三格) =================
        /// <summary>
        /// 用户 2026-09-21 报的三条(示例 `多文件_跨文件共享`),都落在**解决方案资源管理器**这一块:
        /// <list type="number">
        /// <item>已经在编辑框里开着的文件,再从资源管理器双击还会**开第二份** —— 要求"相同的文件只能打开一份";</item>
        /// <item>资源管理器右键的「编译」**还会顺手开一份汇编代码页** —— 要求与 F5 一样;</item>
        /// <item>右键菜单要补上「添加文件 / 新建项目 / 新建文件」三格。</item>
        /// </list>
        /// ① 的"哪一页算同一个文件"是引擎纯函数(`汇编源码C.找复用页`),真值在汇编源码自检里逐条钉
        /// (其中"同名不同目录算两份"就是为这一条加的);"添加文件"的登记写法也是纯函数
        /// (`工程维护C.工程里的路径写法`)—— 这里喂 5 种写法,并真写一份 `.hbp` 读回来。
        /// 其余是界面接线,**按源码钉**(自检不许开窗口,硬规矩 6)。
        /// </summary>
        private static void 项目树与文件页自检()
        {
            try
            {
                // ---- ①「添加文件」把磁盘上已有的文件登记进工程:工程文件里该写成什么(纯函数) ----
                string 工程目录 = Path.Combine(临时区C.基目录(), "hb添加文件自检", "工程");
                string 里面 = 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "工具.hb"));
                string 子目录里 = 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "子目录", "工具.hb"));
                string 外面 = Path.GetFullPath(Path.Combine(工程目录, "..", "外面.hb")).Replace('\\', '/');
                string 外面的写法 = 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "..", "外面.hb"));
                string 大小写不同 = 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录.ToUpperInvariant(), "工具.hb"));
                string 没工程目录 = 工程维护C.工程里的路径写法("", @"D:\别处\工具.hb");
                记录("添加文件 工程目录里按相对路径登记(含子目录)、工程目录外按绝对路径登记",
                    里面 == "工具.hb" && 子目录里 == "子目录/工具.hb" && 外面的写法 == 外面
                    && 大小写不同 == "工具.hb" && 没工程目录 == "D:/别处/工具.hb",
                    $"里面={里面} 子目录={子目录里} 外面={外面的写法}(应为 {外面}) 大小写不同={大小写不同} 没工程目录={没工程目录}");

                记录("添加文件 按后缀分表:.hb 进 `文件`、.hba 进 `汇编`(C22 那张)、别的进 `资源`",
                    工程维护C.该进哪个表("工具.hb") == "文件"
                    && 工程维护C.该进哪个表(@"子目录\热路径.hba") == 工程维护C.汇编字段
                    && 工程维护C.该进哪个表("热路径.HBA") == 工程维护C.汇编字段
                    && 工程维护C.该进哪个表("图.png") == "资源"
                    && 工程维护C.该进哪个表("") == "资源",
                    "工程树本来就分三种节点:源码 / 汇编源码 / 资源(资源在执行时当输入流,编译时跳过;" +
                    "`.hba` 当源码编会撞标签,必须进 `汇编` 表)");

                // 这些写法真的能进 `.hbp` 对应的那一张表,而且读回来认得(★ 与界面调用同一套)
                string 工程文本 = "{\n  \"名称\": \"示例\",\n  \"启动文件\": \"主程序.hb\",\n  \"文件\": [\n    \"主程序.hb\"\n  ],\n  \"汇编\": [],\n  \"资源\": []\n}\n";
                var 要加 = new List<(string 字段, string 写法)>
                {
                    (工程维护C.该进哪个表("工具.hb"), 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "子目录", "工具.hb"))),
                    (工程维护C.该进哪个表("热路径.hba"), 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "热路径.hba"))),
                    (工程维护C.该进哪个表("图.png"), 工程维护C.工程里的路径写法(工程目录, Path.Combine(工程目录, "图.png"))),
                };
                string 加过 = 工程文本;
                var 说明表 = new List<string>();
                foreach (var (字段, 写法) in 要加)
                {
                    string? 新文本 = 工程维护C.工程文本加项(加过, 字段, 写法, out string 说明);
                    说明表.Add(说明);
                    加过 = 新文本 ?? 加过;
                }
                string 临时 = Path.Combine(临时区C.基目录(), "hb添加文件自检_" + Guid.NewGuid().ToString("N")[..8]);
                try
                {
                    Directory.CreateDirectory(临时);
                    string 工程路径 = Path.Combine(临时, "示例.hbp");
                    File.WriteAllText(工程路径, 加过);
                    var 读回 = 工程文件C.加载(工程路径);
                    记录("添加文件 三张表各进各的(读回来认得;只动数组里那一处,老条目一个字没动)",
                        读回.文件.Count == 2 && 读回.文件.Contains("子目录/工具.hb")
                        && 读回.汇编.Count == 1 && 读回.汇编.Contains("热路径.hba")
                        && 读回.资源.Count == 1 && 读回.资源.Contains("图.png")
                        && 加过.Contains("\"主程序.hb\"", StringComparison.Ordinal),
                        $"{string.Join(" / ", 说明表)};文件 = {string.Join(", ", 读回.文件)};"
                        + $"汇编 = {string.Join(", ", 读回.汇编)};资源 = {string.Join(", ", 读回.资源)}");
                }
                finally { try { Directory.Delete(临时, true); } catch { } }

                // ---- ②③ 界面接线:按源码钉 ----
                string? 示例 = 找示例目录();
                string? 根 = 示例 == null ? null : Directory.GetParent(示例)?.FullName;
                if (根 == null)
                {
                    跳过("项目树 同一个文件只开一份(工作副本之外跑自检时跳过)", "找不到仓库根");
                    跳过("项目树 右键三格(新建项目 / 新建文件 / 添加文件)+ 右键编译不开汇编页(工作副本之外跳过)", "找不到仓库根");
                    return;
                }
                string 编译源 = File.ReadAllText(Path.Combine(根, "MainWindow.项目与编译.cs"));
                string 界面 = File.ReadAllText(Path.Combine(根, "MainWindow.xaml"));

                记录("项目树 同一个文件只开一份:开页前先查,查得到就切过去(不读盘、不开新页)",
                    编译源.Contains("var 常规 = 主视图模型.常规页.ToList();", StringComparison.Ordinal)
                    && 编译源.Contains("int 复用 = 汇编源码C.找复用页([.. 常规.Select(页 => 页.全称)], 全称);", StringComparison.Ordinal)
                    && 编译源.Contains("主视图模型.选中页 = 已有;", StringComparison.Ordinal)
                    && 编译源.Contains("private void 打开文件到标签页(string 全称) => 打开文件到标签页(全称, 临时: false);", StringComparison.Ordinal),
                    "落点在 MainWindow.项目与编译.cs 的 打开文件到标签页(双击项目树 / 打开文件 / 新建文件 / 添加文件 四条路都走它);"
                    + "H61-3 起这一条是 `临时: false` 那一档(普通页)");

                // ---------------- H61-3:VS 式预览标签页(临时页) ----------------
                string 窗口源 = File.ReadAllText(Path.Combine(根, "MainWindow.窗口与文件.cs"));
                string 页模型源 = File.ReadAllText(Path.Combine(根, "选卡控件", "选卡页视图模型.cs"));
                string 主视图源 = File.ReadAllText(Path.Combine(根, "选卡控件", "主视图模型.cs"));
                string 思维导图源 = File.ReadAllText(Path.Combine(根, "MainWindow.思维导图.cs"));
                int 临时开页处 = (编译源 + 窗口源 + 思维导图源).Split("打开文件到标签页(全称, 临时: true)").Length - 1;

                记录("H61-3 预览页 一编辑就固定(临时页 => 普通页;`是临时页` 这面旗只声明在页模型上)",
                    页模型源.Contains("public bool 是临时页", StringComparison.Ordinal)
                    && 页模型源.Contains("if (_是临时页 && 有未保存更改) 是临时页 = false;", StringComparison.Ordinal)
                    && !窗口源.Contains("public bool 是临时页", StringComparison.Ordinal)
                    && !主视图源.Contains("public bool 是临时页", StringComparison.Ordinal),
                    "选卡页视图模型.cs:内容一变(有未保存更改)当场摘掉临时页那面旗 —— 所以"
                    + "「改过的预览页被下一次预览顶掉、改动一起丢」这条路根本不存在;别处没有第二份声明");

                记录("H61-3 预览页 同一时刻只留一个(整页顶掉、位置不变;没有预览页才追加)",
                    主视图源.Contains("public 选卡页视图模型? 临时页 => 常规页.FirstOrDefault(页 => 页.是临时页);", StringComparison.Ordinal)
                    && 主视图源.Contains("public 选卡页视图模型 换临时页(string 标题, string 内容, string 全称)", StringComparison.Ordinal)
                    && 主视图源.Contains("{ 是临时页 = true };", StringComparison.Ordinal)
                    && 主视图源.Contains("选卡页视图模型表[位置] = 新页;", StringComparison.Ordinal)
                    && 窗口源.Contains("if (临时) 页 = 主视图模型.换临时页(文件名, 内容 ?? \"\", 路径);", StringComparison.Ordinal)
                    && 窗口源.Contains("主视图模型.添加(文件名, 内容 ?? \"\", 路径);", StringComparison.Ordinal),
                    "主视图模型.cs 的 临时页 / 换临时页(位置那一格上原地换,不挪到最后);"
                    + "窗口这边临时那一支走 换临时页、普通那一支照旧 添加");

                记录("H61-3 预览页 页头斜体 + 双击标签头(标题以外)固定;双击标题仍是改文件名",
                    界面.Contains("<EventSetter Event=\"MouseDoubleClick\" Handler=\"标签头_双击\"/>", StringComparison.Ordinal)
                    && 界面.Contains("<DataTrigger Binding=\"{Binding 是临时页}\" Value=\"True\">", StringComparison.Ordinal)
                    && 界面.Contains("<Setter Property=\"FontStyle\" Value=\"Italic\"/>", StringComparison.Ordinal)
                    && 窗口源.Contains("private void 标签头_双击(object sender, MouseButtonEventArgs e)", StringComparison.Ordinal)
                    && 窗口源.Contains("if (sender is not FrameworkElement { DataContext: 选卡页视图模型 页 } || !页.是临时页) return;", StringComparison.Ordinal)
                    && 窗口源.Contains("e.Handled = true;", StringComparison.Ordinal)
                    && 窗口源.Contains("页.是临时页 = false;", StringComparison.Ordinal),
                    "MainWindow.xaml(EventSetter + DataTrigger 斜体)+ MainWindow.窗口与文件.cs 的 标签头_双击;"
                    + "标题那条路自己 e.Handled,两下不打架");

                记录("H61-3 预览页 只有导图那一处走临时页(别处一律普通页)",
                    临时开页处 == 1
                    && 思维导图源.Contains("打开文件到标签页(全称, 临时: true);", StringComparison.Ordinal)
                    && 编译源.Contains("if (临时 && 已有.是临时页) 已有.是临时页 = false;", StringComparison.Ordinal)
                    && 帮助文本C.快速上手().Contains("预览页", StringComparison.Ordinal)
                    && 帮助文本C.快速上手().Contains("再双击导图里那一格", StringComparison.Ordinal),
                    $"`临时: true` 全仓只在 MainWindow.思维导图.cs 的 导图跳到 里出现({临时开页处} 处);"
                    + "已有那一份是临时页时再跳一次 = 固定;帮助第1节与第26节都写了这一档");

                // 右键菜单那一块单独切出来查:菜单「文件」里也有同名 handler,拿整份 XAML 查等于没查
                int 菜单起 = 界面.IndexOf("<TreeView.ContextMenu>", StringComparison.Ordinal);
                int 菜单止 = 菜单起 < 0 ? -1 : 界面.IndexOf("</TreeView.ContextMenu>", 菜单起, StringComparison.Ordinal);
                string 右键菜单 = 菜单起 >= 0 && 菜单止 > 菜单起 ? 界面[菜单起..菜单止] : "";
                记录("项目树 右键菜单补上三格(新建项目 / 新建文件 / 添加文件),都接现成那套实现",
                    右键菜单.Contains("Click=\"新建项目_Click\"", StringComparison.Ordinal)
                    && 右键菜单.Contains("Click=\"新建文件_Click\"", StringComparison.Ordinal)
                    && 右键菜单.Contains("Click=\"添加文件_Click\"", StringComparison.Ordinal)
                    && 编译源.Contains("private void 添加文件_Click(object sender, RoutedEventArgs e)", StringComparison.Ordinal)
                    && 编译源.Contains("工程维护C.工程文本加项(工程文本, 字段, 写法, out _)", StringComparison.Ordinal),
                    "三条都写在 TreeView.ContextMenu 里;「添加文件」走 工程维护C 那一处文本增删(注释与排版留着)," +
                    "进哪张表按后缀定(该进哪个表)");

                记录("项目树 右键的「编译」不再走会开汇编页那条路(与 F5 一个口径)",
                    右键菜单.Contains("Click=\"编译启动项目_不开汇编源码页_Click\"", StringComparison.Ordinal)
                    && !右键菜单.Contains("Click=\"编译启动项目_Click\"", StringComparison.Ordinal)
                    && 编译源.Contains("private void 编译启动项目_不开汇编源码页_Click(object sender, RoutedEventArgs e)", StringComparison.Ordinal)
                    && 编译源.Contains("_不开汇编源码页 = true;", StringComparison.Ordinal)
                    && 编译源.Contains("finally { _不开汇编源码页 = false; }", StringComparison.Ordinal),
                    "右键编译 = 同一条 编译启动项目_Click,只把『编完自动开 <文件>_ASM.hba』那一格按住;菜单「运行 → 编译」照旧会开");
            }
            catch (Exception ex) { 记录异常("项目树与文件页自检", ex); }
        }
        #endregion
    }
}
